/* ÇEVİRİ ru · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ru","olay",{
"OLAYLAR_EK16:1955-12-01:0":{"b": ["Войска султана Омана вошли в главные центры внутреннего Омана; ибадитский имамат фактически прекратил существование", "9a9962a5"], "d": ["В декабре 1955 года султан Омана предпринял шаги для восстановления своей власти, и его войска вошли в главные населённые центры внутреннего Омана (Бахла, Изки, Низва); власть ибадитского имамата над внутренним Оманом фактически прекратилась. Источник указывает только месяц; на карте показано 1 декабря 1955 года.", "31f8761e"]},
"OLAYLAR_EK16:1961-06-19:0":{"b": ["Кувейт вышел из-под британского покровительства и обрёл полную независимость", "e9a86d04"], "d": ["Обменом нотами между Кувейтом и Соединённым Королевством 19 июня 1961 года было прекращено британское покровительство, действовавшее с соглашения 1899 года, и Кувейт стал полностью независимым. На карте британский слой над Кувейтом заканчивается в этот день.", "eb64fb65"]},
"OLAYLAR_EK16:1971-09-03:0":{"b": ["Катар провозгласил независимость с окончанием договоров с Великобританией", "8f288cc6"], "d": ["После истечения срока договоров о покровительстве, заключённых с Великобританией, Катар 3 сентября 1971 года провозгласил независимость. На карте британский слой над Дохой заканчивается в этот день.", "997a4b35"]},
"OLAYLAR_EK17:1369-01-01:0":{"b": ["Крепости Истранджи: завоевание Pınarhisar, Кирк-Килисе (Кыркларели) и Визе", "c6b1a9c1"], "d": ["Мурад I, проведший зиму 1369 г. во дворце в Эдирне, весной вновь выступил против Византии и взял крепости Pınarhisar, Кирк-Килисе и Визе у подножия гор Истранджа. Эти завоевания вызвали панику в Константинополе, и император Иоанн V решил отправиться к папе за помощью.", "61aac0e3"]},
"OLAYLAR_EK17:1485-01-01:0":{"b": ["Ташкент перешёл под управление моголистанского хана Юнус-хана", "a37ee010"], "d": ["Во время борьбы за престол между тимуридскими принцами Ташкент и его округа перешли в руки хана Восточного Чагатая (Моголистана) Юнус-хана. Спустя два года, когда Юнус-хан умер, его сменил сын Махмуд-хан; город оставался у моголистанских ханов до 1503 г., когда его взяли узбеки Шейбани-хана.", "07459832"]},
"OLAYLAR_EK17:1504-01-01:0":{"b": ["Бабур оставил Фергану узбекам и ушёл в Кабул", "69df593c"], "d": ["Тимурид Бабур, сын Умар Шайх-мирзы, после войн с Мухаммедом Шейбани-ханом оставил узбекам Фергану, где правил с 1494 г., и, перейдя Гиндукуш, обосновался в Кабуле.", "21d1ed8c"]},
"OLAYLAR_EK17:1513-01-01:0":{"b": ["Пири-реис начертил древнейшую из дошедших до нас карт мира", "6ef941f5"], "d": ["Пири-реис в Галлиполи начертил карту мира, датированную 919 г. х. (1513 г.); по TDV İslâm Ansiklopedisi, среди источников карты были «древние карты, дошедшие до него из восточного и западного мира, и карта Христофора Колумба», то есть считается, что она хранит следы оригинальной навигационной карты Колумба, которая в то время считалась утраченной. Карту он представил Селиму I Грозному в Каире в 923 г. х. (1517 г.). До нас дошла лишь её часть, показывающая западные/атлантические берега (Испанию, Португалию, Западную Африку, восточный берег Южной Америки); эта часть была вновь обнаружена в дворце Топкапы в 1929 г. и входит в список ЮНЕСКО «Память мира».", "78561b0b"]},
"OLAYLAR_EK17:1534-06-01:0":{"b": ["Объединение окрестностей Карса: переход Şüregel, Арпачая и Digor под османское управление", "10f16b5c"], "d": ["Во время Irakeyn Seferi крепости Пасин, Şüregel и Oltu перешли в руки османов; весьма вероятно, что и крепость Карс была присоединена тогда же. Область Арпачая и Digor к северу и востоку от Карса перешла под османский контроль в ходе той же операции.", "f8a4288a"]},
"OLAYLAR_EK17:1538-10-01:0":{"b": ["Конец ширваншахов: Алкас-мирза взял в плен Шахруха, Ширван стал сефевидской провинцией", "e6d64114"], "d": ["Алкас-мирза, посланный шахом Тахмаспом, разграбил Ширван, взял крепость Baykurd и увёл в Тебриз в плен пятнадцатилетнего ширваншаха Шахруха. Так закончилось правление ширваншахов, долго господствовавших в регионе; Ширван стал провинцией Сефевидского государства.", "47532c27"]},
"OLAYLAR_EK17:1552-01-01:0":{"b": ["Расширение Алжирского оджака к Сахаре — обложение данью Тугурта и Уарглы, окончательное завоевание Тлемсена", "705ec920"], "d": ["Согласно статье TDV о Тлемсене, в 960 г. х. (1553 г.) большая армия, отправленная из Алжира под командованием Салих-реиса, окончательно взяла город и положила конец трёхвековой династии Зайянидов. В тот же период (1552 г.) Салих-реис организовал поход на независимые султанаты Тугурт и Варгла; османские силы взяли Тугурт, продвинулись к Варгле, оба султаната были обложены данью; в Бискре на пути был оставлен постоянный османский гарнизон. Так граница Алжирского оджака впервые перешла Телль-Атлас и дошла до сахарского берега. Большое сражение под Мостаганемом произошло не в этом году, а в 1558 г.: Хасан-паша разбил там испанского графа Алькаудете и положил конец испанским наступлениям в Северной Африке.", "da55aa7d"]},
"OLAYLAR_EK17:1557-01-01:0":{"b": ["Основание эялета Хабеш — берег Красного моря перешёл под османское управление", "7dd470ec"], "d": ["Эялет, созданный, чтобы не допустить проникновения Португалии в Красное море через Абиссинию, по статье TDV об эялете Хабеш был официально учреждён 15 шаабана 962 г. х. (5 июля 1555 г.), центром санджака стал Суакин. Оздемир-паша начал операцию осенью 1555 г.; он овладел островами Дахлак, контролировавшими порт Массава, а 2 апреля 1557 г. взял город Массава, затем Аркико. Продолжение завоевания шло переходом провинции Тигре под власть османов в 1558 г. и Дебарвы в 1559 г.", "7bb5b28b"]},
"OLAYLAR_EK17:1606-10-11:0":{"b": ["Седефкяр Мехмед-ага назначен главным архитектором — зодчий мечети Султанахмет", "27b66fce"], "d": ["Мехмед-ага, взятый ко двору по девширме в 1562–63 гг. из албанского городка Эльбасан, воспитавшийся при Мимаре Синане, 11 октября 1606 г. был назначен главным архитектором Османской империи. TDV İslâm Ansiklopedisi приводит слова современного источника, описывающего его как «кроткого нравом, скромного, верного слову, набожного и умного». Мехмед-ага, которому через три года по приказу Ахмеда I предстояло приступить к строительству мечети Султанахмет, оставил обширное наследие — от ремонтных работ у Каабы до множества фонтанов и мечетей в Стамбуле и Эдирне. Распространённое народное предание гласит, что шесть минаретов вызвали спор о «равенстве» с Каабой в Мекке; энциклопедические источники этого не подтверждают и характеризуют решение лишь как «не опробованное до того времени».", "a4c538fd"]},
"OLAYLAR_EK17:1617-11-22:0":{"b": ["Новый падишах Мустафа I: на троне узник «кафеса» с бледным лицом и рассеянным взглядом", "c487b0d1"], "d": ["Мустафа I, взошедший на престол после смерти Ахмеда I, как первый шехзаде, оставленный в живых братом, годами жил запертым во дворце под строгим надзором; TDV İslâm Ansiklopedisi описывает его как «бледнолицего, с редкой бородой, с крупными чёрными глазами и тусклым взглядом» и отмечает, что долгое заключение усугубило его психологическое состояние. Во время этого первого правления, продлившегося девяносто шесть дней, он не мог вести государственные дела; зато, по преданию, часто выезжал на охоту, осматривал верфь и даже бросал в воду золото, наблюдая за рыбами. Корпус янычар и улемы, сочтя его непригодным к правлению, 26 февраля 1618 г. низложили его и посадили на трон четырнадцатилетнего племянника Османа II.", "f2d36b20"]},
"OLAYLAR_EK17:1630-08-19:0":{"b": ["Путевой сон Эвлии Челеби — оговорка «Seyahat» вместо «Şefaat»", "2d863e22"], "d": ["По TDV İslâm Ansiklopedisi, Эвлия Челеби связывает начало своей сорокалетней жизни в странствиях со сном, который он видел в ночь ашуры месяца мухаррам 1040 г. х. (19 августа 1630 г.): во сне в стамбульской мечети Ahî Çelebi он видит Пророка в окружении большого собрания и от волнения вместо «şefaat yâ Resûlellah» говорит «seyahat yâ Resûlellah». По преданию, Пророк, улыбнувшись этой оговорке, обещает ему и заступничество, и странствия, и паломничество. Он никогда не женился и посвятил жизнь этому обещанию «странствий».", "ede1feb4"]},
"OLAYLAR_EK17:1632-01-01:0":{"b": ["Противоречия Мурада IV: падишах, пристрастный к вину, — запрет на вино, борцовская рука, слух композитора", "3d2ea5e0"], "d": ["В первые годы Мурада IV, взошедшего на престол в одиннадцать лет, определяющим было влияние его матери Кёсем-султан; TDV İslâm Ansiklopedisi сообщает, что Кёсем, опасаясь властных наклонностей сына, «направляла его к развлечениям, отвлекала подарками и празднествами». Когда примерно в двадцать лет он фактически взял управление в свои руки, это был высокий, широкоплечий, внушительный правитель — по преданию, он поднимал сильного человека за пояс и несколько раз проносил его по Has Oda. Поразительное противоречие, которое фиксирует TDV, таково: падишах, о котором говорят, что он ненавидел табак и опиум, чрезмерно пристрастен был к вину, однако перед походом запретил кофе, табак, а позднее и само вино; в то же время он обладал познаниями в музыке, достаточными, чтобы сочинять музыку по канонам макама.", "f2aba572"]},
"OLAYLAR_EK17:1632-01-01:1":{"b": ["Полёт Лагари Хасана Челеби на ракете — предание, единственным источником которого служит Эвлия Челеби", "1f02e3f2"], "d": ["По Seyahatnâme Эвлии Челеби, Лагари Хасан Челеби в присутствии Мурада IV на Sarayburnu соорудил из пятидесяти ока пороха семиствольное ракетное устройство и, сказав «Мой падишах, я поручаю тебя Всевышнему, иду беседовать с пророком Исой», сел на ракету. По преданию, поднявшись примерно на 250 метров, Хасан Челеби с помощью приспособлений, похожих на крылья сокола, спланировал в море, доплыл и вернулся к падишаху, а в награду получил сипахийство с жалованьем в семьдесят акче в день.", "ef620ef6"]},
"OLAYLAR_EK17:1638-12-24:0":{"b": ["Кеманкеш Кара Мустафа-паша стал великим визирем — началась эпоха финансовых реформ", "583846a4"], "d": ["Кеманкеш Кара Мустафа-паша, ставший великим визирем 17 шаабана 1048 г. х. (24 декабря 1638 г.) после гибели Таййар Мехмед-паши в Багдадском походе, при султане Ибрагиме проводил жёсткую финансовую дисциплину: сократил численность янычар и сипахов втрое, исправил пробу монеты, ужесточил систему нарха. По приводимой TDV цифре, эта экономия достигла 6000 кисе в год — но такой строгий контроль нажил ему врагов в придворной среде.", "2de299c2"]},
"OLAYLAR_EK17:1639-01-20:0":{"b": ["Мустафа I умер после пятнадцати лет забвения", "b4c872cd"], "d": ["Мустафа I, во второй раз низложенный 10 сентября 1623 г., все пятнадцать лет до самой смерти жил в комнате, где его держали взаперти; об этих годах в источниках нет никаких сведений. Он скончался 15 рамадана 1048 г. х. (20 января 1639 г.) — часть источников считает это естественной смертью, часть утверждает, что приложил руку Мурад IV.", "f153eced"]},
"OLAYLAR_EK17:1644-01-01:0":{"b": ["«Безумный Ибрагим» или волнообразная болезнь?", "2abc230f"], "d": ["TDV İslâm Ansiklopedisi прямо отвергает ярлык «Безумный Ибрагим», распространившийся в XX в.; он отмечает, что в собственных письмах падишах жалуется на боли, отсутствие аппетита, слабость в ногах, ощущение тумана в голове, стеснение в груди и приступы обморока. В то же время последовательные и разумные ответы в процессе низложения противоречат утверждению о постоянной неуравновешенности; делается вывод, что состояние султана «не было постоянным, а протекало с изменяющейся тяжестью». В этот период ответственность Кёсем-султан постепенно возрастала, а то, что приглашённый во дворец Джинджи-ходжа оказывал падишаху духовное утешение «действенными молитвами», усилило его возможность вмешиваться в политику.", "f3705d31"]},
"OLAYLAR_EK17:1647-01-01:0":{"b": ["Соболиный инцидент — меховой налог великого визиря Ахмед-паши подготовил конец Ибрагима", "a2a47d62"], "d": ["Пока увлечение султана Ибрагима собольими мехами и амброй при дворе росло, великий визирь Ахмед-паша около 1647–1648 гг. ввёл практику принудительного сбора с государственных чинов платы за соболий мех; TDV İslâm Ansiklopedisi отмечает, что чиновники видели в этом откровенную «дань». Когда офицеры-янычары коллективно отказались платить, это сопротивление стало прямым толчком к процессу низложения падишаха — собравшиеся утром 7 августа 1648 г. чиновники сначала убили Ахмед-пашу, а на следующий день низложили Ибрагима.", "596c6d08"]},
"OLAYLAR_EK17:1648-05-01:0":{"b": ["«Государством правят женщины» — восстание Варвара Али-паши из Сиваса", "5b027357"], "d": ["Бейлербей Сиваса Варвар Али-паша отказался платить 30.000 курушей, которые Стамбул требовал под названием «байрамийе», заявив, что «годового дохода Сиваса на эту сумму не хватит»; по TDV İslâm Ansiklopedisi, основанием его восстания было утверждение, что из-за нездоровья падишаха государственные дела перешли в руки женщин и что это вызвало нестабильность частой сменой наместников. Хотя в мае 1648 г. он сначала добился военного успеха, он был разбит Ипширом Мустафа-пашой, 20 мая 1648 г. казнён, а его голова отправлена в Стамбул.", "e45166db"]},
"OLAYLAR_EK17:1686-08-30:0":{"b": ["Потеря Нафплиона Венеции — поворотный пункт Морейской войны", "9d400557"], "d": ["По статье TDV о Нафплионе, уцелевшие из мусульманского населения города во время осады бежали на окрестные острова и в Анатолию (1686 г.). По стандартному академическому источнику (Setton, Venice, Austria, and the Turks in the Seventeenth Century), силы Кёнигсмарка в течение двух недель отражали атаки османской деблокирующей армии; когда 29 августа наступление Исмаил-паши закончилось тяжёлым поражением, крепость сдалась через несколько дней. Нафплион был османской землёй, полученной по договору в 1540 г.; с его потерей переход Мореи к Венеции ускорился.", "592908a0"]},
"OLAYLAR_EK17:1687-08-01:0":{"b": ["Мехмед IV отказался от охоты — последняя попытка накануне низложения", "7daa904b"], "d": ["После Мохачского разгрома (август 1687 г.) армия, которой не выплатили жалованья, подняла мятеж и двинулась на Стамбул. Мехмед IV велел казнить Сулейман-пашу, бежавшего с печатью великого визиря, и показал его голову солдатам, а затем раздал охотничье снаряжение и борзых и объявил, что раскаялся, — но этот жест не спас его трон, и через несколько месяцев он был низложен.", "3f079bcd"]},
"OLAYLAR_EK17:1688-01-17:0":{"b": ["Сдача крепости Munkács (Мукачево) Австрии после трёхлетней осады", "ca2efc3d"], "d": ["Крепость Munkács, осаждённая императорскими войсками в конце 1685 г., три года держалась под управлением Илоны Зриньи, жены Имре Текели; по многим опубликованным справочным трудам, крепость сдалась генералу Антонио Карафе 17 января 1688 г. Это было падение одной из последних крупных крепостей османофильского сопротивления в Венгрии на османо-габсбургском фронте.", "d72ac109"]},
"OLAYLAR_EK17:1711-07-21:0":{"b": ["Балтаджи Мехмед-паша и предание о царице Екатерине", "c1b739f1"], "d": ["Популярный рассказ, объясняющий спасение окружённой на Пруте русской армии подарками/подкупом, посланными Екатериной I Балтаджи Мехмед-паше, повторялся на протяжении столетий.", "f28badd1"]},
"OLAYLAR_EK17:1711-07-21:1":{"b": ["Спор об «упущенной возможности» на Пруте — два мнения", "61ee699c"], "d": ["Удовлетворение миром при полном окружении русской армии османской армией стало предметом споров среди историков сразу после заключения договора — по собственному выражению TDV, «стало ясно, что была упущена большая возможность, и этот тезис был активно развит противниками». По мнению критиков, царя можно было взять в плен, а оружие русской армии принять; по мнению защитников, ограниченное ослабление России ради предотвращения усиления Швеции в Северной Европе было «более разумной политикой». TDV излагает обе точки зрения и не принимает ничьей стороны.", "d9f3213c"]},
"OLAYLAR_EK17:1725-01-01:0":{"b": ["Основана учёная/переводческая комиссия из тридцати двух человек", "0e3a713c"], "d": ["В Стамбуле в годы великого визирата Дамада Ибрагим-паши была образована комиссия из тридцати двух учёных-писцов, которую, по выражению TDV, «можно считать академией эпохи». Комиссия переводила на турецкий труды по истории, философии и географии с арабского, персидского, греческого и латинского — в их числе перевод «Физики» Аристотеля Янялы Эсад-эфенди с группой из двадцати пяти человек и то, что поэт Недим возглавил комиссию по переводу истории. День в TDV не указан; год — по оговорке.", "69ac19ac"]},
"OLAYLAR_EK17:1730-11-25:0":{"b": ["Махмуд I заманил Патрону Халила во дворец и устроил ловушку", "6147059f"], "d": ["Спустя семь недель после воцарения Махмуд I через доверенных людей — во дворце Хаджи Бешир-агу, вне его — крымского хана Каплана I Герая — привлёк на свою сторону военачальников и сломил влияние Патроны Халила. 25 ноября 1730 г. приглашённых на встречу в Sünnet Odası дворца Топкапы Патрону Халила, Муслу Беше и Кель Мехмед-агу впустили внутрь; по знаку великого визиря Силахдара Мехмед-паши заранее спрятанные тридцать два вооружённых человека вышли и убили всех троих. Махмуд I тем самым полностью взял под контроль мятеж.", "e3d9bb3d"]},
"OLAYLAR_EK17:1731-01-01:0":{"b": ["Хумбараджи Ахмед-паша (Бонневаль) поставлен во главе Humbaracı Ocağı", "27b0b1d7"], "d": ["Офицер французского происхождения, настоящее имя которого граф Клод-Александр де Бонневаль, прослужив во французской и австрийской армиях, принял в Сараево ислам и взял имя Ахмед, а в 1729 г. нашёл убежище в Османском государстве. Поставленный в 1731 г. при Махмуде I во главе Humbaracı Ocağı (корпус бомбардиров) Ахмед-паша обучал около 300 солдат, доставленных из Боснии, в казарме, построенной им в Üsküdar Ayazma; их число вскоре превысило 600, а сам он преподавал и математику. Его попытка поднять в Венгрии восстание вместе с Ракоци в пользу Франции подорвала его влияние, и в 1738 г. он был сослан в Кастамону. Он умер в Стамбуле 23 мая 1747 г., могила его находится на кладбище Galata Mevlevîhânesi.", "5bfbc961"]},
"OLAYLAR_EK17:1738-08-01:0":{"b": ["Возвращение Смедерева из рук Габсбургов (корона Венгерского королевства) — война 1737–39 гг.", "63dcf604"], "d": ["По статье TDV о Смедереве, крепость, уступленная Австрии в 1717 г. по Пожаревацкому миру, была возвращена в результате османского продвижения на дунайско-савском фронте австро-турецкой войны, начавшейся в 1737 г.; силы Габсбургов (корона Венгерского королевства) могли держаться в районе до августа 1738 г., после чего Смедерево вновь перешло под османское управление. Белградский мир (1739-09-18), который будет подписан через год, закрепит этот выигрыш — вместе с Белградом и северной Сербией.", "9ca857ec"]},
"OLAYLAR_EK17:1738-08-01:1":{"b": ["Возвращение долины Моравы под османское управление — Ягодина, Крагуевац и Чачак", "b219d3c9"], "d": ["С возвращением Смедерева в августе 1738 г. под османское управление вернулась и долина Моравы, лежавшая между Смедерево и основной частью Османской державы: Ягодина, Крагуевац и Чачак с этой даты считаются османскими. Источники не датируют возвращение этих трёх мест отдельно; карта опирается на день Смедерева. Белградский мир (1739-09-18) закрепил это положение.", "4b38fa55"]},
"OLAYLAR_EK17:1789-04-07:0":{"b": ["Абдулхамид I, читая весть о падении Очакова, перенёс паралич и умер", "6ac60365"], "d": ["Согласно статье TDV İslâm Ansiklopedisi об Абдулхамиде I, его здоровье окончательно ухудшилось из-за тяжёлого хода русско-австрийской войны, и он скончался от внезапного паралича во время чтения доклада великого визиря (kâime) о занятии крепости Очаков русскими (11 раджаба 1203 г. х. / 7 апреля 1789 г.). Тело было погребено в тюрбе, построенном им самим в Bahçekapı в Стамбуле. В тот же день на престол взошёл его племянник Селим III.", "e0b9fc27"]},
"OLAYLAR_EK17:1799-01-03:0":{"b": ["Османо-русский оборонительный союз — совместная оборона против Франции", "c87079d1"], "d": ["После вторжения Наполеона в Египет Селим III и русский император Павел I заключили четырнадцатистатейный оборонительный союз на восемь лет. Стороны обязались иметь общих друзей и врагов, оказывать друг другу помощь и не заключать сепаратного мира.", "41183e81"]},
"OLAYLAR_EK17:1799-01-21:0":{"b": ["Османо-сицилийский (неаполитанский) оборонительный союз — общее дело против Франции", "1d2be816"], "d": ["Перед лицом французского вторжения в Италию, на Мальту и в Египет Османская держава и Королевство Обеих Сицилий заключили девятистатейный оборонительный союз. Стороны обязались вести совместную войну, не заключать сепаратного мира и оказывать друг другу помощь на суше и на море.", "5a755b31"]},
"OLAYLAR_EK17:1800-04-02:0":{"b": ["Образована Республика Семи Соединённых островов — Ионические острова под русско-османским покровительством", "08839694"], "d": ["В 1799 г. объединённый русско-османский флот изгнал французов с Ионических островов (крепость Корфу пала 5 марта 1799 г.); по двенадцатистатейной конвенции от 21 марта 1800 г. острова были образованы как Cezâyir-i Seb'a-i Müctemia Cumhuru (Республика Семи островов), автономная во внутренних делах и подчинённая Османской державе во внешних. Период между 1799-03-05 и этим днём — время совместной оккупации.", "a9d3379e"]},
"OLAYLAR_EK17:1807-07-07:0":{"b": ["Тильзит — русские права на Республику Семи островов переданы Франции", "98a78beb"], "d": ["По соглашению между Россией и Францией, достигнутому в Тильзите, Россия уступила Франции свои права на Семь островов; французские войска разместились на островах летом 1807 г., и Республика Семи островов прекратила существование.", "4561dfb9"]},
"OLAYLAR_EK17:1815-11-05:0":{"b": ["Переход Ayamavra и Ионических островов под британское покровительство — порядок после Наполеона", "0af821dc"], "d": ["Ayamavra и остальные Ионические острова, перешедшие к Франции в 1797 г., после окончательного поражения Наполеона по особому договору, подписанному 5 ноября 1815 г. в Париже между Англией, Россией, Австрией и Пруссией, были переданы под британское покровительство под названием «Соединённые Штаты Семи островов» — это документ, отдельный от общего Парижского договора 20 ноября 1815 г. Протекторат продлится до 1864 г., после чего острова будут переданы Греции.", "b76e9e11"]},
"OLAYLAR_EK18:1455-06-20:0":{"b": ["Завоевание Призрена — османский центр санджака в Косове", "f84c220f"], "d": ["4 раджаба 859 г. х. (20 июня 1455 г.) османская армия под командованием султана Мехмеда Завоевателя после войны с сербским деспотом Юрием Бранковичем (в османских источниках — Vılkoğlu) заняла Призрен. Город перешёл от Византии к Сербскому королевству в середине XIII в., был королевской резиденцией при короле Милутине, царе Душане и короле Уроше; после смерти Душана его значение упало. После завоевания он стал центром санджака и сохранял этот статус вплоть до 1912 г., то есть четыре с половиной века. До распада Югославии Призрен был единственным городом на Балканах, где вместе говорили на трёх языках — албанском, турецком и сербском.", "82ab4141"]},
"OLAYLAR_EK19:1789-07-14:0":{"b": ["Падение Бастилии — начало Французской революции", "96e931f1"], "d": ["На фоне гнева, вызванного отставкой министра финансов Неккера королём Людовиком XVI (11 июля 1789 г.), и экономического кризиса парижане с требованием оружия и пороха двинулись к крепости Бастилия. В бою, начавшемся после полудня, крепость, где против более чем трёх тысяч повстанцев было лишь около ста стражников, сдалась около 17:00; несколько человек, включая коменданта Бернара-Рене де Лонэ, были убиты, семь заключённых освобождены. Почти пустая и уже предназначенная к сносу крепость была символом королевского деспотизма — о её падении Людовику XVI, как передают, доложили словами: «Нет, сир, это не бунт, это революция». 14 июля ныне — национальный праздник Франции, и это событие считается символическим началом народного движения, быстро охватившего всю страну, и Французской революции (1789-1799) — революции, которая в следующее десятилетие, разрушив абсолютную монархию, необратимо изменила политическую карту Европы и международное равновесие, в которое входили и Османы.", "ecc8db63"]},
"OLAYLAR_EK20:1315-04-28:0":{"b": ["Мамлюкское войско вступило в Малатью — город перешёл от Ильханов к мамлюкам", "2540363d"], "d": ["Мамлюки отправили на Малатью армию под командованием дамасского наиба Сейфеддина Тенгиза; 22 мухаррама 715 г. х. (28 апреля 1315 г.) армия вошла в город. До этого дня Малатья находилась под властью Ильханов и была ключевым пунктом линии, где к западу от Евфрата соприкасались сферы влияния Ильханов и мамлюков. Переход города из рук в руки показывает продвижение мамлюков к Верхнему Евфрату в долгом противостоянии двух государств. После этой даты Малатья на некоторое время окажется под управлением Eretnaoğulları, а с 1338 г. вновь вернётся под власть мамлюков.", "e762cf2c"]},
"OLAYLAR_EK20:1326-10-09:0":{"b": ["Конец бейлика Eşrefoğulları — Beyşehir и Seydişehir перешли к Hamîdoğulları", "e4e70846"], "d": ["Демирташ, сын эмира Чобана, генерал-губернатора Анатолии при государстве Ильханов, выступил против туркменских бейликов, объявивших о независимости; вступив в Beyşehir, он велел убить Eşrefoğlu Сулейман-шаха, некогда жаловавшегося на него (9 октября 1326 г.). Так закончился бейлик Eşrefoğulları, основанный в конце XIII в. в округе Beyşehir и Seydişehir. Статья TDV о Hamîdoğulları продолжает рассказ: Beyşehir, Seydişehir, Akşehir и Doğanhisar, принадлежавшие устранённым Демирташем Eşrefoğulları, были включены в границы бейлика Hamîd. В том же году Hamîdoğlu Дундар-бей также был выдан Демирташу и убит. Эти земли в 1381 г. будут проданы Мураду I за 80 000 золотых и перейдут под османское управление.", "af867ff8"]},
"OLAYLAR_EK20:1338-01-01:0":{"b": ["Малатья вновь перешла под власть мамлюков — конец управления Eretnaoğulları", "08b80aa2"], "d": ["Малатья, перешедшая под мамлюкское управление в 1315 г., в годы распада государства Ильханов на некоторое время оказалась в руках Eretnaoğulları. Статья TDV «Malatya» передаёт возвращение одним предложением: с 1338 г. город вновь подчинился мамлюкам. Это эпизод тех лет, когда пустота на юго-востоке Анатолии после Ильханов делилась между мамлюками и Эретной.", "fdd56a26"]},
"OLAYLAR_EK20:1344-10-28:0":{"b": ["Потеря порта Измир флотом крестоносцев — морская мощь Aydınoğulları сломлена", "775c65fe"], "d": ["Флот крестоносцев, собранный по побуждению папы Климента VI из кораблей Венеции, Генуи, Кипрского королевства, родосских рыцарей и герцога Наксосского, отнял порт Измир у Aydınoğulları (28 октября 1344 г.). Порт был взят отцом Умур-бея, Мехмед-беем, у генуэзца Мартино Дзаккариа в 1328-1329 гг. и служил базой морской мощи Aydınoğulları на Эгейском море. В сентябре 1334 г. флот крестоносцев, пришедший с той же целью, был вынужден отступить; этот второй поход удался. Умур-бей продолжил сопротивление и, объединившись с другими тюркскими бейликами, 17 января 1345 г. разбил флот крестоносцев, однако порт вернуть не удалось.", "de5df043"]},
"OLAYLAR_EK20:1366-01-01:0":{"b": ["Караманоглу Алаэддин-бей присоединил Конью, Аксарай и Нигде к землям Караманидов", "2b8b0f70"], "d": ["Караманоглу Алаэддин-бей, желая воспользоваться тем, что Мамлюкский султанат покончил с Армянским королевством и присоединил всю Чукурову, а также смутой в государстве Эретна в Центральной Анатолии, присоединил к землям Караманидов прежде всего Конью (1366-1367), а также Niğde Karahisarı (Yeşilhisar), Аксарай, Akşehir, Ilgın, İshaklı и Кайсери. Конья, в силу веса, который она имела как столица сельджуков, была для Караманидов не просто городом, а притязанием на законность власти.", "986c1d2e"]},
"OLAYLAR_EK20:1467-01-01:0":{"b": ["Узун-Хасан покончил с государством Кара-Коюнлу — бассейн озера Ван перешёл к Ак-Коюнлу", "d8d6c2e8"], "d": ["Правитель Ак-Коюнлу Узун-Хасан в 1467 г. застал врасплох своего непримиримого врага, правителя Кара-Коюнлу Джахан-шаха, выступившего против него, и покончил с государством Кара-Коюнлу. С исчезновением Джахан-шаха, правившего с 1438 г., бассейн озера Ван — Ван, Битлис, Bargiri (Muradiye), Hoşap и Kotur — перешёл от Кара-Коюнлу под управление Ак-Коюнлу. Эта победа сделала государство Ак-Коюнлу единственной великой силой в Восточной Анатолии и Иране и поставила Узун-Хасана на путь, который через поколение приведёт его к столкновению с Османами.", "4d0ea428"]},
"OLAYLAR_EK20:1489-03-04:0":{"b": ["Султан Джем доставлен в Рим — дипломатия заложника и 40 000 дукатов в год", "1c6715a8"], "d": ["Папа Иннокентий VIII, договорившись с главой родосских рыцарей Пьером д'Обюссоном, велел доставить султана Джема в Рим (4 марта 1489 г.). Джем 29 июля 1482 г. нашёл убежище на Родосе, оттуда перешёл на земли Савойи и в конце концов оказался под папским присмотром. Баязид II согласился платить рыцарям 40 000 дукатов в год за то, что они держат его брата под стражей, и предоставить им право свободной торговли на османских землях. Эта плата была не данью, а ценой удержания законного соперника за престол в Европе в бездействии: окажись Джем на свободе, он мог бы собрать войско в Анатолии и, сверх того, стать источником законности для крестового похода. Так династический вопрос на тридцать лет стал главным ограничением османской внешней политики — в этом причина осторожного поведения Баязида на Западе. Со смертью Джема в 1495 г. это ограничение исчезло.", "60ca67f8"]},
"OLAYLAR_EK20:1490-01-01:0":{"b": ["Царство Грузия разделилось на три — Картли, Кахети и Имерети с центром в Кутаиси", "f9c5f798"], "d": ["Объединённое Грузинское царство, которым управляла династия Багратидов, после долгой междоусобной борьбы формально распалось на три царства: на востоке Картли с центром в Тбилиси, на северо-востоке Кахети и на западе Имерети с центром в Кутаиси. Статья TDV «Gürcistan» подтверждает раздел: «Грузия разделилась на три царства (Картлия, Кахетия, Имеретия) и пять княжеств». Этот раздел стал решающим в османо-сефевидском соперничестве следующего века: по Амасийскому миру 1555 г. Имерети, Дадиани, Гурия и Дзвели отошли к Османам, а Картли, Кахети и Мосух — к Сефевидам. То есть то, что атлас относит западную и восточную Грузию к разным владыкам, вытекает из этого раздела. Селим I Грозный ещё будучи правителем Трапезунда в 1508 г. подчинил царство Имерети (Açıkbaş) и обложил его данью.", "6b0aaa55"]},
"OLAYLAR_EK20:1510-07-25:0":{"b": ["Занятие Триполи испанцами — конец власти Хафсидов", "de319d23"], "d": ["После Ammâroğulları власть Хафсидов в Триполи продолжалась до 1510 г. В этом году город был занят испанцами под командованием графа Оливетто дона Педро Наварро; мусульмане, уцелевшие после резни, покинули город. Это занятие стало восточным концом цепи крепостей Испании на северо-африканском побережье, от Мелильи до Триполи. Жители Триполи в 925 г. х. (1519) отправят в Константинополь делегацию с просьбой о помощи Османов против испанского вторжения, а город в 1551 г. будет взят Тургут-реисом и Синан-пашой и перейдёт под османское управление.", "f65b0ba2"]},
"OLAYLAR_EK20:1530-03-24:0":{"b": ["Мальта и Триполи переданы рыцарям Святого Иоанна — новая база изгнанного с Родоса ордена", "2595729e"], "d": ["Рыцари Святого Иоанна (госпитальеры), изгнанные с Родоса султаном Сулейманом Кануни в 928 г. х. (1522), после восьми лет без родины были поселены королём Испании и Германии Карлом V на Мальте; тем же даром орден получил и защиту Триполи. Мальта с её идеальными гаванями стала удобной базой для рыцарей, влиятельных на морях: сначала они обосновались в Биргу, укрепили форт Сант-Анджело и построили на оконечности Сенглеи форт Сен-Мишель. Это поселение породило постоянную вражескую базу посреди Средиземного моря, перерезавшую османские морские пути; столкновения, начавшиеся набегом Тургут-реиса на Гозо в 947 г. х. (1540), продлятся до осады Мальты 1565 г.", "3992bdbc"]},
"OLAYLAR_EK20:1648-10-24:0":{"b": ["Вестфальский мир — Тридцатилетняя война закончилась, единство Священной Римской империи распалось", "d7719f05"], "d": ["Договоры, завершившие Тридцатилетнюю войну (1618-1648), были подписаны в один день в Мюнстере и Оснабрюке (24 октября 1648 г.). Около трёхсот княжеств Священной Римской империи получили право вести собственную внешнюю политику; империя перестала быть государством и превратилась в оболочку. Швеция получила Западную Померанию и Штеттин, Бранденбург — Восточную Померанию и право на ожидание архиепископства Магдебургского — здесь начинается накопление земель Гогенцоллернов, которое в 1701 г. приведёт к королевству. Независимость Нидерландов и Швейцарии была официально признана. Для Османов значение косвенное, но большое: когда Габсбурги отошли от западного фронта, в Центральной Европе возникла сила, способная вновь повернуться на восток.", "21478661"]},
"OLAYLAR_EK20:1701-01-18:0":{"b": ["Провозглашено Прусское королевство — Фридрих I коронован в Кёнигсберге", "337a9f74"], "d": ["Курфюрст Бранденбургский Фридрих III, с согласия императора Леопольда I, короновался в Кёнигсберге и принял титул «короля в Пруссии» (18 января 1701 г.). Титул был взят от Восточной Пруссии, потому что она находилась за пределами Священной Римской империи, а подчинённый императору курфюрст мог стать королём лишь за пределами империи. Разрозненные владения династии Гогенцоллернов с этой даты стали именоваться одним названием государства.", "203ac1b3"]},
"OLAYLAR_EK20:1720-09-02:0":{"b": ["Сардиния перешла от Испании к Савойской династии — родилось Сардинское королевство", "adf778b7"], "d": ["В последнем звене договорённостей, закрывших войну за испанское наследство, остров Сардиния был отнят у Испании и передан Савойской династии; герцог Савойский уступил взамен Сицилию и получил титул короля Сардинии. Кальяри и Сассари таким образом вышли из-под двухвековой испанской власти. Возникшее Сардинское королевство — ядро государства, которое полтора века спустя создаст единую Италию, то есть корни Королевства Италия, вступившего в Рим в 1870 г., уходят сюда.", "a73abd0e"]},
"OLAYLAR_EK20:1768-05-15:0":{"d": ["Генуэзская республика уступила Франции Корсику, которой владела веками, но фактически не могла контролировать из-за восстаний. Статья TDV «Korsika» передаёт событие одним предложением: Генуя в 1768 г. продала Франции этот остров, который не очень стремилась удержать. Передача отмечает уход Генуи из последнего крупного территориального владения в Средиземноморье; в 1796 г. остров на некоторое время перейдёт в руки англичан, затем будет вновь возвращён Франции. То, что остров стал французской землёй, сделало Наполеона Бонапарта, родившегося годом позже в Аяччо, французским подданным. В этом году (1768) Корсика, включая Бастию, продана Генуей Франции (TDV Korsika; день не подтверждён).", "c6214397"], "b": ["Корсика продана Генуей Франции — Версальский договор", "770343df"]},
"OLAYLAR_EK20:1807-07-09:0":{"b": ["Тильзитский мир — Пруссия потеряла половину земель, создано Варшавское герцогство", "d30bb2cc"], "d": ["После разгрома при Йене и Ауэрштедте Пруссия была вынуждена принять в Тильзите тяжёлый мир с Наполеоном (9 июля 1807 г.). Она уступила все земли к западу от Эльбы и польские земли, полученные при разделах 1793 и 1795 гг.; из вторых было создано Варшавское герцогство, а округа Белостока передан России. Пруссия потеряла около половины населения и территории, её армия была ограничена 42 000 человек. В атласе Познань и Торунь с этого дня переходят к Варшавскому герцогству, а Белосток — к России. По этому договору Лодзь и Ченстохова (польские провинции, перешедшие к Пруссии после 1772 г.) отошли к Варшавскому герцогству; Гданьск (Данциг) стал независимым вольным городом.", "e484982c"]},
"OLAYLAR_EK20:1870-09-20:0":{"b": ["Итальянские войска вступили в Рим — конец Папского государства и завершение объединения Италии", "a3689f2e"], "d": ["Когда в ходе Франко-прусской войны Наполеон III был свергнут и французский гарнизон, охранявший Рим, был отозван, итальянские войска вступили в город, а папа удалился в Ватикан. Так закончилось Папское государство, существовавшее более тысячи лет, а Королевство Италия, присоединившее и Рим к объединению, вышло на европейскую и мировую сцену как политическая сила. Это событие имеет прямые последствия для последнего полувека атласа: объединённая Италия — государство, которое в 1911 г. заберёт у Османов Триполи и Додеканес.", "6d9c3e10"]},
"OLAYLAR_EK20:1887-01-07:0":{"b": ["Битва при Çelenko — конец эмирата Харэр и абиссинская оккупация", "5671a0d9"], "d": ["Когда Дауд стал имамом Аусса, Харэр, оказавшийся посреди земель, управляемых оромо, вновь стал независимым эмиратом и сохранял это положение до абиссинской оккупации 1887 г. Эмир Абдуллах, объявив джихад, 7 января 1887 г. с 5000 человек встретил абиссинцев у Şeleneko (Çelenko); поняв, что будет разбит, он бежал в область Огаден на юге Харэра. Битва показала неравенство между вооружённой огнестрельным оружием абиссинской армией и силами эмирата и уничтожила один из последних независимых мусульманских эмиратов за Красным морем. Харэр, Cîcîga и Dagahbûr таким образом вошли в состав Абиссинии.", "73175130"]},
"OLAYLAR_EK21:1509-01-01:0":{"b": ["Взятие Дербента шахом Исмаилом — сефевидская власть дошла до кавказских ворот", "305542c4"], "d": ["После того как ширваншах Ферух Ясар в 1500 г. был разбит и убит, Баку и Шемаха перешли к Сефевидам, а Дербент ещё некоторое время оставался отдельным. Шах Исмаил в 1509 г. взял город и поселил здесь одно из племён румлу; так сефевидская власть дошла до северных ворот Кавказа — узкого прохода между Каспием и горами. С переходом Ширвана в 1538 г. под прямое сефевидское управление связь стала прочной. Дербент в походе 1578 г. перейдёт в руки Османов и до 1607 г. будет центром бейлербейства из семи санджаков. Запись TDV такова: «Образование и развитие Сефевидского государства положило начало новому периоду в Дербенте. Шах Исмаил в 1509 г. взял город и поселил здесь одно из племён румлу. Когда в 1538 г. Ширван перешёл под прямую власть Сефевидов...»", "e301b4f1"]},
"OLAYLAR_EK21:1537-01-01:0":{"b": ["Окончательное присоединение Карса к османским землям — гвоздь восточного порубежья", "6235c85a"], "d": ["После падения государства Ак-Коюнлу от рук Сефевидов Карс некоторое время оставался в руках Севюндюк-хана Курчибаши из туркмен-афшаров. Весьма вероятно, что во время Ирак-ейнского похода Кануни (940/1534), когда были взяты крепости Пасин, Шюрегель и Олту, крепость Карс тоже была подчинена османам; однако окончательное присоединение города произошло тремя годами позже. Запись TDV такова: «Карс был окончательно включён в османские земли в 944 г. (1537) Dulkadırlı Мехмед-ханом, перешедшим на османскую службу». Поскольку из-за долгих сражений город и крепость были в значительной степени разрушены, быстро занялись ремонтом; в 955 г. (1548), когда крепость ремонтировали, сефевиды напали на город и вновь разрушили крепость. После этого Карс на триста сорок лет останется замком северо-восточного порубежья Османов и будет уступлен России после войны 1877-78 гг.", "dff46f96"]},
"OLAYLAR_EK21:1811-04-01:0":{"b": ["Возвращение Никополя — шестимесячная русская оккупация закончилась", "7fb299d7"], "d": ["В османо-русской войне 1806-1812 гг. русские войска, перешедшие на южный берег Дуная, взяли Никополь в октябре 1810 г. под командованием генерала Кутузова. Через шесть месяцев, увидев, что не смогут удержать линию Дуная, они оставили город; перед уходом взорвали значительную часть крепости. Запись TDV такова: «В октябре 1810 года (в период турецко-русской войны 1808-1812 гг.) Никополь был взят войсками знаменитого русского генерала Михаила Кутузова. Русские, прежде чем покинуть город, в апреле 1811 года взорвали значительную часть крепости и нанесли городу большой ущерб». После отхода русских войск османы вновь отстроили крепость; надпись 1813-1814 гг. фиксирует этот ремонт.", "7237449c"]},
"OLAYLAR_EK21:1811-05-01:0":{"b": ["Эвакуация Силистрии — средняя крепость Дуная оставлена со снесёнными стенами", "561628bb"], "d": ["Силистра, одна из сильнейших османских крепостей на Дунае, в 1810 г. подверглась бомбардировке русской артиллерии; из-за взрыва оружейного склада крепость и предместье были сильно разрушены. Овладев городом, русские вместо того чтобы удерживать его, предпочли уничтожить его укрепления: генерал Кутузов приказал разрушить стены, а в мае 1811 г. донёс царю, что стены Силистрии взорваны. Запись TDV: «В 1810 г. город был подвергнут бомбардировке русскими… После того как русские овладели городом и до их отхода генерал Кутузов приказал разрушить Силистру. В мае 1811 г. он донёс царю, что стены Силистры взорваны». Эта же крепость в войне 1827-1828 гг. будет вновь взята русскими, и ту осаду подробно опишет Гельмут фон Мольтке.", "d18dd90e"]},
"OLAYLAR_EK22:1794-01-01:0":{"b": ["Конец династии Зендов — власть Каджаров в Иране", "5dda30a4"], "d": ["С поражением Лютф Али-хана, последнего правителя династии Зендов, династия, основанная в 1751 г., прекратила существование, и весь Иран оказался в руках Ага Мухаммед-хана. Формальное основание государства Каджаров датируется двумя годами позже — коронацией Ага Мухаммед-хана в Тегеране шахиншахской короной (1796); однако власть перешла в 1794 г.", "793d45c6"]},
"OLAYLAR_EK22:1923-07-24:0":{"b": ["Различия Лозанны и Севра: от навязанного мира к равному миру", "4b578583"], "d": ["Севр (10 августа 1920 г.) был документом, навязанным стамбульскому правительству и никогда не вступившим в силу; Лозанна (24 июля 1923 г.) — мир, подписанный Анкарой как равной стороной и ратифицированный ВНСТ 23 августа 1923 г. (Лозанна, ст. 1, 143). По границам Севр проводит европейскую границу Турции по линии Чаталджа и отдаёт Греции Восточную Фракию, включая Эдирне, а также Имброс и Бозджаада (Севр, ст. 27, 84); Измир и его округа остаются под турецким суверенитетом по названию, но управление передаётся Греции, а через пять лет местный парламент может потребовать присоединения (ст. 65-83). Лозанна проводит границу по линии Мерич-Арда, Эдирне и Караагач остаются в Турции, Имброс и Бозджаада становятся турецкими (Лозанна, ст. 2, 12, 14; Караагачский протокол). По проливам Севр учреждает международную комиссию, распространяющуюся на все воды, где турецкий член имеет лишь один голос; укрепления разрушаются, а зона открывается для использования союзниками (Севр, ст. 36-61, 178-180). Лозанна сохраняет принцип свободного прохода, но оставляет комиссию с турецким председателем, демилитаризованные зоны и гарнизон в 12 000 человек в Стамбуле (Лозанна, ст. 23; Конвенция о проливах). Признание Армении и арбитраж президента США по границе, а также план курдской автономии (Севр, ст. 62-64, 88-93) в Лозанне отсутствуют. По арабским землям, Египту, Судану и Кипру Севр вводит подробные положения о передаче (Севр, ст. 94-97 — мандаты, ст. 98-100 — Хиджаз, ст. 101-122 — отказ от Египта, Судана, Кипра, Марокко, Туниса и Ливии; диапазоны статей по TDV такие же); Лозанна формулирует отказ короче: Додеканес остаётся Италии, Кипр — Англии, вопрос о границе Мосула откладывается (Лозанна, ст. 3, 15-21). Севр заново устанавливает и расширяет капитуляции, через Финансовую комиссию контролирует турецкий бюджет и заимствования, вооружённые силы (жандармерия и вспомогательные части) не могут превышать 50 000 человек, военная и морская авиация запрещены (Севр, ст. 155, 164, 191-195, 231-264, 261-263). Лозанна отменяет капитуляции, распределяет долги и не вводит отдельного ограничения на армию (Лозанна, ст. 28, 46-63; ст. 113 упраздняет и иностранные почтовые отделения). Положения о меньшинствах в Севре шире и открыты для вмешательства союзников, тогда как в Лозанне они гарантированы Лигой Наций и взаимны (Севр, ст. 140-151; Лозанна, ст. 37-45).\n\nСравнение по осям:\n• Восточная Фракия, Эдирне, Чаталджа — Севр: граница по линии Чаталджа; Восточная Фракия и Эдирне Греции (ст. 27, 84-85) | Лозанна: граница по Меричу и Арде; Эдирне и Караагач в Турции (ст. 2; Караагачский протокол)\n• Район Измира — Севр: суверенитет турецкий, управление и армия греческие, через пять лет заявление о присоединении (ст. 65-83) | Лозанна: особой статьи о статусе Измира нет; Анатолия находится в границах Турции (ст. 2-3, общая граница; по Измиру в частности доказательства в статьях нет)\n• Проливы и Стамбул — Севр: Международная комиссия по проливам, у Турции 1 голос; разрушение укреплений, зона в пользовании союзников; Стамбул в турецких руках, но с условием о меньшинствах (ст. 36-61, 178-180) | Лозанна: принцип свободного прохода; комиссия с турецким председателем, демилитаризованные зоны, гарнизон в 12 000 человек в Стамбуле (ст. 23; Конвенция о проливах)\n• Армения и Курдистан — Севр: Армения признаётся, границу определяет президент США; курдская автономия, через год заявление о независимости (ст. 62-64, 88-93) | Лозанна: соответствующего положения нет (в сводках ст. 1-143 не встречается)\n• Эгейские острова, Додеканес — Севр: Имброс, Бозджаада и острова Эгейского моря Греции; Додеканес и Кастелоризо Италии (ст. 84, 122) | Лозанна: Имброс и Бозджаада в Турции, острова Восточного Эгея греческие, Додеканес и Кастелоризо в Италии (ст. 12-15)\n• Кипр, Египет, Судан, арабские земли — Севр: мандат на Сирию/Месопотамию и Палестину, Хиджаз независим; признаются протекторат над Египтом, Судан, аннексия Кипра (ст. 94-98, 101-117) | Лозанна: граница с Сирией по франко-турецкому соглашению 1921 г., граница с Ираком позднее; отказ от Египта, Судана, Кипра (ст. 3, 16-20)\n• Капитуляции — Севр: восстанавливаются и расширяются; план судебной реформы в союзнической комиссии (ст. 136, 261-263, 308-309) | Лозанна: отменяются полностью; иностранные почтовые отделения и Высший санитарный совет упраздняются (ст. 28, 113-114)\n• Финансовый контроль и долги — Севр: Союзническая финансовая комиссия контролирует бюджет и заимствования, Управление оттоманского государственного долга расширяется, доходы служат обеспечением (ст. 231-264) | Лозанна: долги Управления оттоманского государственного долга делятся между государствами; военные убытки взаимно прощаются (ст. 46-63, 58)\n• Военные ограничения — Севр: армия 50 000 человек, авиация и танки запрещены, союзнические контрольные комиссии (ст. 152-207) | Лозанна: общих ограничений нет; лишь демилитаризация греческих островов и районов проливов и Фракии (ст. 13; Конвенции о проливах и Фракии)\n• Меньшинства — Севр: гарантии и право вмешательства союзников, отмена Emval-i Metruke, возвращение (ст. 140-151, 86, 142-144) | Лозанна: права немусульманских меньшинств, гарантированные Лигой Наций, взаимные права мусульман в Греции; греко-турецкий обмен населением (ст. 37-45; Конвенция об обмене)\n• Правовой статус — Севр: подписан стамбульским правительством, Анкара отвергла, не вступил в силу (TDV) | Лозанна: равная сторона; ратификация ВНСТ 2 августа 1923 г., 213 за, 14 против (TDV; ст. 1, 143)", "95c8b4ce"]},
"OLAYLAR_EK2:1327-01-01:0":{"b": ["Чеканка первого османского акче", "38d2d638"], "d": ["Первое серебряное акче, отчеканенное от имени Орхан-гази, — денежное провозглашение независимого суверенитета бейлика; акче оставалось основной денежной единицей пять веков.", "8729ab5b"]},
"OLAYLAR_EK2:1362-09-01:0":{"b": ["Учреждено Румелийское бейлербейство", "ffa16089"], "d": ["Завоевания на европейской стороне были собраны под единой военно-административной крышей; бейлербейский порядок стал хребтом провинциальной организации империи.", "9c13c8c3"]},
"OLAYLAR_EK2:1390-01-15:0":{"b": ["Брак Йылдырым Баязида и Деспины-хатун", "4b10dc6c"], "d": ["Вассалитет, установленный с сербским деспотатом после Косова, был скреплён браком Оливеры, дочери Лазаря, с Баязидом — типичный пример брачной дипломатии раннего периода.", "7d87810a"]},
"OLAYLAR_EK2:1393-01-01:0":{"b": ["Учреждено Анатолийское бейлербейство", "5ef8d3a7"], "d": ["Для управления присоединёнными землями бейликов было организовано Анатолийское бейлербейство; двукрылая румелийско-анатолийская система управления была завершена.", "55429c02"]},
"OLAYLAR_EK2:1399-06-01:0":{"b": ["Завершена Улу-джами в Бурсе", "27bcc4a5"], "d": ["Построенная на никопольскую добычу двадцатикупольная соборная мечеть — монументальный образец раннеосманской архитектуры и открытый музей каллиграфии.", "b0e811e6"]},
"OLAYLAR_EK2:1453-06-01:0":{"b": ["Смещение и казнь Чандарлы Халиль-паши", "5e19438f"], "d": ["После завоевания великий везирь из старинного рода Чандарлы, державшийся в стороне от осады, был казнён; впервые великий везирь убивался по приказу падишаха, и открывалась эпоха везирей девширменского происхождения.", "557b77f5"]},
"OLAYLAR_EK2:1456-06-01:0":{"b": ["Обложение Молдавии данью", "25bd3693"], "d": ["Молдавское воеводство согласилось платить дань; тройной вассальный пояс к северу от Дуная вместе с Валахией и Трансильванией стал северным буфером империи. В тот же день присоединены также: Яссы.", "7cea09ea"]},
"OLAYLAR_EK2:1459-03-07:0":{"b": ["Дань Дубровника (Рагузы)", "d127c78a"], "d": ["Купеческая республика Рагуза гарантировала себе автономию и торговые привилегии в обмен на дань; она разбогатела как окно османов на Адриатике. Остров Млет (Mljet), земля республики, также разделил этот статус.", "812b9f2b"]},
"OLAYLAR_EK2:1462-06-01:0":{"b": ["Валашский поход: Влад Цепеш (Колосажатель)", "fd4530bb"], "d": ["Походом, организованным против Влада Цепеша, отказавшегося платить дань и убившего послов, Валахия была возвращена в вассальное положение; ночное нападение и сцены ужаса с посаженными на кол стали легендой в Европе. В тот же день присоединены также: Бухарест.", "6ae089b4"]},
"OLAYLAR_EK2:1470-12-01:0":{"b": ["Открыт комплекс Фатиха", "a150ea55"], "d": ["Комплекс с его восемью медресе (Сахн-и Семан) стал первым большим шагом программы превращения Стамбула в научный центр исламского мира.", "cbec7a2f"]},
"OLAYLAR_EK2:1472-01-01:0":{"b": ["Али Кушчи в Стамбуле", "8508229d"], "d": ["Али Кушчи, последний крупный представитель самаркандской обсерватории, по приглашению Фатиха стал мударрисом в медресе Айя-Софии; он основал в Стамбуле математико-астрономическую традицию.", "fd325f60"]},
"OLAYLAR_EK2:1477-01-01:0":{"b": ["Кануннаме Фатиха", "b08944c9"], "d": ["Первое обширное кануннаме обычного права, сводящее государственную организацию, протокол и наказания; оно обсуждается до сих пор из-за известной статьи, разрешающей братоубийство «ради миропорядка».", "0e654de1"]},
"OLAYLAR_EK2:1478-06-01:0":{"b": ["Отчеканен первый османский золотой (султани)", "2fd5c0dd"], "d": ["Была отчеканена первая османская золотая монета, равная венецианскому дукату; финансы империи вошли в международный денежный порядок.", "cac00614"]},
"OLAYLAR_EK2:1478-09-01:0":{"b": ["Переезд во дворец Топкапы", "b9cd6a5e"], "d": ["С завершением Нового дворца (Топкапы) центр государственного управления переместился сюда; дворец оставался мозгом империи на протяжении четырёх веков.", "748ada37"]},
"OLAYLAR_EK2:1532-04-27:0":{"b": ["Флорентийская республика превращена в герцогство — Алессандро де Медичи", "c08764e1"], "d": ["Под давлением папы Климента VII правящая комиссия Флоренции (Балия) приняла новую конституцию; пятисотлетний республиканский режим был отменён, Алессандро де Медичи был провозглашён наследственным герцогом и 1 мая фактически вступил на престол. Флоренция таким образом превратилась из независимой городской республики в наследственное герцогство династии Медичи.", "92da65c9"]},
"OLAYLAR_EK2:1534-01-01:0":{"b": ["Никях Кануни и Хюррем-султан", "abc05f26"], "d": ["Заключение Кануни официального никяха с Хюррем коренным образом изменило дворцовую традицию; родился институт «хасеки-султан», и открылась дверь эпохи женщин в династической политике.", "db1f832b"]},
"OLAYLAR_EK2:1536-02-18:0":{"b": ["Первые обширные капитуляции Франции", "e2264e48"], "d": ["В составе франко-османского союза против габсбургских тисков между Жаном де ла Форе и Макбулом Ибрагим-пашой были подписаны торговые привилегии; капитуляции, в тот день бывшие дипломатическим инструментом, с течением веков превратились в дверь финансовой зависимости.", "e7c6fd84"]},
"OLAYLAR_EK2:1538-06-13:0":{"b": ["Поход в Индийский океан: осада Диу", "fcd1217a"], "d": ["Флот, вышедший из Суэца, пересёк Красное море и осадил Диу в Гуджарате; хотя крепость не была взята, османская сила впервые дотянулась до Индийского океана, и португальская монополия была поколеблена.", "ce118bf7"]},
"OLAYLAR_EK2:1553-12-07:0":{"b": ["Индийское путешествие Сейди Али Рейса", "e5da3b2c"], "d": ["Сейди Али Рейс, которому было поручено привести флот из Басры в Египет, был штормами унесён в Индию; «Мират уль-мемалик», в которой он рассказал о приключениях возвращения, — один из первых османских путевых сочинений.", "bb472cec"]},
"OLAYLAR_EK2:1554-01-01:0":{"b": ["Казнь Пири Реиса", "63026444"], "d": ["Великий мореплаватель и картограф, вернувшийся из Ормузского похода, оставив флот в Басре, был казнён в возрасте 84 лет — одно из самых спорных решений в истории нашей науки.", "e3d1ac3f"]},
"OLAYLAR_EK2:1557-10-16:0":{"b": ["Открыт комплекс Сулеймание", "1c6458b2"], "d": ["Комплекс, который зодчий Синан называл «трудом подмастерья»; с медресе, даруш-шифа и библиотекой он стал крупнейшим образовательно-благотворительным комплексом классической эпохи.", "0c203c6b"]},
"OLAYLAR_EK2:1565-05-18:0":{"b": ["Осада Мальты", "f57f6a85"], "d": ["Мальта, ключ Средиземного моря, была осаждена четыре месяца; Тургут Рейс пал как шехид, осада была снята. Это стало первым крупным отступлением в мореплавании эпохи Кануни.", "860ee1bc"]},
"OLAYLAR_EK2:1575-03-01:0":{"b": ["Завершена мечеть Селимие", "3b0484e1"], "d": ["Селимие, которую Синан называл «трудом мастера», где единственный купол господствует над пространством, считается вершиной османской классической архитектуры (Всемирное наследие ЮНЕСКО).", "9d7cd43c"]},
"OLAYLAR_EK2:1577-01-01:0":{"b": ["Основана Стамбульская обсерватория", "169bdf5d"], "d": ["Обсерватория Таки ад-Дина, одна из наиболее оснащённых обсерваторий своего времени, была разрушена в 1580 году после споров, возникших после кометы 1577 года; институциональная астрономия опоздала на три века.", "7fb471aa"]},
"OLAYLAR_EK2:1578-08-09:0":{"b": ["Победа при Чылдыре — началась восточная война", "13125a54"], "d": ["С разгромом сефевидской армии при Чылдыре открылись ворота Кавказа; был взят Тифлис, и Грузия перешла под османское господство.", "0bf34d05"]},
"OLAYLAR_EK2:1583-05-09:0":{"b": ["Битва факелов — Ширван окончательно у османов", "3bbc23bc"], "d": ["В битве, названной так потому, что она продолжалась и ночью при свете факелов, сефевиды были окончательно разгромлены; османское господство в Ширване и Баку было закреплено.", "e2aa6d1e"]},
"OLAYLAR_EK2:1585-01-01:0":{"b": ["Великая порча монеты — кризис акче", "9205c3d4"], "d": ["Под давлением долгих войн и американского серебра содержание серебра в акче было снижено наполовину; революция цен питала распад сипахийского порядка и смуту джелали.", "bd2a508f"]},
"OLAYLAR_EK2:1585-09-25:0":{"b": ["Завоевание Тебриза", "6506bdb9"], "d": ["Сердар Эздемироглу Осман-паша вошёл в Тебриз; древняя столица сефевидов была взята под османское управление. Осман-паша через несколько недель скончался в лагере.", "e54b35bd"]},
"OLAYLAR_EK2:1590-03-21:0":{"b": ["Договор Фархад-паши — наибольшие границы на востоке", "c429972f"], "d": ["После прибытия в Стамбул посла шаха Аббаса Хайдар-мирзы (18 января 1590 года) по договору, заключённому на условии, что завоёванные места останутся за османами, и закончившему 12-летнюю войну, Тебриз, Карабах, Ширван, Грузия и Лурестан остались за османами; империя достигла на востоке наибольших границ в своей истории.", "41d8b058"]},
"OLAYLAR_EK2:1603-10-21:0":{"b": ["Началась османско-сефевидская война (1603–1612) — контрнаступление шаха Аббаса, потеря Тебриза", "abf27dd8"], "d": ["Шах Аббас, реорганизовавший армию, воспользовавшись смутой джелали, перешёл в наступление; Тебриз пал, кавказские приобретения были утрачены в течение нескольких лет. В том же походе и после него утрачены также: Нахичевань, Хой, Merend, Сальмас; беи Карадага (Ахар) и Мукри также перешли на сторону сефевидов.", "b1757da9"]},
"OLAYLAR_EK2:1611-03-25:0":{"b": ["Родился Эвлия Челеби", "2b6051ff"], "d": ["Эвлия Челеби, собравший свои путешествия, длившиеся более пятидесяти лет, в десятитомном «Сейяхатнаме», оставил несравненную панораму османского мира XVII века.", "bbd451a3"]},
"OLAYLAR_EK2:1612-11-20:0":{"b": ["Договор Насух-паши", "bb69e388"], "d": ["По договору, завершившему войну, шедшую с 1603 года, от приобретений 1590 года отказались и вернулись к Амасийской границе 1555 года; равновесие на восточном фронте было восстановлено.", "f3ce47a7"]},
"OLAYLAR_EK2:1616-06-09:0":{"b": ["Открыта мечеть Султан Ахмед", "e39dfd43"], "d": ["«Голубая мечеть» с шестью минаретами и синими изникскими изразцами — последний большой султанский комплекс классической эпохи.", "c3e55fc5"]},
"OLAYLAR_EK2:1648-08-18:0":{"b": ["Убийство султана Ибрахима", "bc4eb452"], "d": ["Союз корпуса и улемов свергнул Ибрахима с престола, мотивируя расточительством и кризисом управления; через десять дней он был задушен по фетве. На престол взошёл семилетний Мехмед IV; власть фактически перешла в руки великой валиде Кёсем-султан.", "b90693f4"]},
"OLAYLAR_EK2:1657-10-06:0":{"b": ["Смерть Катиба Челеби", "e167e89d"], "d": ["Вершинная фигура истории османской науки благодаря библиографии «Кашф аз-зунун» и географии «Джихан-нюма»; известен новаторским подходом, использовавшим европейские источники.", "786ec8d5"]},
"OLAYLAR_EK2:1703-08-22:0":{"b": ["Эдирнейское событие — низложение Мустафы II", "0291c1cd"], "d": ["Гнев на то, что падишах жил в Эдирне, и на влияние Фейзуллах-эфенди перерос в большое восстание армии и ремесленников; шейх-уль-ислам был предан самосуду, падишах свергнут, двор вернулся в Стамбул.", "e8740499"]},
"OLAYLAR_EK2:1720-10-08:0":{"b": ["Посол в Париж: Йирмисекиз Мехмед-челеби", "26312a3f"], "d": ["Великое посольство, посланное во Францию, стало первым систематическим наблюдением за Западом на месте; его «Сефаретнаме» вдохновило обновление эпохи тюльпанов.", "aa11c96a"]},
"OLAYLAR_EK2:1727-07-05:0":{"b": ["Основана первая османская типография", "4943f7e5"], "d": ["Было дано разрешение печатать книги на турецком языке; первым трудом в 1729 году был напечатан Словарь Ванкулу. Типография — самое прочное наследие обновления эпохи тюльпанов.", "a33e45d0"]},
"OLAYLAR_EK2:1740-05-30:0":{"b": ["Капитуляции сделаны постоянными", "d044a79e"], "d": ["Привилегии, данные Франции, перестали быть ограниченными личностью падишаха и были привязаны к постоянному договору; режим капитуляций, ставший не расторгаемым в одностороннем порядке, удалось отменить лишь в Лозанне.", "d50899dc"]},
"OLAYLAR_EK2:1773-01-01:0":{"b": ["Основано Мюхендисхане-и Бахри-и Хюмаюн", "9bf3f439"], "d": ["Инженерное училище, основанное для подготовки современных морских офицеров после чесменской катастрофы, — первое постоянное учреждение технического образования западного образца; сухопутное инженерное училище последовало в 1795 году.", "b73b2ce6"]},
"OLAYLAR_EK2:1793-06-01:0":{"b": ["Первое постоянное посольство в Лондоне", "6b5630eb"], "d": ["В рамках программы Низам-и Джедид в европейских столицах были открыты постоянные посольства; османская дипломатия перешла на основу взаимности.", "0321b899"]},
"OLAYLAR_EK2:1808-11-16:0":{"b": ["Смерть Алемдара Мустафа-паши", "4426534e"], "d": ["В янычарском восстании, начавшемся ночью 15 ноября 1808 года, великий везирь-реформатор, осаждённый в Высокой Порте, не дождавшись ожидаемой помощи, на следующий день поджёг пороховой склад и погиб вместе с сотнями нападавших; порядок Сенед-и Иттифак и первая попытка реформ были погребены вместе с ним.", "04420a26"]},
"OLAYLAR_EK2:1831-11-01:0":{"b": ["Первая официальная газета: Такви-и Векаи", "c637f623"], "d": ["Начала выходить официальная газета государства; это начало традиции современного общественного мнения и официальных сообщений.", "b4f1f627"]},
"OLAYLAR_EK2:1838-08-16:0":{"b": ["Торговый договор Балта-Лиман", "e790b383"], "d": ["Англии было предоставлено наиболее привилегированное положение даже во внутренней торговле, система йед-и вахид (монополия) была отменена; пока местное производство оставалось беззащитным, договор стал документом полного открытия османского рынка свободной торговле.", "14089a77"]},
"OLAYLAR_EK2:1842-01-01:0":{"b": ["Конец Ливанского эмирата — смещение Башира III Шихаба", "f85ae454"], "d": ["Эмир Башир II (III), не сумевший контролировать христианско-друзскую распрю и внутренние равновесия в области Шуф, был смещён в январе 1842 года; порядок местного эмирата, продолжавшийся с 1516 года (руками Маниды, а затем Шихабидов), закончился, и область перешла под непосредственное османское управление, а затем к системе двойного каймакамства.", "205abc18"]},
"OLAYLAR_EK2:1844-01-01:0":{"b": ["Ташихи сикке: порядок Меджидийе", "c77be809"], "d": ["Реформой монеты были изъяты монеты с испорченной пробой; была создана стабильная биметаллическая система на основе золотой лиры (Меджидийе).", "e0642ec8"]},
"OLAYLAR_EK2:1850-01-01:0":{"b": ["Конец местного господства семьи Харфуш в Баальбеке", "8438f4ae"], "d": ["Влияние семьи Харфуш, правившей в Баальбеке с 1521 года (после восстания Джанбирди аль-Газали) как малая местная династия, закончилось новым административным устройством Высокой Порты; город был превращён в обычный центр каза, подчинённый вилайету Дамаск.", "106eabb2"]},
"OLAYLAR_EK2:1851-01-01:0":{"b": ["Основана Ширкет-и Хайрийе", "462830e7"], "d": ["Основанная для эксплуатации пароходов на Босфоре компания считается первым османским акционерным обществом; пароходные пристани наложили отпечаток на жизнь города.", "b4203b61"]},
"OLAYLAR_EK2:1854-08-24:0":{"b": ["Первый договор о внешнем долге", "9017c579"], "d": ["Для финансирования Крымской войны на Лондонском рынке был получен первый внешний заём; точкой, к которой привели 15 займов за 21 год, стали мораторий 1875 года и Управление общественного долга.", "1c4f9949"]},
"OLAYLAR_EK2:1855-09-14:0":{"b": ["Телеграфная линия в Стамбуле", "d320f39f"], "d": ["Первая телеграфная линия, построенная по нуждам Крымской войны, была открыта для работы; за несколько десятилетий империя обзавелась одной из самых обширных телеграфных сетей мира.", "f59439a3"]},
"OLAYLAR_EK2:1858-06-06:0":{"b": ["Земельное кануннаме", "6bae243a"], "d": ["Кануннаме, модернизировавшее земельное право, привязало фактическое распоряжение в мирийской земле к тапу; оно — один из основных документов порядка собственности в нынешнем Ближнем Востоке.", "395494dc"]},
"OLAYLAR_EK2:1863-01-13:0":{"b": ["Первые лекции в Дарюльфюнуне", "08f74066"], "d": ["Дарюльфюнун, призванный давать образование университетского уровня, начал работу с публичных лекций; учреждение, существовавшее с перерывами, было постоянно открыто в 1900 году и стало ядром Стамбульского университета.", "6218d070"]},
"OLAYLAR_EK2:1864-11-08:0":{"b": ["Положение о вилайетах", "ad20853b"], "d": ["Вместо эялетного порядка была создана вилайетская организация по французской модели; опыт Дунайского вилайета Мидхат-паши был взят за образец и распространён на всю страну.", "665b97d3"]},
"OLAYLAR_EK2:1867-06-21:0":{"b": ["Европейское путешествие Абдулазиза", "9ff0fa1e"], "d": ["Первое мирное путешествие османского падишаха в Европу; Парижская выставка и визиты в Лондон послужили витриной как дипломатии, так и модернизации.", "bd58ae5d"]},
"OLAYLAR_EK2:1868-09-01:0":{"b": ["Открыт Галатасарайский султанский лицей", "f9688524"], "d": ["Лицей с преподаванием на французском языке стал символом идеала равенства в образовании эпохи Танзимата своим составом учеников без различия религии и миллета.", "c9d5821d"]},
"OLAYLAR_EK2:1869-04-01:0":{"b": ["Первая книга Меджелле вступила в силу", "6475461c"], "d": ["Меджелле, свод обязательственного и вещного права ислама, составленный современной законодательной техникой, считается первым исламским гражданским кодексом; комиссия под председательством Джевдет-паши завершила 16 книг в 1876 году.", "9669c96e"]},
"OLAYLAR_EK2:1876-05-30:0":{"b": ["Низложение Абдулазиза", "eb7397ea"], "d": ["Государственные деятели-конституционалисты и военная верхушка свергли Абдулазиза бесшумным переворотом; его сомнительная смерть через пять дней и последовавшие за ней события в Чырагане породили расчёты, которые продлятся годами.", "9523e81b"]},
"OLAYLAR_EK2:1878-05-20:0":{"b": ["Нападение на Чыраган (дело Али Суави)", "d2a9ac87"], "d": ["Журналист Али Суави напал на Чыраган, чтобы вновь возвести Мурада V на престол; нападение было кроваво подавлено, режим Абдулхамида навсегда ужесточил кольцо безопасности.", "8bd8ba3f"]},
"OLAYLAR_EK2:1884-01-01:0":{"b": ["Учреждено Управление Режи (табачная монополия)", "bad9b030"], "d": ["Табачные доходы были переданы компании Режи с иностранным капиталом в составе Управления общественного долга; конфликты «контрабанды Режи» между крестьянами и сборщиками продолжались десятилетиями. В тот же день утрачены также: Зейла.", "19e84e39"]},
"OLAYLAR_EK2:1898-10-18:0":{"b": ["Визит кайзера Вильгельма II в Стамбул и Иерусалим", "2988cd06"], "d": ["Второй визит германского императора закрепил османско-германское сближение; открылся путь к концессии на Багдадскую железную дорогу, в Дамаске была произнесена речь о «друге трёхсот миллионов мусульман».", "2e385229"]},
"OLAYLAR_EK2:1908-09-01:0":{"b": ["Хиджазская железная дорога в Медине", "95009b9c"], "d": ["Линия протяжённостью 1464 км, построенная лишь на мусульманские пожертвования и силами местной инженерии, дошла до Медины; путь паломничества сократился с недель до дней. Это крупнейшее инфраструктурное творение эпохи Абдулхамида II.", "a1c98c4c"]},
"OLAYLAR_EK2:1909-04-13:0":{"b": ["Инцидент 31 марта", "1d7c2bb2"], "d": ["Большое антиконституционное восстание овладело Стамбулом; пришедшая из Салоник Армия действия подавила мятеж, и Абдулхамид II был свергнут.", "4885dfd1"]},
"OLAYLAR_EK2:1912-10-26:0":{"b": ["Началась осада Эдирне", "234d9b28"], "d": ["Пятимесячная оборона Шюкрю-паши стала эпосом сопротивления в разгар балканской катастрофы; город пал от голода, в июле 1913 года был возвращён.", "3c3ca395"]},
"OLAYLAR_EK2:1913-01-23:0":{"b": ["Налёт на Высокую Порту", "b304d02d"], "d": ["Правительство, готовившееся сдать Эдирне, было свергнуто вооружённым налётом унионистов; военный министр Назым-паша был убит. Началась эпоха полной власти «Единения и прогресса».", "a8a7af44"]},
"OLAYLAR_EK2:1915-07-11:0":{"b": ["Упразднение мутасаррифата Горного Ливана", "b5639051"], "d": ["Порядок автономного мутасаррифата, основанный на Органическом регламенте 1861 года и международном протоколе, обновлённом в 1864 году, был односторонне расторгнут Османским государством во время Первой мировой войны; Министерство внутренних дел начало назначать в область непосредственно мутасаррифов-мусульман. Так закрылся период автономии, в течение которого в 1861–1915 годах служили восемь мутасаррифов.", "83ff35bc"]},
"OLAYLAR_EK3:1402-08-01:0":{"b": ["Раздел страны между шехзаде", "82f26bfb"], "d": ["После разгрома при Анкаре Сулейман-челеби перешёл в Румелию и провозгласил себя султаном в Эдирне; Иса-челеби удерживал Бурсу, а Челеби Мехмед — область Амасья–Токат–Сивас. На карте эти три доли показываются разными цветами.", "08baaa0b"]},
"OLAYLAR_EK3:1403-02-01:0":{"b": ["Галлипольский договор: черноморское побережье до Месемврии оставлено Византии", "a4164eca"], "d": ["Эмир Сулейман, желавший закрепиться в Румелии после разгрома при Анкаре, подписал в Галлиполи договор с византийским императором Мануилом. Он оставил Византии Картал, Пендик и Gebze с некоторыми островами, в Румелии — Салоники и Фессалию, на Чёрном море — береговую полосу до Месемврии; налог, который Византия платила османам, также был отменён. Ахтополь, Игнеада и Резве на берегу Странджи таким образом двадцать один год оставались под византийским управлением; Мурад II вернул большую часть этих мест миром 1424 года.", "ad1af28a"]},
"OLAYLAR_EK3:1403-03-09:0":{"b": ["Смерть Йылдырым Баязида в плену", "7e968d83"], "d": ["Падишах, находившийся в плену у Тимура, скончался в Акшехире; его тело было привезено в Бурсу и погребено. Его смерть сделала борьбу за престол между шехзаде необратимой.", "af68bc4d"]},
"OLAYLAR_EK3:1403-06-15:0":{"b": ["Галлипольский договор — уступки Византии", "dfacbd00"], "d": ["Сулейман-челеби, желавший обеспечить своё положение в Румелии, договорившись с Византией и латинскими государствами, вернул Салоники, берега Мраморного моря и некоторые острова; он согласился даже платить дань.", "0d91820c"]},
"OLAYLAR_EK3:1403-09-01:0":{"b": ["Столкновение при Ulubat — поражение Исы-челеби", "500c5d24"], "d": ["Иса-челеби, удерживавший Бурсу, был разбит при Ulubat своим братом Мехмедом; несколько попыток оправиться также остались безрезультатными.", "624072ce"]},
"OLAYLAR_EK3:1406-06-01:0":{"b": ["Исчезновение Исы-челеби", "0effa11e"], "d": ["Иса-челеби, несколько раз возвращавшийся в Анатолию при поддержке Сулейман-челеби, после последнего поражения исчез; его доля перешла к Челеби Мехмеду, и на карте владения Мехмеда расширились к западу.", "d164b447"]},
"OLAYLAR_EK3:1406-06-18:0":{"b": ["Муса-челеби перешёл в Валахию", "8441267a"], "d": ["Челеби Мехмед, потерявший Бурсу и Анкару в борьбе с Сулейман-челеби и отошедший в Токат–Амасью, подтолкнул брата Мусу отправиться в Румелию. Муса, приняв приглашение валашского воеводы Мирчи, морем добрался до Валахии; отсюда он вступит в борьбу, которая поставит Сулеймана между двух фронтов.", "e7866931"]},
"OLAYLAR_EK3:1410-05-06:0":{"b": ["Челеби Мехмед вновь взял Бурсу и Анкару — анатолийская доля вышла из рук Сулейман-челеби", "bfb69f12"], "d": ["После успехов Мусы-челеби в Румелии (Ямбол, 13 февраля 1410 года) находившийся в Анатолии эмир Сулейман-челеби перешёл в Румелию. После ухода Сулеймана из Анатолии Мехмед-челеби вновь овладел областью Бурсы, включая Анкару, и в знак восшествия на престол велел отчеканить монету с датой 813 года. На карте анатолийская сторона Мраморного моря переходит от доли эмира Сулеймана к цвету Челеби Мехмеда.", "bc148b8e"]},
"OLAYLAR_EK3:1410-06-15:0":{"b": ["Битва при Космидионе", "0efc2caa"], "d": ["В сражении под стенами Стамбула, состоявшемся при поддержке Византии, Сулейман Челеби победил своего брата Мусу; однако его поддержка в Румелии быстро начала таять. Другие населённые пункты, утраченные в ту же дату: Аласона (Elassona), Айтос (Aytos), Болаыр (места в Румелии, перешедшие на карте от Мусы к Сулейману).", "0498cbda"]},
"OLAYLAR_EK3:1411-01-01:0":{"b": ["Осада Константинополя Мусой-челеби", "4932f586"], "d": ["Муса-челеби, желавший наказать Византию, поддерживавшую Сулеймана, осадил Константинополь; эта осада толкнула Византию к союзу с Челеби Мехмедом.", "b52f942c"]},
"OLAYLAR_EK3:1411-02-17:0":{"b": ["Смерть эмира Сулеймана — Муса владеет Румелией", "325c1549"], "d": ["Сулейман-челеби, схваченный при бегстве из Эдирне, был убит; вся Румелия перешла в руки Мусы-челеби. На карте Румелия меняет синий цвет на фиолетовый.", "48aa849a"]},
"OLAYLAR_EK3:1413-07-05:0":{"b": ["Битва при Чамурлу — восстановление единства", "0b23173e"], "d": ["Челеби Мехмед, получивший поддержку Византии, сербского деспотата и румелийских беев, нанёс брату Мусе решительное поражение при Чамурлу; Муса был убит при бегстве. Румелия, бывшая в руках Мусы, вместе с Эдирне перешла к Мехмеду, и Мехмед-челеби провозгласил себя в Эдирне единственным правителем Османского государства. Одиннадцатилетний период Фетрета закончился, доли шехзаде на карте слились в одно тело.", "649e53b7"]},
"OLAYLAR_EK3:1683-01-01:0":{"b": ["Решение о венском походе — Вашварский мир не был возобновлён, цель изменена с Дьёр на Вену", "1bf278f2"], "d": ["Император Леопольд I хотел возобновления Вашварского договора, срок которого ещё не истёк, и Мехмед IV также, по-видимому, склонялся к миру. Великий везирь Мерзифонлу Кара Мустафа-паша же, ссылаясь на жалобы Имре Тёкёли, провозглашённого королём Средней Венгрии, не допустил возобновления мира; он привёл в движение проповедников во главе с Вани Мехмед-эфенди и убедил падишаха на войну. На совещании было решено, что падишах останется в Белграде, а сердар-и экрем двинется на взятие Дьёр; однако на совещании в Секешфехерваре цель, несмотря на возражения крымского хана Мурад-Гирея и будинского наместника Узун Ибрахим-паши, была изменена на осаду Вены.", "7a572168"]},
"OLAYLAR_EK3:1683-07-14:0":{"b": ["Началась вторая осада Вены — армия перед Веной", "bb542e49"], "d": ["Османская армия под командованием великого везиря Кара Мустафа-паши 14 июля 1683 года подошла к Вене. Император Леопольд I оставил защиту города Штарембергу и удалился вглубь Австрии. Эта вторая осада, в отличие от первой, подготовленная с прямой целью Вены, продлится до 12 сентября.", "ecea5576"]},
"OLAYLAR_EK3:1683-10-09:0":{"b": ["Разгром при Парканах и потеря Эстергома", "a7366740"], "d": ["Армия, отступавшая от Вены, вторично потерпела разгром при Парканах; затем пал Эстергом, одна из ключевых крепостей Венгрии. Отступление начало превращаться в крах.", "13a860f4"]},
"OLAYLAR_EK3:1683-12-25:0":{"b": ["Казнь Мерзифонлу Кара Мустафа-паши", "ce8b10ac"], "d": ["Великий везирь, считавшийся ответственным за венский разгром, был задушен в Белграде; но его казнь не исправила ни фронта, ни пошатнувшегося авторитета государства.", "23449e61"]},
"OLAYLAR_EK3:1684-03-05:0":{"b": ["Образована Священная лига", "060280d0"], "d": ["По почину папства между Австрией, Польшей и Венецией против османов была образована Священная лига (Мукаддес иттифак); в 1686 году присоединилась и Россия. Таким образом империя вступила в многофронтовую войну, которая продлится шестнадцать лет.", "5f02a851"]},
"OLAYLAR_EK3:1684-07-14:0":{"b": ["Первая оборона Буды", "ccc43630"], "d": ["Первая осада Буды войском Священной лиги была отражена упорной четырёхмесячной обороной крепости; но крепости в Венгрии продолжали падать одна за другой.", "fb62dd75"]},
"OLAYLAR_EK3:1685-08-19:0":{"b": ["Потеря Нове-Замки", "689ab78c"], "d": ["Крепость Нове-Замки, двадцать два года остававшаяся в руках османов и ставшая в Европе пословицей, пала; османское присутствие в Верхней Венгрии распалось.", "559f5062"]},
"OLAYLAR_EK3:1685-10-15:0":{"b": ["Арест Тёкёли в Варе — распад Королевства Средней Венгрии, сдача крепостей Верхней Венгрии", "1741aaaf"], "d": ["После венского разгрома османы стали видеть и в Тёкёли одного из виновников войны и поражения. 15 октября 1685 года по приказу сердара Мелек Ибрахим-паши варадский бейлербей Ахмед-паша велел схватить пришедшего на помощь Тёкёли; надеялись, передав его Габсбургам, добиться лучших условий мира. Когда весть об аресте распространилась, все крепости и города Королевства Средней Венгрии, за исключением Мукачева, который защищала его жена Илона Зриньи, сдались Габсбургам; большая часть куруцких солдат перешла в габсбургскую армию. Когда Тёкёли 2 января 1686 года был освобождён в Белграде, королевства уже не существовало.", "1a00b9f3"]},
"OLAYLAR_EK3:1686-09-02:0":{"b": ["Потеря Буды — 145-летней венгерской столицы", "70800e2b"], "d": ["Буда пала в конце осады, длившейся семьдесят восемь дней; последний бейлербей Абдуррахман Абди-паша погиб на стенах как шехид. Потеря города, находившегося под османским управлением с 1541 года, считается символом утраты Венгрии. В тот же день утрачены также: Пешт.", "e66f909f"]},
"OLAYLAR_EK3:1687-08-12:0":{"b": ["Разгром при Втором Мохаче (Харшань) — потеря Трансильвании и Мохача", "a7922681"], "d": ["На равнине, где в 1526 году была одержана большая победа, на этот раз потерпели тяжёлое поражение; армия рассеялась, взбунтовавшиеся солдаты добились смещения великого везиря. Поражение привело и к потере Трансильвании.", "6b95b7d0"]},
"OLAYLAR_EK3:1687-09-26:0":{"b": ["Потеря Афин и взрыв Парфенона", "b6691730"], "d": ["Бомба, выпущенная венецианской артиллерией, взорвала Парфенон, использовавшийся османами как пороховой склад; двухтысячелетний храм превратился в руины. Город перешёл в руки Венеции (будет возвращён в 1688 году).", "e28ad137"]},
"OLAYLAR_EK3:1687-11-08:0":{"b": ["Низложение Мехмеда IV и восшествие Сулеймана II", "9f53037c"], "d": ["После катастроф на фронте и бунта армии Мехмед IV был низложен после 39-летнего правления; на его место был возведён его брат Сулейман II, сорок лет содержавшийся в клетке.", "6a7bb845"]},
"OLAYLAR_EK3:1688-09-06:0":{"b": ["Первая потеря Белграда — осада Священной лиги", "c6b9b19a"], "d": ["Белград, с 1521 года находившийся в османских руках, сдался армии Священной лиги; ворота Сербии были открыты врагу, а опасность подступила к линии Ниш — София. Другой населённый пункт, перешедший в атласе от Османской империи к Габсбургам в тот же день: Гроцка (Hisarcık) — следует цепи старшего центра Белграда (TDV belgrad; декларированное приближение).", "ba09a1ad"]},
"OLAYLAR_EK3:1689-08-01:0":{"b": ["Баден перешёл Мораву у Пожареваца — Пожаревац пал к Австрии", "bcf3fc59"], "d": ["Маркграф Людвиг фон Баден в августе 1689 года перешёл Мораву у Пожареваца и двинулся в направлении Ниша; город оставался в австрийских руках до лета 1690 года (ТДВ suleyman-ii говорит, что Пожаревац был возвращён в 1690 году). Чтение Гюна и Рёдера в этом сеансе заново не проверено.", "28e54b6c"]},
"OLAYLAR_EK3:1689-09-24:0":{"b": ["Потеря Ниша — продвижение Габсбургов (короны Венгерского королевства), самый критический год", "c5e27b3f"], "d": ["Продвижение Габсбургов (короны Венгерского королевства) отняло у османского управления и Ниш; набеги дошли до Скопье и Приштины. Видин же пал позднее, в октябре 1689 года (отдельная статья). В самый тёмный год войны государство чувствовало угрозу даже для своей столицы.", "77de2b1f"]},
"OLAYLAR_EK3:1689-10-25:0":{"b": ["Орсова и Fethülislâm взяты австрийским гарнизоном", "ee8dd875"], "d": ["После взятия Видина без боя (октябрь 1689 года, ТДВ vidin) Баден 25 октября 1689 года отремонтировал и занял гарнизонами Орсову и Fethülislâm; Орсова оставалась у Австрии до осени 1690 года. Дата опирается на Банлаки/Рёдера, в этом сеансе заново не проверена.", "4c6ebd2c"]},
"OLAYLAR_EK3:1690-09-27:0":{"b": ["Ниш снова у османов", "0c4f44eb"], "d": ["Fâzıl Mustafa-паша выступил в поход в июле 1690 года; после взятия Şehirköy, Пожаревца и Güvercinlik осаждённый Ниш 27 сентября 1690 года перешёл в руки османов (TDV semendire). Тогда же был возвращён и Видин. Другие населённые пункты, вернувшиеся в атласе от Габсбургов к Османской империи в тот же день: Ягодина и Прокупье — день на уровне места не найден, взят день Ниша (TDV semendire; декларированное приближение; Röder 1842 пишет, что визирь проходил через Ягодину 8-24 сентября, противоречие не разрешено).", "ec6a2b00"]},
"OLAYLAR_EK3:1690-10-01:0":{"b": ["Австрийские войска в Смедерево сдались", "90da20c4"], "d": ["После взятия Ниша 27 сентября 1690 года австрийские войска в Смедерево сдались после четырёхдневной осады (ТДВ semendire). Банлаки/Рёдер называет 24 сентября; источники противоречат друг другу, за основу принят ТДВ.", "9034a37d"]},
"OLAYLAR_EK3:1690-10-08:0":{"b": ["Белград возвращён", "ab435838"], "d": ["Великий визирь Köprülüzâde Fâzıl Mustafa-паша 8 октября 1690 года вернул Белград у Австрии; город, потерянный в 1688 году, таким образом вернулся к Османской империи (TDV suleyman-ii). Другой населённый пункт, вернувшийся в атласе от Габсбургов к Османской империи в тот же день: Гроцка (Hisarcık) — следует цепи старшего центра Белграда (TDV suleyman-ii; декларированное приближение).", "5b889cb0"]},
"OLAYLAR_EK3:1691-08-19:0":{"b": ["Разгром при Сланкамене — Фазыл Мустафа-паша погиб как шехид", "10d626f1"], "d": ["В одном из самых кровопролитных полевых сражений столетия великий везирь, простреленный в лоб, пал как шехид; армия рассеялась. С этим сражением угасла надежда на восстановление.", "36dfe6ea"]},
"OLAYLAR_EK3:1694-09-21:0":{"b": ["Потеря острова Хиос", "07c084f8"], "d": ["Венецианский флот оккупировал Хиос; османское господство в Эгейском море оказалось под угрозой. Остров будет возвращён на следующий год.", "f5f59c77"]},
"OLAYLAR_EK3:1695-02-11:0":{"b": ["Решение Мустафы II лично выйти в поход", "61c3ba9c"], "d": ["Новый падишах, следуя пути предков, объявил, что выйдет в поход во главе армии; это решение вызвало подъём духа в армии и начало эпоху личных походов, которая продлится два года.", "2794ae0f"]},
"OLAYLAR_EK3:1695-02-22:0":{"b": ["Возвращение Хиоса", "6b496fca"], "d": ["Мезоморто Хусейн-паша, победивший венецианский флот в морских сражениях у островов Койун-Адалары, вернул Хиос; это стало знаком краткого оживления в османском мореплавании.", "7638e074"]},
"OLAYLAR_EK3:1695-09-22:0":{"b": ["Победа при Лугоже — первый австрийский поход Мустафы II", "d5ee9b34"], "d": ["В первом походе, в котором султан участвовал лично, была возвращена Липова, а при Лугоже австрийские силы были разбиты; в цепи поражений, продолжавшейся годами, произошёл первый перелом. Атлас считает, что и Карансебеш в этом походе вернулся от Габсбургов к Османской империи; источник даёт лишь сентябрь 1695 года (TDV mustafa-ii), день атласа взят из записи о Лугоже (декларированное приближение).", "a6411d61"]},
"OLAYLAR_EK3:1696-07-19:0":{"b": ["Потеря крепости Азов", "2b78b5cd"], "d": ["Пётр I, стремившийся выйти к Чёрному морю, взял Азов во второй осаде; Россия впервые прочно обосновалась в одной из османских крепостей и сделала первый шаг на пути к превращению в морскую державу.", "b765c903"]},
"OLAYLAR_EK3:1696-08-27:0":{"b": ["Победа при Улаше (Олашин)", "02ac9ca8"], "d": ["Победа, одержанная во втором походе падишаха на берегу Дуная, сорвала австрийский план взятия Темешвара; однако она не изменила общего баланса войны.", "b6e2d27a"]},
"OLAYLAR_EK3:1697-09-11:0":{"b": ["Разгром при Зенте — судьба войны решена", "475c4a7b"], "d": ["При переправе через реку Тису армия подверглась внезапному нападению принца Евгения; силы, разделённые на двух берегах реки, были уничтожены за несколько часов, погибли тысячи воинов и государственных деятелей, включая великого везиря Эльмас Мехмед-пашу. Зента, одно из самых тяжёлых поражений в османской истории, сделала мирные переговоры неизбежными.", "ced10fdc"]},
"OLAYLAR_EK3:1698-11-13:0":{"b": ["Начались карловицкие мирные переговоры", "1f395cf3"], "d": ["На переговорах, начавшихся при посредничестве Англии и Голландии, османская делегация впервые была вынуждена принять принцип «uti possidetis» (сохранение занятого); переговоры, продолжавшиеся семьдесят две сессии, считаются рождением современной османской дипломатии.", "1d41e9e8"]},
"OLAYLAR_EK4:1801-03-08:0":{"b": ["Мехмед Али из Кавалы высадился в Египте", "514c943f"], "d": ["В составе османской армии, посланной для возвращения оккупированного французами Египта, был и добровольческий отряд, набранный в Кавале. Мехмед Али, которому было за тридцать, был вторым командиром этого отряда; он ступил на землю Египта не как наместник, а как офицер роты.", "b7e3bb36"]},
"OLAYLAR_EK4:1803-05-01:0":{"b": ["Албанские солдаты свергли правителя Египта", "c76a0ec2"], "d": ["Албанские части, которым не выплачивали жалованье, подняли мятеж и вынудили правителя Хусрев-пашу бежать из цитадели. В образовавшемся после ухода французов вакууме мамлюкские беи, албанский оджак и назначаемые Высокой Портой правители вступили в трёхстороннюю борьбу; Мухаммед Али выдвинулся, сумев сбалансировать силы в этом треугольнике. В тот же день утрачено также: Таиф.", "669d61a0"]},
"OLAYLAR_EK4:1805-05:0":{"b": ["Каирские улемы провозгласили Мухаммеда Али правителем", "a16752f2"], "d": ["Измученные налоговым гнётом каирские торговцы и улемы под предводительством накиб аль-ашрафа Омара Макрама восстали, объявили, что не признают правителя Хуршид-пашу, и возвели Мухаммеда Али на пост правителя. Избрание правителя народом — редкий случай в османской истории.", "1572b66f"]},
"OLAYLAR_EK4:1805-07-03:0":{"b": ["Высокая Порта признала свершившийся факт: ферман о правлении в Египте", "b86736a3"], "d": ["Не имея в Египте сил, чтобы отстоять своего кандидата, Высокая Порта направила Мухаммеду Али ферман о наместничестве в Египте с саном визиря. На карте Египет с этой даты переходит в слой подчинённых территорий (светлый тон): юридически это османская земля, фактически — страна династии Кавалалы. В тот же день в слой подчинённых территорий перешли также: Каир, Александрия, Дамьетта, Асьют, Асуан, Ибрим, Суэц, Рашид (Розетта).", "e769c607"]},
"OLAYLAR_EK4:1807-03-17:0":{"b": ["Английская экспедиция Фрейзера высадилась в Александрии", "4d6c31be"], "d": ["В ответ на сближение Османской империи с Францией Англия направила в Египет десантный корпус. Мухаммед Али в то время воевал с мамлюками в Верхнем Египте; он быстро вернулся и организовал оборону.", "fd5f278f"]},
"OLAYLAR_EK4:1807-04-21:0":{"b": ["Разгром у Рашида (Розетты) — англичане отброшены", "3636004c"], "d": ["Английская колонна, вошедшая в город Рашид, понесла тяжёлые потери в уличных боях; в сентябре войска полностью покинули Египет. Эта победа упрочила авторитет Мухаммеда Али как в Египте, так и в Стамбуле.", "68a2ba26"]},
"OLAYLAR_EK4:1811-03-01:0":{"b": ["Бойня в цитадели: истребление мамлюкских беев", "84030b97"], "d": ["Мамлюкские беи, приглашённые на торжественную церемонию по случаю хиджазского похода, были заперты в узком проходе Каирской цитадели и уничтожены. Так закончилось пятисотлетнее влияние мамлюков, и у Мухаммеда Али в Египте не осталось соперников.", "1ca00e33"]},
"OLAYLAR_EK4:1811-09-03:0":{"b": ["Начался хиджазский поход — армия двинулась к Янбу из Суэца морем, а по паломническому пути сушей", "1c05c159"], "d": ["Возвращение Харамейна, с 1803 года находившегося под властью саудитов-ваххабитов, было для Махмуда II важнейшим вопросом легитимности; поскольку сил у Высокой Порты не хватало, задача была возложена на правителя Египта. Мухаммед Али направил во главе армии своего шестнадцатилетнего сына Тусуна.", "5e614d69"]},
"OLAYLAR_EK4:1811-10-01:0":{"b": ["Янбу взят — первая прибрежная база хиджазского похода", "179bc78d"], "d": ["Около двух тысяч албанских пехотинцев, отплывших из Суэца на недавно построенных судах, высадились близ Янбу в октябре 1811 года; после двухдневного слабого сопротивления город сдался. Кавалерия под командованием Тусуна двигалась сушей по паломническому пути через Акабу и Вадж и достигла Янбу лишь две недели спустя. Янбу стал первой базой египетской армии в Хиджазе, выступавшей на Медину и Мекку.", "cfc2ed8a"]},
"OLAYLAR_EK4:1812-01-01:0":{"b": ["Первое поражение в ущелье Сафра-Джедида", "99ef804d"], "d": ["Египетский авангард, попавший в засаду в узких горных проходах, был рассеян. Поражение стало тактическим уроком похода: стало ясно, что без поддержки бедуинских племён двигаться по Хиджазу невозможно.", "765dd19d"]},
"OLAYLAR_EK4:1812-12-03:0":{"b": ["Медина возвращена", "6f6a5d55"], "d": ["После долгой осады Медина сдалась. Возвращение города Пророка отмечали в Стамбуле пушечными салютами; в награду Мухаммеду Али было передано и наместничество в Джидде.", "45cc4c79"]},
"OLAYLAR_EK4:1813-01-23:0":{"b": ["Мекка возвращена — паломнический путь открыт", "3d6d66a0"], "d": ["Египетские войска, вступив в Мекку, снова велели читать в Каабе хутбу от имени османского падишаха. Паломнические караваны, прерванные на десять лет, смогли вновь отправиться в путь. На карте Хиджаз возвращается под османскую власть, но, поскольку управляется из Каира, показан тоном подчинённых территорий. В тот же день под подчинённое управление перешло также: Джидда.", "f0970e28"]},
"OLAYLAR_EK4:1813-05-02:0":{"b": ["Возвращение Таифа — завершение хиджазского похода", "6315fb31"], "d": ["После Медины (декабрь 1812) и Мекки (январь 1813) египетская армия под командованием Тосун-паши в последнюю очередь отвоевала Таиф у ваххабитов. Десятилетнее владычество саудитов закончилось, и три священных центра Хиджаза вновь оказались под османско-египетским контролем.", "374bf563"]},
"OLAYLAR_EK4:1813-08-28:0":{"b": ["Мухаммед Али лично отправился в Хиджаз", "fda0ea2d"], "d": ["Видя, что поход затягивается, правитель взял управление в свои руки; торгуясь с вождями племён, он пытался разложить саудитский фронт изнутри. Благодаря этому походу выросла и доля Египта в торговле Красного моря.", "aeb051d1"]},
"OLAYLAR_EK4:1815-01-20:0":{"b": ["Битва при Бисель: разгром саудовских сил", "9c9ab91f"], "d": ["Саудиды, потерпевшие тяжёлое поражение в полевом сражении, отошли во внутренние области. Заключённое перемирие не стало прочным; два года спустя операции будут перенесены в сердце Неджда. Атлас считает, что после этой победы Турабе и Хурма к востоку от Таифа вышли из саудовских рук (источник события — Lorimer, Gazetteer; свидетельство по самим пунктам и день 13 января — декларированное приближение).", "551e1880"]},
"OLAYLAR_EK4:1816-09-01:0":{"b": ["Ибрахим-паша выступил в Недждский поход", "d5ed80d1"], "d": ["Приняв командование после смерти брата Тусуна, Ибрахим-паша начал тяжёлый двухлетний поход по пустыне. Продвигаясь от колодца к колодцу и по одному устраняя племена, армия подошла к столице саудитов.", "e84c2cef"]},
"OLAYLAR_EK4:1818-09-09:0":{"b": ["Дирия пала — первое Саудовское государство прекратило существование", "aa96206d"], "d": ["После шестимесячной осады Дирия сдалась и была разрушена. Эмир Абдулла б. Сауд был отправлен в Стамбул и казнён. Османское знамя впервые проникло в глубь Аравии так далеко; гарнизон в Неджде оставался до 1824 года. В тот же день присоединено также: Дирия (Неджд).", "4b161cf5"]},
"OLAYLAR_EK4:1820-07-20:0":{"b": ["Начался суданский поход", "b1fc6905"], "d": ["Цель Мухаммеда Али была троякой: набрать солдат в свою армию, добраться до золота Сеннара и уничтожить уцелевших бежавших мамлюков. Войска под командованием его сына Исмаил-паши двинулись на юг вдоль Нила.", "478563e9"]},
"OLAYLAR_EK4:1820-11-01:0":{"b": ["Донгола без боя переходит к египетской армии (мамлюки покинули её в июне 1820 года)", "bc5942c0"], "d": ["Донгола, расположенная на большой излучине Нила, без насилия перешла в руки египетской армии Исмаил-паши после того, как мамлюки покинули её в июне 1820 года. На карте Судан с этой даты появляется в зависимом слое: завоеватель — Каир, и править тоже будет Каир.", "61ac03d6"]},
"OLAYLAR_EK4:1820-12-04:0":{"b": ["Сражение при Джебель ад-Дайка — конфедерация шайкия решительно разбита египетской армией", "befc9539"], "d": ["Через месяц после первой схватки у Курти армия Исмаил-паши, сына Мухаммеда Али-паши, разбила шайкия во втором, решающем сражении близ Джебель ад-Дайка. Вождь шайкия Макк Субайр сдался; Макк Шавиш продолжил сопротивление. С тех пор египетское господство над излучиной Нила стало прочным.", "5e0734a7"]},
"OLAYLAR_EK4:1821-06-14:0":{"b": ["Сеннарский (Фунджский) султанат сдался", "3cac7dd2"], "d": ["Трёхвековая династия Фунджей сдалась без боя. В том же году лагерь, основанный в месте слияния двух рукавов Нила, вскоре превратился в Хартум, административный центр Судана. В тот же день присоединено также: Сеннар.", "1ad105c1"]},
"OLAYLAR_EK4:1821-08-19:0":{"b": ["Взят Кордофан", "06440602"], "d": ["Вторая колонна, посланная на запад, разбила при Bâre (Bâra) силы Дарфура и вместе с окрестностями Нухуда взяла Кордофан. Египетское господство в Судане таким образом распространилось из долины Нила на западные степи.", "6bc3a4f6"]},
"OLAYLAR_EK4:1822-06-28:0":{"b": ["Египетские войска высадились на Крите", "835aee90"], "d": ["Когда греческое восстание перекинулось на Крит, Высокая Порта потребовала направить на остров египетские силы. Влияние Мухаммеда Али на острове началось с этого вмешательства и восемь лет спустя завершилось передачей ему наместничества на Крите.", "8d651366"]},
"OLAYLAR_EK4:1822-10-24:0":{"b": ["Убийство Исмаил-паши в Шенди", "223860c9"], "d": ["Местный эмир Немир, разгневанный тяжёлыми налогами и требованиями рекрутов, поджёг дом, в котором остановился Исмаил-паша, и сжёг его вместе со свитой. Карательный поход превратил край в море крови; с тех пор управление Суданом строилось на жестокости.", "722af711"]},
"OLAYLAR_EK4:1824-07-19:0":{"b": ["Махмуд II попросил у Мухаммеда Али помощи в Морее", "03594a42"], "d": ["Не сумев за три года подавить восстание в Морее янычарской армией, падишах обратился к египетской армии, обученной по европейскому образцу. В обмен ему были обещаны наместничество в Морее и Крит. Эта просьба была первым открытым признанием того, что империя нуждается в помощи ради собственной провинции.", "1b0ee342"]},
"OLAYLAR_EK4:1825-02-24:0":{"b": ["Ибрахим-паша высадился в Модоне", "9c993dba"], "d": ["Десант под прикрытием египетского флота ступил на юго-западную оконечность Мореи. Эта армия, оснащённая регулярной пехотой и полевой артиллерией, вскоре добилась превосходства над отрядами повстанцев.", "edf38fca"]},
"OLAYLAR_EK4:1825-06-22:0":{"b": ["Триполица возвращена — центр Мореи пал", "8a478c11"], "d": ["С падением Триполицы, административного центра восстания, большая часть Мореи вновь оказалась под контролем. На карте полуостров показан тоном подчинённых территорий, поскольку находится в руках египетских сил.", "e7d9b818"]},
"OLAYLAR_EK4:1826-04-22:0":{"b": ["Миссолонгион (Месолонги) пал", "07257f87"], "d": ["После годичной осады город был взят. Однако отклик, который оборона вызвала в европейской печати, довёл сочувствие к греческому делу до предела и подготовил почву для вмешательства великих держав.", "9bf1efc2"]},
"OLAYLAR_EK4:1827-06-05:0":{"b": ["Афинский Акрополь сдан", "3b19f946"], "d": ["С падением Акрополя греческое восстание было в военном отношении почти закончено. Именно в этот момент вопрос перестал быть внутренним мятежом и стал предметом европейской дипломатии.", "e096fc52"]},
"OLAYLAR_EK4:1827-07-06:0":{"b": ["Лондонский договор: три державы навязали автономию Греции", "7ce46fd8"], "d": ["Англия, Франция и Россия приняли решение действовать совместно, чтобы заставить Османскую империю и греков принять перемирие и условие автономии; было объявлено, что в случае отказа вмешаются их флоты. Высокая Порта отвергла предложение.", "8382f516"]},
"OLAYLAR_EK4:1828-08-06:0":{"b": ["Александрийская конвенция: решение Египта уйти из Мореи", "cc978f37"], "d": ["Потеряв флот при Наварине, Мухаммед Али, не советуясь со Стамбулом, напрямую договорился с английским адмиралом и согласился вывести войска из Мореи. Заключение самостоятельного соглашения с великими державами правителем провинции было предвестием будущего кризиса.", "9430ea24"]},
"OLAYLAR_EK4:1828-10-05:0":{"b": ["Египетские войска оставили Морею", "8fb742dd"], "d": ["Последние части были посажены на корабли; полуостров фактически был потерян и по Лондонскому протоколу 1830 года стал ядром независимой Греции. Мухаммед Али же не получил обещанного наместничества в Морее и потерял взамен большой флот и армию. В тот же день утрачено также: Модон, Корон.", "7bfbefe0"]},
"OLAYLAR_EK4:1830-11-01:0":{"b": ["Управление Критом передано Мухаммеду Али", "7f76396d"], "d": ["В возмещение утраты Мореи наместничество на Крите было отдано Мухаммеду Али. Остров десять лет управлялся из Каира; на карте в этот период он показан тоном подчинённых территорий. В тот же день присоединено также: Кандия (Крит).", "5b000d2b"]},
"OLAYLAR_EK4:1831-10-31:0":{"b": ["Ибрахим-паша вступил в Сирию — начался первый кризис", "1a5cc386"], "d": ["Поводом послужил правитель Акки, не выдававший бежавших из Египта феллахов; настоящей причиной была потребность Мухаммеда Али в сирийском лесе, портах и людских ресурсах. Армия пересекла Синай и быстро заняла палестинское побережье.", "9d41b0f9"]},
"OLAYLAR_EK4:1831-11-26:0":{"b": ["Началась осада Акки", "b211d96d"], "d": ["Крепость, остановившая Наполеона в 1799 году, оборонялась шесть месяцев. Осада стала первым большим испытанием современной артиллерии египетской армии.", "97d9816b"]},
"OLAYLAR_EK4:1832-05-27:0":{"b": ["Акка пала", "0f47917b"], "d": ["Когда батареи, бившие по стенам, пробили брешь, крепость была взята. Ворота Сирии были открыты; в те же дни Высокая Порта объявила Мухаммеда Али мятежником и отменила его наместничество.", "f92b4224"]},
"OLAYLAR_EK4:1832-06-16:0":{"b": ["Дамаск сдался", "48da3b62"], "d": ["Город сдался без боя. Ибрахим-паша, объявив налоговый порядок и равенство, предоставленное немусульманам, пытался завоевать поддержку местного населения; эти же меры несколько лет спустя стали причиной восстаний против него. В те же дни присоединено также: Бейрут, Триполи, Сайда.", "c67bd97e"]},
"OLAYLAR_EK4:1832-07-08:0":{"b": ["Сражение при Хомсе", "867810ee"], "d": ["Османская армия, посланная освободить Сирию, была разгромлена на открытой местности. Стало видно, что новая армия, созданная через шесть лет после упразднения янычарства, ещё не готова.", "f429ba2e"]},
"OLAYLAR_EK4:1832-07-15:0":{"b": ["Алеппо захвачен", "9c0ead76"], "d": ["Пал и торговый и административный центр Северной Сирии. Так египетская армия вышла к предгорьям Тавра и направилась к проходам у ворот Анатолии.", "b8b4a1bd"]},
"OLAYLAR_EK4:1832-07-29:0":{"b": ["Разгром у перевала Белен (Бейлан) — открыта Чукурова", "4bae872b"], "d": ["Оборонительная линия в узком проходе в горах Аманос была прорвана. Антакья, Адана и Тарс перешли к египетским силам (занятие Мараша, по TDV, относится к 1833 году и является отдельной записью); на карте Чукурова возвращается к тону подчинённых территорий. Дорога в глубь Анатолии оказалась беззащитной.", "73cb1c5e"]},
"OLAYLAR_EK4:1832-09-13:0":{"b": ["Пал перевал Gülek — побережье İçil (Мерсин, Силифке) перешло под контроль Египта", "d9049b5b"], "d": ["Ворота Тавра в Чукурову, перевал Gülek, оказались в руках египетской армии. Ибрахим-паша назначил в санджак İçil своего мютеселлима, и все пристани на побережье перешли под контроль Египта. На карте Мерсин и Силифке с этого дня показаны зависимыми от Египта (нижняя граница; дня назначения в источнике нет); поскольку в Кютахийском решении упоминается лишь мухассыльство Аданы, этот контроль заканчивается с эвакуацией из Анатолии.", "fa650158"]},
"OLAYLAR_EK4:1832-09-13:1":{"b": ["Конийский Эрегли под египетской оккупацией — горловина Тавра на дороге Конья–Адана", "fb908900"], "d": ["Эрегли, лежавший на пути к Конье египетской армии, преодолевшей перевал Gülek, в 1832 году попал под оккупацию Ибрахим-паши, а когда по Кютахийскому урегулированию 1833 года был освобождён, вновь был присоединён к вилайету Караман. На карте это промежуточная, подкреплённая источником точка линии оккупации между Аданой и Коньей; для Улукышлы и Карапынара свидетельств на уровне города найти не удалось.", "c5c7c153"]},
"OLAYLAR_EK4:1832-11-21:0":{"b": ["Египетская армия вступила в Конью", "13952a2d"], "d": ["Перейдя Тавр, армия достигла Центральной Анатолии. Силы османского наместника впервые продвигались по коренным землям империи. В тот же день присоединено также: Караман.", "569bd202"]},
"OLAYLAR_EK4:1832-12-21:0":{"b": ["Сражение при Конье: великий визирь попал в плен", "ec82cc9a"], "d": ["Османская армия, рассеявшаяся в туманную погоду, потерпела тяжёлое поражение, а великий визирь Решид Мехмед-паша был взят в плен. Центральной армии государства больше не существовало; между Стамбулом и египетскими силами не осталось никакой силы, способной их остановить.", "30e73138"]},
"OLAYLAR_EK4:1833-01-01:0":{"b": ["Мараш подвергся египетской оккупации", "f558e383"], "d": ["По TDV, Мараш в 1833 году был оккупирован Кавалалы Ибрахим-пашой и почти девятнадцать месяцев оставался под его управлением. Поскольку Мараш остался за пределами границ эялетов по Кютахийскому урегулированию, это управление является не юридическим, а фактическим.", "3d3c898a"]},
"OLAYLAR_EK4:1833-01-01:1":{"b": ["Карахисар-и Сахиб (Афьон) подвергся египетской оккупации — дорога Конья–Кютахья", "ae0c2c78"], "d": ["Карахисар-и Сахиб, лежавший на пути египетской армии, наступавшей на Кютахью после сражения при Конье, в 1833 году некоторое время находился в руках Ибрахим-паши. На карте это промежуточная, подкреплённая источником точка линии оккупации между Коньей и Кютахьей; для Акшехира, Ылгына и Исхаклы свидетельств на уровне города найти не удалось, они показаны в османском цвете.", "bce0b466"]},
"OLAYLAR_EK4:1833-02-02:0":{"b": ["Египетская армия достигла Кютахьи", "214f8df6"], "d": ["Ибрахим-паша остановился в Кютахье, в трёх переходах от Стамбула. Его остановка была не военной, а политической: были учтены русское вмешательство и реакция Европы.", "0f1c5f03"]},
"OLAYLAR_EK4:1833-02-20:0":{"b": ["Русский флот у Бююкдере", "6f836d61"], "d": ["Не получив помощи от Англии и Франции, Махмуд II обратился к вчерашнему врагу — России. Это решение падишаха, вошедшее в историю словами «утопающий хватается за змею», закончилось высадкой русских солдат на проливах и вызвало в Европе тревогу.", "3e402e00"]},
"OLAYLAR_EK4:1833-05-06:0":{"b": ["Кютахьинское соглашение (устное) — Сирия и Адана отданы Кавалалы", "25fe9985"], "d": ["Высокая Порта оставила Мехмеду Али, помимо Египта, Крита и Хиджаза, также правление Дамаска, Алеппо, Триполи и Сайды, а Ибрахим-паше — мухассыльство Аданы. Взамен армия отошла к югу от Тавра. Это был не договор, а фирманы султана, данные наместнику, — вопрос не был решён, а отложен.", "4160e4f4"]},
"OLAYLAR_EK4:1833-06-15:0":{"b": ["Вывод египетской армии из Анатолии завершён через Gülek", "a53ac2a3"], "d": ["После Кютахийского урегулирования египетские войска покинули Анатолию; к середине июня вся армия прошла через перевал Gülek в Чукурову. Побережье İçil (Мерсин, Силифке) вновь возвращается под османское управление; мухассыльство Аданы и Сирия остаются за Египтом.", "c5e13625"]},
"OLAYLAR_EK4:1833-07-08:0":{"b": ["Ункяр-Искелесийский договор", "da741d5c"], "d": ["С Россией был подписан восьмилетний союз взаимной обороны. По секретной статье Османская империя должна была закрыть проливы для военных кораблей, если Россия подвергнется нападению. Это стало одним из самых спорных решений османской дипломатии и сделало Англию активным участником в египетском вопросе.", "43dc2c96"]},
"OLAYLAR_EK4:1834-05-19:0":{"b": ["Восстание в Палестине (Наблус) против египетского управления", "4fe43e27"], "d": ["Обязательная воинская повинность, сбор оружия и новые налоги вызвали в Палестине широкое восстание. Оно было жестоко подавлено; поддержка египетского управления среди местного населения быстро иссякла.", "2a3301a2"]},
"OLAYLAR_EK4:1834-08-01:0":{"b": ["Конец египетского управления в Мараше (приблизительно)", "bb46ca42"], "d": ["Если отсчитывать фразу TDV «почти девятнадцать месяцев» от оккупации 1833 года, египетское управление заканчивается около лета 1834 года. То, что Мустафа-бей из Küçükalioğulları в 1834 году не смог противостоять египетской армии и отошёл в сторону Мараша, также показывает, что Мараш в то время был убежищем вне египетского контроля.", "fbb6814a"]},
"OLAYLAR_EK4:1837-10-15:0":{"b": ["Восстание в Джебель-Друз", "12e74626"], "d": ["Сопротивление, начавшееся в друзском регионе, продолжалось два года. Накопившееся в Сирии недовольство в 1840 году, когда на побережье высадились союзные флоты, должно было оголить тыл египетской армии.", "75c50707"]},
"OLAYLAR_EK4:1838-05-25:0":{"b": ["Мухаммед Али объявил о намерении добиться независимости", "48633bbd"], "d": ["Правитель заявил консулам великих держав, что намерен провозгласить независимость Египта и Сирии. Англия решительно воспротивилась этому: возникновение сильного, близкого к Франции государства в Средиземноморье угрожало бы дороге в Индию.", "d6181bd9"]},
"OLAYLAR_EK4:1839-04-21:0":{"b": ["Османская армия перешла Евфрат", "9af1ea69"], "d": ["Махмуд II двинул армию к сирийской границе, чтобы вернуть потерянное под Кютахьей. Прусский офицер Мольтке, находившийся при армии в качестве советника, возражал против выбора позиции и раннего наступления; его возражения не были услышаны.", "85d5db1c"]},
"OLAYLAR_EK4:1839-06-24:0":{"b": ["Сражение при Незибе — Османская армия рассеяна", "156b3cdf"], "d": ["Плохо расположенная османская армия была разгромлена за несколько часов. Падишах умер, не дождавшись вести о поражении; государство за несколько дней должно было потерять армию, правителя, а затем и флот.", "fb8af82d"]},
"OLAYLAR_EK4:1839-06-28:0":{"b": ["Смерть Махмуда II", "07eccfff"], "d": ["Падишах, за тридцать один год правления упразднивший янычарство и заново выстроивший центральное управление, умер, не одолев своего главного противника. Болезнь не была точно диагностирована. Его смерть скрывали до 30 июня, пока в городе не были приняты военные меры предосторожности из страха перед выступлением янычарского духа.", "3174d901"]},
"OLAYLAR_EK4:1839-07-01:0":{"b": ["Воцарение Абдул-Меджида и похороны Махмуда II", "d0f3d2cc"], "d": ["После смерти отца на престол взошёл шестнадцатилетний Абдул-Меджид. В тот же день тело Махмуда II было доставлено во дворец Топкапы; опасавшихся беспорядков не последовало, в траурной процессии участвовали широкие массы мусульман и немусульман.", "7b398ea4"]},
"OLAYLAR_EK4:1839-07-14:0":{"b": ["Передача флота Александрии", "a53e6103"], "d": ["Капудан-паша Ахмед Февзи-паша, заподозрив, что великий визирь Коджа Хусрев-паша отдаст флот России, увёл флот в Александрию и передал его Мухаммеду Али. В течение одного месяца Османское государство осталось без армии, без падишаха и без флота.", "78a26255"]},
"OLAYLAR_EK4:1839-07-27:0":{"b": ["Совместная нота великих держав", "2a3b8316"], "d": ["Пять держав вручили Высокой Порте ноту, потребовав, чтобы она не заключала соглашения по египетскому вопросу в одиночку. Так внутренний вопрос официально стал «европейским вопросом»; Османское государство фактически лишилось права самостоятельно решать судьбу собственной провинции.", "979e7f0a"]},
"OLAYLAR_EK4:1840-07-15:0":{"b": ["Лондонский договор: четыре державы на стороне Османской империи", "a517f775"], "d": ["Договор, подписанный без Франции, предъявил Мухаммеду Али ультиматум: если он согласится в течение десяти дней — наследственное наместничество в Египте и Акка пожизненно; если в течение двадцати дней — только Египет; если откажется — ничего. Правитель отказался.", "fc066f82"]},
"OLAYLAR_EK4:1840-09-10:0":{"b": ["Бомбардировка Бейрута и высадка союзников", "0905ce92"], "d": ["Англо-австрийский флот обстрелял Бейрут; населению ливанских гор, восставшему против египетского управления, раздали оружие. Контроль Ибрахим-паши над Сирией рухнул между внутренним восстанием и внешним вмешательством.", "743ec7e2"]},
"OLAYLAR_EK4:1840-10-10:0":{"b": ["Бейрут и прибрежные города утрачены", "09bdaf23"], "d": ["После боёв в направлении Баальбека египетские силы отошли от побережья. На карте побережье Ливана выходит из тона подчинённых территорий и возвращается под непосредственное османское управление.", "fe5e95aa"]},
"OLAYLAR_EK4:1840-11-03:0":{"b": ["Акка пала за два часа", "5aec21f0"], "d": ["При обстреле союзного флота взорвался арсенал крепости, и Акка сдалась за несколько часов. Крепость, которую Ибрахим-паша смог взять лишь за шесть месяцев восемью годами ранее, показала превосходство морской артиллерии.", "5cf01edf"]},
"OLAYLAR_EK4:1840-11-27:0":{"b": ["Александрийская конвенция", "85cb47b0"], "d": ["Мухаммед Али согласился отказаться от Сирии, Аданы, Крита и Хиджаза, вернуть османский флот и признать власть падишаха; взамен ему было гарантировано наследственное наместничество в Египте.", "63d90626"]},
"OLAYLAR_EK4:1841-02-25:0":{"b": ["Египетская армия оставила Сирию и Чукурову", "719a28dc"], "d": ["Девятилетняя оккупация закончилась; армия Ибрахим-паши вернулась в Египет через Синай. На карте широкая полоса от Алеппо до Газы, от Аданы до Крита вновь переходит под непосредственное османское управление. В тот же день утрачено также: Урфа, Мараш, Тарс, Антакья, Кандия (Крит), Хама, Дамаск, Иерусалим, Яффа, Наблус.", "a678b17a"]},
"OLAYLAR_EK4:1841-05-24:0":{"b": ["Ферман: наместничество в Египте оставлено семье Кавалалы в наследственное владение", "87b89ff8"], "d": ["Ферман падишаха признал наместничество переходящим внутри династии от отца к сыну; взамен численность армии была сокращена до восемнадцати тысяч, налоги были подчинены Стамбулу, право чеканить монету и заключать договоры было отменено. Египет остался вилайетом, но уже был страной отдельной династии. Управление Хиджазом и Харамейном вернулось к Высокой Порте. В тот же день из слоя подчинённых территорий в слой непосредственного управления вернулись также: Мекка, Медина, Джидда, Янбу.", "48099454"]},
"OLAYLAR_EK4:1841-07-13:0":{"b": ["Лондонская конвенция о проливах", "0e95a1ea"], "d": ["Конвенция, заменившая Ункяр-Искелесийский договор, постановила, что в мирное время проливы закрыты для всех военных кораблей. Привилегия, единолично полученная Россией, таким образом превратилась в общую гарантию Европы; вопрос о проливах получил международный статус.", "5bbbb459"]},
"OLAYLAR_EK4:1848-09-01:0":{"b": ["Ибрахим-паша фактически стал правителем Египта", "9e14f5d9"], "d": ["Вместо старевшего и терявшего рассудок Мухаммеда Али наместником был назначен его сын Ибрахим-паша. Однако несколько месяцев спустя, в ноябре 1848 года, он умер раньше отца.", "338908f8"]},
"OLAYLAR_EK4:1849-08-02:0":{"b": ["Смерть Мухаммеда Али-паши Кавалалы", "871310e0"], "d": ["Наместник, родившийся в Кавале, основавший в Египте династию и дважды подводивший империю к краю пропасти, умер в возрасте восьмидесяти лет. Основанная им династия правила в Египте до 1953 года; государство же, увидев, что рану, которую он нанёс, удалось закрыть лишь европейским вмешательством, пошло по пути Танзимата.", "c0877894"]},
"OLAYLAR_EK5:1086-06-04:0":{"b": ["Сулейман ибн Кутулмыш потерпел поражение и погиб при Aynüseylem; Антиохия вышла из-под власти Анатолийских Сельджуков", "0412dfa1"], "d": ["Сулейман ибн Кутулмыш, взявший Антиохию у Византии в 1084 году, погиб в битве при Aynüseylem с правителем Сирийских Сельджуков Тутушем; город перешёл под контроль султана Великих Сельджуков Мелик-шаха, и наместником был назначен Ягы-Сиян.", "67de3930"]},
"OLAYLAR_EK5:1092-11-20:0":{"b": ["Мелик-шах умер; Антиохия вместе с Ягы-Сияном подчинилась Тутушу Сирийских Сельджуков", "c61da1b4"], "d": ["После смерти султана Великих Сельджуков Мелик-шаха государство было разделено между наследниками; антиохийский наместник Ягы-Сиян подчинился властителю Сирии Тутушу.", "6c441576"]},
"OLAYLAR_EK5:1097-06-19:0":{"b": ["Никея сдалась крестоносцам; центр сельджуков отошёл в Конью, Византия начала возвращать западную Анатолию", "8a4e90fa"], "d": ["После осады Никеи крестоносцами город 19 июня 1097 года сдался Византии; сельджукский султан Кылыч-Арслан I отвёл свой центр вглубь страны, в Конью, а Византия вернула такие места на побережье западной Анатолии, как Эфес.", "c63f0616"]},
"OLAYLAR_EK5:1180-05-28:0":{"b": ["Кылыч-Арслан II взял у Византии Дорилей (Эскишехир) и Кютахью", "3ddee6c2"], "d": ["После Мириокефала (1176) византийские крепости Дорилей и Кютахья внутри Анатолии в последние годы Мануила или после его смерти, в 576/1180 году, перешли в руки Кылыч-Арслана II.", "4358e7d4"]},
"OLAYLAR_EK5:1276-06-15:0":{"b": ["Караманоглу Мехмед-бей назначен субаши Эрменека и взял под управление Ич-иль", "6d62be11"], "d": ["Караманоглу Мехмед-бей в 675 г. х. (1276) был назначен субаши Эрменека и взял Ич-иль под своё управление; Эрменек стал первым центром Караманидов, которым предстояло на следующий год выступить на Конью.", "dc2f3a25"]},
"OLAYLAR_EK5:1281-01-01:0":{"b": ["Смерть Эртугрул-гази и переход Осман-бея к правлению беем — наследие Сёгюта и Доманича", "395fb9fa"], "d": ["По TDV, Эртугрул-гази умер в 680 (1281–82) году; в статье отмечается, что называются и даты 1288 и 1289. Осман-бей унаследовал от отца не завоёванный город, а два пожалования, данные Эртугрулу сельджукским султаном, разместившим его на самой передовой линии пограничной области: зимовье (кышлак) в Söğüt и летнее пастбище в Domaniç. То есть бейлик начал не с завоевательного наследия, а с двух пастбищных пожалований; на карте эти два места показаны не как «завоевание», а как «наследие».", "37fbc33c"]},
"OLAYLAR_EK5:1282-03-30:0":{"b": ["Сицилийская вечерня — Анжуйская династия потеряла остров Сицилию", "547db635"], "d": ["Восстание, вспыхнувшее в Палермо в вечерню пасхального понедельника против власти Карла I Анжуйского, оторвало остров Сицилию от Анжуйской династии. Сицилийское королевство разделилось надвое: остров перешёл к Арагону, а Анжуйская династия удержалась в материковом королевстве с центром в Неаполе. Заморские владения династии на Адриатике и в Средиземноморье также остались при этом королевстве: Корфу, находившийся в её руках с 1267 года, и Драч, который она держала с 1270-х годов, продолжали существовать в составе Неаполитанского королевства; крепости Влёра, Канина и Химара на албанском берегу также остались в неаполитанском королевстве (комендант Влёры John of Taxis в течение 1282 года сопротивлялся византийцам; Драч, Влёра и Канина, вероятно, перешли к Византии в начале 1285 года). Мальта же перешла в руки арагонцев лишь в 1284 году.", "7c8ea21d"]},
"OLAYLAR_EK5:1285-01-01:0":{"b": ["Набег на Kulacahisar — первое военное предприятие Осман-бея", "79b00b14"], "d": ["Статья TDV «Осман I»: «Разграбил и сжёг малую крепость Kulaca близ İnegöl (684/1285)». Это первое датируемое по источникам военное действие Осман-бея. Постоянное поселение захвачено не было, крепость была разграблена и сожжена; поэтому это не столько завоевание, сколько классический пограничный набег. Считается отправной точкой военной деятельности бейлика.", "15ee9a09"]},
"OLAYLAR_EK5:1288-01-01:0":{"b": ["Завоевание Karacahisar — первое городское приобретение и власть над Эскишехиром", "178ae619"], "d": ["Статья TDV «Осман I»: Осман-бей в 687 (1288) году «завоевал Karacahisar и овладел Эскишехиром». Это первое подлинное городское приобретение бейлика, и, по преданию, благодаря этому успеху Осман-бей поднялся до звания санджак-бея на пограничье; передаётся, что первая пятничная хутба от его имени была прочитана в Karacahisar и что сюда был назначен первый кади. В статье TDV «Эскишехир» говорится, что османское предание называет 1291 год, но его достоверность сомнительна.", "90949e22"]},
"OLAYLAR_EK5:1291-05-18:0":{"b": ["Падение Акки перед мамлюками — вытеснение крестоносцев с сирийского побережья: Сайда и Бейрут", "3ca7a464"], "d": ["Акка, долгое время бывшая центром Иерусалимского королевства крестоносцев, была завоёвана мамлюкским султаном аль-Малик аль-Ашрафом Халилем, и господство крестоносцев в Палестине закончилось. Рыцари-тамплиеры, ушедшие из Акки, укрылись в Сайде; когда мамлюкская армия приблизилась, они оставили морскую крепость и бежали на Кипр, а город в то же лето перешёл к мамлюкам. Бейрут, с 1197 года находившийся в руках крестоносцев, также был взят в 1291 году дамасским наместником Сенджером аш-Шуджаи. Так двухвековое присутствие крестоносцев было стёрто с сирийско-палестинского побережья.", "63b3c40c"]},
"OLAYLAR_EK5:1299-01-01:0":{"b": ["Завоевание Биледжика и Yarhisar ночным набегом", "f461b0af"], "d": ["Статья TDV «Биледжик»: «Хотя другие текфуры региона, среди них текфур Биледжика, подготовили покушение на Осман-гази, османские силы, узнав об этом замысле, внезапным набегом завоевали Yarhisar и Биледжик (1299)». Две крепости были взяты в одной операции, в одном ночном набеге. Эта дата — поворотный пункт, принимаемый за год основания Османского государства. В тот же день присоединено также: İnegöl.", "ec452c9e"]},
"OLAYLAR_EK5:1302-07-27:0":{"b": ["Битва при Бафее (Койунхисар) — первая большая победа над византийской армией", "584a9512"], "d": ["Статья TDV «Осман I»: 27 июля 1302 года Осман-бей сразился с византийской армией при Бафее (Койунхисар) и разбил её. Эта победа — поворотный пункт, поднявший Османа из положения областного пограничного бея до статуса основателя династии. После битвы равнина Бурсы перешла под османский контроль, началась блокада Изника.", "b82fb787"]},
"OLAYLAR_EK5:1303-01-01:0":{"b": ["Победа при Dimbos и последовавшее взятие Kite и Ulubat", "e168ab64"], "d": ["Статья TDV «Осман I»: в 702 (1303) году союз текфуров Бурсы, Кестеля, Kite и Adranos был разбит в ущелье Dimbos; противник с боями отступил до самого ущелья, и текфур Кестеля погиб на поле боя. Сразу после победы были захвачены крепости Kite и Ulubat, сухопутная связь Бурсы была прервана и её блокада ужесточена. В этом сражении участвовал и юный Орхан.", "4afb53bf"]},
"OLAYLAR_EK5:1304-01-01:0":{"b": ["Поход на Сакарью: взятие Leblebicihisar, Lefke, Mekece и Geyve", "a51ba4d3"], "d": ["Статья TDV «Осман I» излагает порядок сакарьинского похода 704 (1304) года: «Когда он пришёл к крепости Leblebüci, текфур покорился... Дошёл до Lefke... Достиг Mekece... Направившись в Geyve, взял найденную пустой крепость». Lefke — ворота долины Сакарьи, открывающиеся к Биледжику. Этим одним походом цепь крепостей вдоль долины перешла под османский контроль, и восточный фланг бассейна Изника был закрыт.", "ae2866c2"]},
"OLAYLAR_EK5:1304-01-01:1":{"b": ["Хиос перешёл под контроль генуэзской семьи Дзаккариа", "9eebe4de"], "d": ["Перед угрозой Айдынидов византийский император попросил помощи у генуэзца Бенедетто Дзаккариа; остров перешёл под его контроль (номинальный византийский вассалитет). Господство Дзаккариа продолжалось до 1329 года.", "4d0e4fd8"]},
"OLAYLAR_EK5:1304-01-01:2":{"b": ["Самос перешёл во владение генуэзцев (Дзаккариа) на Хиосе", "0e6f51e3"], "d": ["Генуэзская семья Дзаккариа, взявшая Хиос под свой контроль, присоединила к своим владениям и почти опустевший Самос (TDV: 1304–1329).", "8eb44fb2"]},
"OLAYLAR_EK5:1305-01-01:0":{"b": ["Завоевание крепостей Geyve Boğazı: Karaçepüş, Karatigin и Absu", "76907c78"], "d": ["Статья TDV «Орхан»: в сакарьинском походе 705 (1305) года Орхан «завоевал крепости Karaçepüş (Катойкия), Karatigin перед Изником и Absu (Hypsu: в Geyve Boğazı)». Эти три крепости, перекрыв проход между долиной Сакарьи и бассейном Изника, полностью отрезали Изник от сухопутной помощи. В Karaçepüş и Absu в Geyve Boğazı был поселён Гази Абдуррахман; теперь город можно было взять только голодом.", "d330595f"]},
"OLAYLAR_EK5:1323-09-01:0":{"b": ["Поход на Adranos (Орханели) — последний поход Осман-бея", "4811546c"], "d": ["Статья TDV «Орхан» фиксирует осенний поход 1323 года на крепость Adranos как последний поход Осман-бея. Текфур Adranos входил в союз текфуров, созданный против османов двадцатью годами ранее при Dimbos; этот поход означал сведение тех счётов. Точный день завоевания крепости неизвестен; операция была продолжена Орхан-беем.", "1e8ea25a"]},
"OLAYLAR_EK5:1324-01-01:0":{"b": ["Смерть Осман-гази и переход Орхан-бея к правлению", "021487cd"], "d": ["Осман-гази, давший имя бейлику, умер в 724 (1324) году, о чём свидетельствуют вакфийе Asporça Hatun и Mekece. Его сын Орхан, с 1305 года стоявший во главе армии в походах, после смерти отца занял место во главе бейлика без какой-либо борьбы за престол. Бесконфликтная передача знамени основателями говорит о том, что династия спокойно выдержала первое большое испытание на пути от пограничного бейлика к государству.", "6f95e64a"]},
"OLAYLAR_EK5:1329-01-01:0":{"b": ["Взятие Хиоса у Дзаккариа и подчинение Византии", "f6741b26"], "d": ["Император Андроник III удалил Дзаккариа с острова и подчинил остров Византии под управлением Бенедетто III. В 1346 году остров будет занят генуэзцем Симоне Виньози.", "84f19c2b"]},
"OLAYLAR_EK5:1329-01-01:1":{"b": ["Самос вернулся от Дзаккариа к Византии (хиосская цепь)", "08034974"], "d": ["С падением владения Дзаккариа (подчинением Хиоса Византии в 1329 году) генуэзское владение на Самосе также закончилось.", "314dce74"]},
"OLAYLAR_EK5:1329-06-01:0":{"b": ["Битва при Пелеканоне (Мальтепе) и взятие всего Kocaeli", "389e7bd4"], "d": ["Статья TDV «Орхан»: в первый день сражения Орхан-гази отправил отряд в триста человек, чтобы привлечь византийскую армию на себя; на второй день, когда отряды под командованием Pazarlu спустились на равнину, бой разросся, и когда император был ранен стрелой, в византийской армии началась паника. Итог однозначен: «Орхан захватил весь Kocaeli; после победы у жителей Изника не осталось никакой надежды». Прибрежные города от Hereke до Ускюдара перешли под османскую власть, центром области был сделан Gebze. Это была последняя имперская византийская армия, пришедшая спасти Константинополь.", "73fe4332"]},
"OLAYLAR_EK5:1331-03-03:0":{"b": ["Основание первого османского медресе в Изнике", "c85fb625"], "d": ["Орхан-бей сразу после взятия Изника назначил сюда кади Чандарлы Кара Халила, превратил базилику в мечеть и, построив рядом имарет и медресе, начал благоустройство города. По статье TDV «Давуд-и Кайсери», строительство медресе было завершено в 1336 году, и Орхан-гази привёл на должность мударриса с жалованьем 30 акче в день Давуда-и Кайсери. Это медресе — первый институциональный шаг османской научной жизни; бейлик, помимо военной силы, получил и научную традицию. Превращение завоёванной византийской столицы в центр исламской учёности стало первым осязаемым признаком претензии османов на статус оседлого государства.", "4f11a077"]},
"OLAYLAR_EK5:1333-08-01:0":{"b": ["Обложение Византии данью — осада Измита и договор", "0c1ec8d3"], "d": ["Статья TDV «Орхан»: летом 733 (1333) года Орхан осадил Измит большой армией с метательными машинами, и император согласился на договор. В обмен на отказ от осады Византия обязалась выплачивать Орхану 12 000 золотых (гиперпиров) в год; «таким образом, в глазах османского эмира Византия оказалась данником». Взамен Орхан должен был стать другом императора и не нападать на города, подвластные Византии. Обложение пограничным бейликом Восточного Рима данью было заявлением о том, насколько изменился баланс сил.", "e2e3eeb4"]},
"OLAYLAR_EK5:1335-01-01:0":{"b": ["Самофракия перешла от венецианцев к генуэзской семье Гаттилузи", "c499ed5f"], "d": ["Генуэзская семья Гаттилузи вытеснила с острова венецианцев, державших его с 1204 года.", "97a996b3"]},
"OLAYLAR_EK5:1345-01-01:0":{"b": ["Присоединение бейлика Каресиды: Балыкесир, Бергама, Бига, Эдремит и Эрдек", "c7cb0511"], "d": ["Статья TDV «Орхан» (Иналджик) относит присоединение к 735 (1334–35) году: после смерти Демир-хан-бея газии Карасы и Хаджи Илбей пригласили на престол Дурсун-бея и попросили помощи у Орхана. Орхан сначала выступил на Балыкесир; когда Дурсун-бей, отправившийся на мирные переговоры, погиб от стрелы, пущенной из крепости Бергама, бейлик целиком вошёл в османские земли. В той же операции Kirmasti и Mihaliç покорились, Gölyazı был взят, а Ulubat, прежде оставленный по условиям пощады, был окончательно занят. Орхан назначил в санджак Каресиды Сулейман-пашу и сделал Бигу пограничным центром — так был получен мореходный кадровый состав для перехода в Румелию. Примечание: статья TDV «Каресиоглу» называет для того же события 746 (1345) год; энциклопедия противоречит сама себе. В тот же день присоединено также: Чанаккале.", "f5ed82c2"]},
"OLAYLAR_EK5:1346-06-15:0":{"b": ["Самос перешёл во владение хиосской Маоны", "01628b2f"], "d": ["После того как генуэзец Симоне Виньози взял Хиос и управление было передано компании Маона, Самос также перешёл во владение хиосских генуэзцев (Маона) (TDV: 1346–1475).", "3b122d12"]},
"OLAYLAR_EK5:1352-01-01:0":{"b": ["Первые капитуляции Орхан-гази с генуэзцами", "e64cb196"], "d": ["Орхан-гази, во время венециано-генуэзской войны договорившийся с генуэзцами, после сражения в проливе в феврале 1352 года отправил на защиту Перы 1000 лучников и обеспечил 60 000 золотых для перевозки войск; взамен он даровал генуэзцам первые капитуляции. Полный текст договора до нас не дошёл. Это первое официальное соглашение османов с европейской морской державой; оно было возобновлено тридцать пять лет спустя, в 1387 году.", "68c60677"]},
"OLAYLAR_EK5:1354-03-02:0":{"b": ["Взятие Галлиполи — прочный плацдарм в Румелии", "ba51a160"], "d": ["Османы в 1354 году взяли Галлиполи, окрестности которого они узнали в 1349–1352 годах как союзники Кантакузина; случай представился благодаря сильному землетрясению, разрушившему стены города. Узкий плацдарм в Çimpe таким образом превратился в настоящую базу на румелийской стороне пролива, и ворота во Фракию были приоткрыты настежь. Галлиполи будет утрачен в 1366 году из-за савойского крестового похода, но вторым завоеванием 1376 года окончательно перейдёт под османское владычество. В тот же день присоединено также: Kilitbahir.", "cac0192e"]},
"OLAYLAR_EK5:1357-09-01:0":{"b": ["Смерть Сулейман-паши, завоевателя Румелии", "2dc98228"], "d": ["Старший сын Орхан-бея и зодчий румелийских завоеваний Сулейман-паша умер осенью 1357 года (из дат, называемых в источниках — 758 (1357), 759 и 760 (1359) — наиболее принятая), упав с лошади на охоте. Смерть шехзаде, создавшего прочное османское присутствие в Румелии своими переходами 1352–1354 годов, оставила очередь наследования брату Мураду. Мавзолей Сулейман-паши, погребённого в Bolayır, остался древнейшим династическим памятником османов в Европе.", "1f780557"]},
"OLAYLAR_EK5:1361-01-01:0":{"b": ["Закон пенчик — закладка основы янычарского корпуса", "e5877c2d"], "d": ["После румелийских завоеваний по совету улема Караманлы Кара Рустема была введена система пенчик, предусматривавшая выделение государству пятой части военнопленных или их денежного эквивалента. Из выбранных среди этих пленных, воспитанных в турецких семьях и взятых в армию, сложилось ядро постоянной пехоты, непосредственно подчинённой падишаху, — янычарского корпуса. С этого устройства началось превращение пограничного бейлика, опиравшегося на племенную кавалерию, в государство с центральной армией.", "f28873dd"]},
"OLAYLAR_EK5:1363-01-01:0":{"b": ["Спуск в Западную Фракию: завоевание Комотини", "9ef69221"], "d": ["После взятия Эдирне пограничные силы, повернувшие на запад от Марицы, под командованием Гази Эвренос-бея взяли Комотини, центр Западной Фракии. Город стал передовым лагерем, откуда Эвренос-бей перенёс свои набеги в Македонию. Так часть Фракии, выходящая к берегу Эгейского моря, перешла под османский контроль, и дорога на Салоники открылась.", "0206d2bb"]},
"OLAYLAR_EK5:1369-01-01:0":{"b": ["Варна вошла в Добруджанское княжество и стала столицей", "2bfe73f9"], "d": ["В ходе распада Болгарского царства Варна на берегу Чёрного моря вошла в Добруджанское княжество, основанное Добротицей, и стала столицей этого небольшого государства.", "5115e7b2"]},
"OLAYLAR_EK5:1373-01-01:0":{"b": ["К западу от Пловдива: присоединение Пазарджика и Ихтимана", "1664d0e1"], "d": ["После взятия Пловдива в 1372 году Пазарджик в верховьях долины Марицы и Ихтиман, державший проход к Софии, были подчинены османскому управлению. Эта линия, находившаяся в руках местных беев, ставших вассалами после битвы при Чирмене, была переведена под прямое управление, и маршрут Пловдив — София стал непрерывным. Это продвижение — подготовка пути к завоеванию Софии, совершённому двенадцать лет спустя.", "0e9acfa0"]},
"OLAYLAR_EK5:1373-05-15:0":{"b": ["Восстание Савджи-бея — совместный мятеж шехзаде и византийского наследника", "75198c33"], "d": ["Савджи-бей, сын Мурада I, и Андроник Палеолог, сын византийского императора Иоанна V, в начале мая 1373 года одновременно в Бурсе и Константинополе восстали против своих отцов. Этот союз, объединивший наследников двух династий, был быстро подавлен; Савджи-бей был схвачен, ослеплён раскалённым железом и казнён. Дата, которую османское предание даёт для восстания, 787 (1385), ошибочна; событие приходится сразу вслед за годами, когда Византия стала вассалом османов, и показывает, насколько переплетены были два двора.", "9776426c"]},
"OLAYLAR_EK5:1374-01-01:0":{"b": ["Долины Струмы и Месты: присоединение Кюстендила, Петрича, Неврокопа и Драмы", "8c0980c4"], "d": ["Долины Струмы и Месты, находившиеся в руках сербских и болгарских местных беев, начавших платить дань османам после победы при Чирмене, были взяты под прямое османское управление продвижением пограничных беев. С присоединением Кюстендила, Петрича, Неврокопа и Драмы открылась восточная половина Македонии, а Салоники и Сере оказались в кольце осады. Расширение Румелии на юго-запад на карте — результат этой операции.", "a50a02ad"]},
"OLAYLAR_EK5:1381-03-28:0":{"b": ["Конец бейлика Эретна и основание государства Кади Бурханеддина", "60dcaf57"], "d": ["Эретниды, возникшие в 1335 году из ильханидского наместничества и сорок шесть лет правившие Центральной Анатолией с центрами в Сивасе и Кайсери, распались из-за придворных распрей. Устранив соперников Кылыч-Арслана и Хаджи Шадгельди, Кади Бурханеддин, ставший визирем в мае 1378 года, осенью 1381 года провозгласил себя султаном, положил конец бейлику и основал государство, носящее его имя. Так сменился владелец восточного соседа османов; линия Сивас-Кайсери оставалась затем семнадцать лет в руках Кади Бурханеддина.", "f5b2be0c"]},
"OLAYLAR_EK5:1381-04-01:0":{"b": ["Тимур взял Герат: конец династии Кертидов и переход Хорасана к Тимуридам", "15f6019e"], "d": ["Хорасан в 1380 году был раздроблен борьбой между сарбадарами, кертидами и музаффаридами. Отправив в регион своего сына Миран-шаха, Тимур затем сам двинулся на Герат и после некоторой осады принял сдачу города от кертидского мелика Гийас ад-дина Пир Али. Восстание, вспыхнувшее после его отъезда, было кроваво подавлено Миран-шахом, и правлению династии Кертидов, управлявшей Гератом с 1255 года, пришёл конец. Весь Хорасан от Мешхеда до Нишапура в эту дату вошёл под тимуридское управление.", "6ae06d43"]},
"OLAYLAR_EK5:1385-01-01:0":{"b": ["Продвижение вглубь Македонии: завоевание Битолы и Охрида", "63bb7838"], "d": ["Битола на Эгнатиевой дороге и Охрид на берегу озера перешли под османское управление во время набегов в сторону Албании. Оба были ключевыми пунктами дороги, ведущей к Адриатике; Охрид к тому же был древнейшим центром православной архиепископии на Балканах. TDV отмечает, что точных сведений о дате завоевания Охрида нет, и называются 787 (1385) год и 797 (1395) год, после смерти Марко Кралевича; здесь принят 1385 год. Битола в последующие века стала одним из важнейших военных центров Румелии.", "e5418654"]},
"OLAYLAR_EK5:1385-09-18:0":{"b": ["Битва при Савре — открытие ворот Албании", "dda6671b"], "d": ["По призыву албанского бея Карла Топии, оказавшегося в тяжёлом положении перед династией Балшичей, османские силы разбили на равнине Савра армию Балши II; Балша погиб на поле боя. Это сражение, в которое вступили по приглашению местного бея, дало османам первое прочное влияние на албанских землях, простирающихся до побережья Адриатики. Эта политика, обращавшая в выгоду раздоры между беями региона, на протяжении следующего столетия стала неизменным методом балканских завоеваний.", "05382964"]},
"OLAYLAR_EK5:1386-01-01:0":{"b": ["«Трёхлетний поход» Тимура: взятие Азербайджана и Северного Ирана", "2a98ec51"], "d": ["Хорошо рассмотрев раздробленное состояние Ирана во время хорасанских походов, Тимур в 788 (1386) году выступил на запад. В кампании 1386–1388 годов, называемой «трёхлетним походом», он через Мазендеран, Луристан и Грузию вышел в Азербайджан и достиг Карабаха; Тебриз, Ардебиль, Урмия и Нахичевань вошли под тимуридское управление. Захват Северного Ирана и Азербайджана стал началом и долгого противостояния с Золотой Ордой, подобно тому как некогда оно существовало между улусом Джучи и Ильханами.", "aaf3b558"]},
"OLAYLAR_EK5:1386-06-01:0":{"b": ["Битва при Frenkyazısı и осада Коньи — первый поход на Караман", "af4e5d77"], "d": ["Против Алаэддина Али-бея Караманоглу, который, будучи зятем Мурада I, был недоволен османским расширением в Западной Анатолии, Мурад I лично выступил в поход; в сражении, произошедшем в местности, называемой Frenk Yazısı, выученная и опытная османская армия разбила караманидские силы. Затем была осаждена крепость Конья, но поскольку Алаэддин-бей был прощён, бейлик не был полностью упразднён. Этот поход — открытие долгого сведения счётов между османами и Караманом, которое продлится век и закончится лишь окончательным присоединением в 1468 году.", "087a605a"]},
"OLAYLAR_EK5:1387-01-22:0":{"b": ["Муш перешёл от Кара-Коюнлу под управление Тимура (789/1387)", "ed2e7a11"], "d": ["Муш, перешедший после монгольского периода под управление Кара-Коюнлу, в 789 г. х. (1387) оказался под властью Тимура, владевшего землями Кара-Коюнлу. В атласе Муш в этом году записан как перешедший от Кара-Коюнлу к Тимуридам.", "9475520a"]},
"OLAYLAR_EK5:1390-06-01:0":{"b": ["Основание верфи в Галлиполи — рождение османского флота", "47546241"], "d": ["Первая организованная верфь Османского государства была основана в 1390 году Баязидом Молниеносным в Галлиполи на месте верфи, оставшейся от Византии. Приняв морское наследие западноанатолийских бейликов, османы впервые стали морской державой, строящей собственные корабли. Расположенная в ключевой точке пролива Дарданеллы, верфь служила главной базой османского флота полтора столетия — от осады Константинополя до эгейских походов.", "f214717c"]},
"OLAYLAR_EK5:1391-01-01:0":{"b": ["Hamîd-ili присоединён к Османской империи: Ыспарта, Бурдур, Улуборлу, Эгирдир", "e3da7de5"], "d": ["Йылдырым Баязид, выступивший в поход после нападения бея Караманогулларов Алааддина на Hamîd-ili и жалоб населения, овладел всеми оставшимися землями Хамидогуллары и передал управление ими сыну Исе Челеби.", "8a997ead"]},
"OLAYLAR_EK5:1393-01-01:0":{"b": ["Конец династии Музаффаридов: поражение шаха Мансура под Ширазом", "5fd14eb8"], "d": ["Шах Мансур, последний сильный правитель Музаффаридов, с 1318 года правивших в Йезде, Фарсе, Исфахане и Кермане, объединившись с родственниками, выступил против Тимура. В сражении близ Шираза, когда один из его эмиров перешёл на другую сторону, он потерял большую часть сил, был разбит и убит. После того как Тимур велел убить и всех членов династии, власть Музаффаридов закончилась, а Фарс и Керман вошли в состав тимуридских владений.", "8e89c2dc"]},
"OLAYLAR_EK5:1393-06-01:0":{"b": ["Присоединение Амасьи к османским землям", "fe2860cf"], "d": ["Во время похода Йылдырыма Баязида в Центральную Анатолию осаждённый эмир Амасьи сдал город османам, и Баязид в 1393 г. вступил в город. Султан оставил управление им сыну Мехмеду Челеби; став шехзадским санджаком, Амасья с тех пор превратилась в один из важнейших центров воспитания османской династии. Другие населённые пункты, утраченные в ту же дату: Ладик (Амасья), Мерзифон, Османджык, Чорум. Этот выбор станет решающим в будущую эпоху Фетрета: Челеби Мехмед вёл борьбу за воссоединение государства именно с этой амасийской базы.", "bc5eb00d"]},
"OLAYLAR_EK5:1393-08-29:0":{"b": ["Тимур захватил Багдад — Джалаириды бежали в Анатолию", "4d5602b3"], "d": ["Тимур после долгой осады взял Багдад; правитель города джалаирид султан Ахмад бежал на запад и укрылся сначала у мамлюков, затем при османском дворе. Таким образом, продвижение Тимура на запад впервые непосредственно соприкоснулось с сферой османского влияния. С этого начинается первое звено вражды между двумя государями.", "2fac674f"]},
"OLAYLAR_EK5:1393-09-01:0":{"b": ["Взятие Варны на берегу Чёрного моря", "a84b2abf"], "d": ["В ходе сокращения земель Болгарского царства между Дунаем и Чёрным морем крупнейший прибрежный порт Варна перешёл под османскую власть. Взятие порта открыло путь к продвижению в сторону Добруджи и дало Османам первую большую пристань на западном берегу Чёрного моря. Варне предстояло стать и ареной победы 1444 года, когда спустя пятьдесят один год было уничтожено войско крестоносцев.", "2e425501"]},
"OLAYLAR_EK5:1398-01-01:0":{"b": ["Область Невшехира и Ургюпа перешла от Караманидов к османам", "06ff59e8"], "d": ["В походах Баязида Молниеносного против Караманидов область Невшехира (Muşkara) и Ургюпа в 800/1398 году перешла под османское управление; в 1402 году после битвы при Анкаре Тимур вернул область Караманидам.", "5faa82e5"]},
"OLAYLAR_EK5:1398-07-15:0":{"b": ["Падение государства Кади Бурханеддина", "b13391e3"], "d": ["Кади Бурханеддин, попавший в плен к правителю Ак-Коюнлу Кара Юлюк Осман-бею, предложил освободить его в обмен на сдачу Сиваса, но жители города сопротивлялись, и султан был казнён перед стенами. Знать Сиваса возвела на престол его сына Алаэддина Али Челеби, но под давлением Ак-Коюнлу они попросили помощи у Баязида Молниеносного; османские силы под командованием Сулеймана Челеби разбили Кара Юлюка и овладели городом. Так государство Кади Бурханеддина исчезло, а Сивас, Токат, Niksar и Кайсери были присоединены к османским землям. В тот же день присоединено также: Kırşehir, Чорум.", "2a0c7f3a"]},
"OLAYLAR_EK5:1399-11-01:0":{"b": ["Размолвка Тимура: отказ выдать беглецов", "33790bc8"], "d": ["Под давлением Тимура джалаирид султан Ахмад и предводитель Кара-Коюнлу Кара Юсуф укрылись на османских землях; Тимур потребовал выдачи этих двух беглецов, Баязид Молниеносный отказал. После этого между двумя государями начался обмен письмами, полными взаимных тяжёлых оскорблений. Идеологическая почва войны была создана этой перепиской ещё до того, как двинулся хоть один солдат.", "ac66be59"]},
"OLAYLAR_EK5:1400-01-01:0":{"b": ["Больница Йылдырым в Бурсе — первая османская больница", "5f0dc59a"], "d": ["В годы, когда Баязид Молниеносный построил в Бурсе величественную Улу-джами, он подарил городу и дарюшшифу; это было звено, отведённое медицине, в широкой благотворительной программе из имарета, медресе, хана и моста. Это первое государственное больничное заведение, выполнявшее и функцию медицинской школы, готовившей лекарей, определило образец османских медицинских учреждений. Сооружение, завершённое всего за два года до Анкарской катастрофы, — одно из последних звеньев замысла Баязида превратить Бурсу в имперскую столицу.", "5765ebac"]},
"OLAYLAR_EK5:1400-08-01:0":{"b": ["Тимур сровнял Сивас с землёй", "f4d79de6"], "d": ["Тимур, двинувшийся на Сивас под проводничеством Кара Юлюк Осман-бея из Ак-Коюнлу и эрзинджанского эмира Мутахартена, осаждал город восемнадцать дней и, приняв его сдачу с обещанием не проливать ничьей крови, учинил большую резню; защитников засыпали землёй заживо во рвах. Важнейшие сооружения города, в первую очередь стены, были разрушены, Сивас демографически рухнул. Это первый крупный удар, нанесённый Тимуром по османским землям за два года до Анкарской битвы.", "8ddb3e3a"]},
"OLAYLAR_EK5:1401-02-01:0":{"b": ["Баязид Молниеносный вернул Эрзинджан и Kemah", "7047ca08"], "d": ["Воспользовавшись тем, что Тимур выступил в сирийский поход, Баязид Молниеносный отнял Эрзинджан и Kemah у подвластного Тимуру эрзинджанского эмира Мутахартена. Хотя он не вмешивался в разрушение Сиваса, этот шаг означал прямой вызов сфере влияния Тимура в Восточной Анатолии. Отношения между двумя государями с тех пор стали непоправимыми.", "2160d645"]},
"OLAYLAR_EK5:1402-03-13:0":{"b": ["Ультиматум Тимура из Тебриза — четыре условия", "3e1ac50e"], "d": ["Тимур через посла, отправленного из Тебриза, объявил четыре условия: возвращение Kemah Мутахартену, возвращение отнятых у анатолийских беев земель их владельцам, отправка в заложники одного османского шехзаде и признание колпака и пояса знаками подданства, а также выдача Кара Юсуфа. Баязид не принял ни одного из них; несмотря на настояния сановников и посредничество Мутахартена, переговоры сорвались. Тимур был намерен окончательно закрыть анатолийский вопрос до отправления в китайский поход.", "bd475bc3"]},
"OLAYLAR_EK5:1402-08-17:0":{"b": ["Бейлик Саруханиды восстановлен — Маниса вышла из-под власти османов", "ac747b05"], "d": ["Через три недели после Анкарского разгрома, при поддержке Тимура, Орхан-бей встал во главе бейлика, и земли Саруханидов вновь стали независимыми. Область с центром в Манисе исчезла с карты спустя двенадцать лет после османского присоединения 1390 года. Это одно из первых применений политики Тимура по возрождению бейликов, дата которого точно известна.", "9fe5744d"]},
"OLAYLAR_EK5:1402-08-20:0":{"b": ["Эмир Сулейман бежал в Румелию с государственной казной", "0a2b7363"], "d": ["Эмир Сулейман, взяв с собой государственную казну, архивы, семью и братьев из Бурсы, переправился на корабле из Гемлика в Güzelcehisar (Анадолухисары), оттуда добрался до Галлиполи и провозгласил свою власть в Эдирне. Перенос государственного архива и казны в Румелию — начало смещения османского центра тяжести на Балканы на целое поколение. На карте Румелия с этой даты рисуется собственным цветом Эмира Сулеймана.", "393aa053"]},
"OLAYLAR_EK5:1402-09-15:0":{"b": ["Тимур восстановил анатолийские бейлики — турецкое единство распалось", "15187774"], "d": ["После победы при Анкаре Тимур вернул находившимся при нём бекам их прежние земли. Караманоглу Мехмеду и Али-бекам были отданы область Караман, а также Кайсери, Киршехир, Сивриисар и Бейшехир; Гермияноглу Якуб-бею II — Кютахья и область Гермиян; Джандароглу Исфендияр-бею — помимо линии Кастамону — Синоп, ещё Чанкыры и Каледжик. Области Айдын, Ментеше и Теке тоже вернулись к своим прежним династиям. Анатолийское турецкое единство, созданное Йылдырымом Баязидом за десять лет, распалось за одно лето; на карте эти бейлики вновь появляются в своих собственных цветах. Другие населённые пункты, сменившие владельца в ходе того же процесса: Аксарай, Денизли, Эрегли (Конья), Эрменек, Илгын, Карапынар, Кайсери, Конья, Киршехир, Кютахья, Сивриисар, Сёке.", "0c3d6fbf"]},
"OLAYLAR_EK5:1402-12-14:0":{"b": ["Тимур отнял Измир у рыцарей Сен-Жана", "66dd1dd4"], "d": ["Спустившись на запад через Кютахью, Денизли, Айдын, Ayasuluk и Tire, Тимур осадил и взял прибрежный Измир, с 1344 года находившийся в руках христиан. Быстро овладев крепостью, которую Баязид Молниеносный годами не мог взять, и заняв окрестные крепости, Тимур оставил область Айдын прежним владельцам и вернулся на восток. После этого город перешёл под управление Айдынида Джунейд-бея.", "b6c372a5"]},
"OLAYLAR_EK5:1402-12-20:0":{"b": ["Иса Челеби овладел Бурсой — возник анатолийский удел", "955128c1"], "d": ["Иса Челеби, отошедший после Анкарского разгрома в сторону Каресиды, овладел Бурсой, пока Тимур находился в Измире. В бывшей столице, разграбленной и сожжённой воинами Тимура, он провозгласил свою власть и велел чеканить монету от своего имени; в январе 1403 года в Анатолии он был признан в качестве правителя «тюрков». На карте этот удел, тянущийся вдоль азиатского берега Мраморного моря, показан собственным цветом Исы Челеби.", "fdd5eed3"]},
"OLAYLAR_EK5:1403-03-15:0":{"b": ["Отход Тимура из Анатолии", "93a98839"], "d": ["Получив весть о смерти Баязида Молниеносного в Акшехире, Тимур счёл свои дела в Анатолии законченными и повернул на восток. Позади остались бейлики, заявившие о верности ему, и османские шехзаде, перессорившиеся друг с другом; некоторые города, как Сивас, были оставлены в руках подвластных Тимуру эмиров вроде Мезид-бея. Тимур в Анатолию больше не вернулся, но созданный им раздробленный порядок продержался десять лет.", "646cb1bc"]},
"OLAYLAR_EK5:1404-03-01:0":{"b": ["Эмир Сулейман перешёл в Анатолию: Бурса оказалась в его руках", "9b27aa5f"], "d": ["Эмир Сулейман, узнав о поражении Исы Челеби, вместе с Чандарлы Али-пашой перешёл с сильным войском в Анатолию и захватил Бурсу; записи марта 1404 г. показывают, что и Карадениз-Эреглы находилась под его управлением. Челеби Мехмед не смог противостоять Сулейману, в короткий срок подчинившему себе и Румелию, и бо́льшую часть Анатолии. Другие населённые пункты, перешедшие в ходе того же процесса от Челеби Мехмеда к эмиру Сулейману: Акъязы, Анадолу-Хисары, Апсу (Гипсу), Адранос (Орханели), Акхисар (Памукова), Армутлу, крепость Айдос, Айвалык, Балыкесир, Бехрамкале (Ассос), Бергама, Бейкоз, Бига. На карте с этой даты и до повторного взятия Бурсы Челеби Мехмедом (1410 г.) оба берега показаны одним цветом — в уделе эмира Сулеймана.", "0fc7e1b4"]},
"OLAYLAR_EK5:1405-01-01:0":{"b": ["Сражение на равнине Yenişehir — Челеби Мехмед отошёл в Амасью", "f1568288"], "d": ["Потеряв Бурсу и Анкару, Челеби Мехмед был разбит Эмиром Сулейманом на равнине Yenişehir, утратил все приобретения в Западной Анатолии и отошёл на базу Токат — Амасья. После этого поражения он избегал прямых столкновений и обратился к укреплению своей власти во внутренних областях Анатолии. Так началась самая долгая тихая фаза Междуцарствия.", "8c8a3c8c"]},
"OLAYLAR_EK5:1406-01-01:0":{"b": ["Эмир Сулейман отнял Анкару у Челеби Мехмеда", "d6a2acd6"], "d": ["В 1406 году Эмир Сулейман осадил Анкару, остававшуюся в руках Челеби Мехмеда после ухода Тимура из Анатолии. Комендант крепости Якуб-бей некоторое время держался, но по хитрости великого визиря Чандарлы Али-паши сдал крепость Сулейману. После этого Челеби Мехмед, договорившись с Караманидом Мехмед-беем, выступил против Сулеймана.", "f2a18bf9"]},
"OLAYLAR_EK5:1408-06-01:0":{"b": ["Челеби Мехмед отвоевал Сивас у тимурида Мезид-бея", "90079b0c"], "d": ["После нашествия Тимура управление Сивасом было оставлено подвластному Тимуру Мезид-бею. Челеби Мехмед в Амасье направил своего командира Баязид-пашу взять город, и после ожесточённого сопротивления Сивас во второй раз оказался в руках османской династии. Так удел Мехмеда через шесть лет после Анкарской битвы достиг на востоке прежней границы.", "22c266b9"]},
"OLAYLAR_EK5:1409-01-01:0":{"b": ["Конец династии Артукидов: сдача Мардина Кара-Коюнлу", "15b06f33"], "d": ["Артукиды, правившие в Мардине с 1106 года, самая долговечная ветвь династии, не удержались под давлением Ак-Коюнлу. Мелик Ахмад, поняв, что не сможет защитить город, договорился с правителем Кара-Коюнлу Кара Юсуфом и сдал ему Мардин. Так закончилось артукидское владычество, длившееся более трёх веков; Мардин и его округа, пока век спустя не перешли к османам, были ареной борьбы Кара-Коюнлу и Ак-Коюнлу.", "52e31654"]},
"OLAYLAR_EK5:1410-02-13:0":{"b": ["Битва при Ямболе — Муса Челеби вошёл в Эдирне", "8f978408"], "d": ["Муса Челеби, перешедший в Румелию через Валахию, при валашской и сербской поддержке разбил под Ямболом силы Эмира Сулеймана и вошёл в Эдирне. Румелия в эпоху Междуцарствия впервые вышла из рук Эмира Сулеймана. Однако его власть не была прочной; через четыре месяца, потерпев поражение при Kosmidion, он должен был отойти во внутренние районы Балкан.", "e80e7126"]},
"OLAYLAR_EK5:1412-10-01:0":{"b": ["Сражение при İnceğiz — первое румелийское поражение Челеби Мехмеда", "3c35cd43"], "d": ["Челеби Мехмед, переправившийся в Румелию на византийских кораблях, вступил в бой с Мусой Челеби при İnceğiz; Муса со своими семью тысячами янычар разбил Мехмеда, и тот вынужден был вернуться в Анатолию. Это поражение направило Мехмеда не к прямой войне, а к стратегии привлечения на свою сторону румелийских пограничных беев и сербского деспотата. Почва для победы при Çamurlu, одержанной девятью месяцами позже, была подготовлена этой дипломатией.", "dd443a98"]},
"OLAYLAR_EK5:1415-03-01:0":{"b": ["Осада Коньи и договор с Караманидами — возвращены Хамид-или, Саид-или, Beyşehir, Seydişehir и Akşehir", "0996257e"], "d": ["Против Караманидов, нападавших на османские земли в эпоху Междуцарствия и осаждавших и сжёгших Бурсу, Челеби Мехмед организовал большой поход и в мухарреме 818 года осадил Конью. Караманид Мехмед-бей II вынужден был просить мира; по договору Хамид-или (область Испарты) и Саид-или вновь присоединились к османским землям, Beyşehir, Seydişehir и Akşehir были возвращены; Sivrihisar, отданный Тимуром Караманидам в 1402 году, также вернулся к османам. Этот поход, в котором началось «зашивание» анатолийского единства, распавшегося после Анкарской битвы, — один из конкретных доводов в пользу того, чтобы считать Челеби Мехмеда «вторым основателем».", "952c9f73"]},
"OLAYLAR_EK5:1415-06-01:0":{"b": ["Взятие Измира у Айдынида Джунейд-бея", "2377ca51"], "d": ["Измир, центр Айдынида Джунейд-бея, постоянно менявшего стороны среди шехзаде в Междуцарствие, после десятидневной осады был взят Челеби Мехмедом; Джунейд был прощён и отправлен санджак-беем в Никополь. Город, возвращённый Тимуром Айдынидам в 1402 году, таким образом через тринадцать лет вернулся к османам. Джунейд вновь захватит город в 1422 году, и вопрос будет закрыт лишь Мурадом II в 1424–1426 годах.", "41fefe61"]},
"OLAYLAR_EK5:1416-01-01:0":{"b": ["Казнь Торлака Кемаля — Саруханиды окончательно османские", "8a09dbf1"], "d": ["Торлак Кемаль, возглавлявший западноанатолийское крыло движения шейха Бедреддина, был разбит в окрестностях Манисы и казнён. С этой даты область Саруханидов окончательно перешла под османский контроль, и бейлик, воскрешённый Тимуром в 1402 году, исчез из истории. Так были вычищены последние политические остатки Междуцарствия в Западной Анатолии.", "43bec619"]},
"OLAYLAR_EK5:1417-01-01:0":{"b": ["Завоевание Влёры, Берата и Канины", "1e1949b8"], "d": ["Османы в 1417 году взяли под своё владычество Влёру на адриатическом побережье вместе с городом Берат и крепостью Канина во внутренней части страны. Через год попытка Венеции вернуть город не удалась, и здесь, с организацией санджака, османская власть стала постоянной. Взятие Влёры впервые сделало османов прямыми владельцами порта на Адриатике и дало им заморский плацдарм перед лицом Италии.", "508b9927"]},
"OLAYLAR_EK5:1419-01-01:0":{"b": ["Возвращение Центральной Анатолии: Кайсери и Kırşehir", "204eacb3"], "d": ["Города Центральной Анатолии, попавшие в руки Караманидов в эпоху Междуцарствия, вернулись под османское управление во время походов Челеби Мехмеда по восстановлению государства. С присоединением Кайсери и Kırşehir бассейн Кызылырмака, потерянный в Анкарской битве, был в значительной степени возвращён. Это продвижение — продолжение политики обращения на восток, начатой осадой Коньи четырьмя годами ранее.", "c663fc08"]},
"OLAYLAR_EK5:1419-01-28:0":{"b": ["Мамлюки передали Кайсери Дулкадиру Насирэддину Мухаммеду", "aad4b00c"], "d": ["Мамлюкское войско, выступившее в поход против Караманоглу Мехмед-бея, заняло Кайсери; мамлюкский командующий оставил город и его округу Dulkadırlı Насирэддину Мухаммеду и вернулся в свою страну.", "8cd84dc4"]},
"OLAYLAR_EK5:1421-06-25:0":{"b": ["Смерть Мехмеда I и восшествие на престол Мурада II", "98acac77"], "d": ["Мехмед I, закончивший эпоху Междуцарствия и вновь собравший османскую землю в одних руках, умер 25 июня 1421 года в Эдирне, и его сын Мурад взошёл на престол в Бурсе. По договорённости с Византией, достигнутой до его смерти, младшие сыновья должны были быть отправлены заложниками к императору, а император не должен был освобождать удерживаемого им претендента на престол Мустафу Челеби; Мурад II отказался отправить братьев императору.", "c8093fa8"]},
"OLAYLAR_EK5:1423-01-01:0":{"b": ["Окончательная ликвидация Текеогуллары: взятие Анталии", "e65565b2"], "d": ["Бейлик Текеогуллары, воссозданный после Анкарской битвы с воскрешения Тимура, закончился осадой Анталии османскими силами под командованием Хамза-бея; был устранён последний значительный человек бейлика, Осман Челеби. Так область Теке на средиземноморском побережье после двадцатиоднолетнего отделения окончательно присоединилась к османам. Бейлик правил в Анталии с 1321 года как ветвь, отделившаяся от Хамидидов.", "6b81398d"]},
"OLAYLAR_EK5:1423-05-01:0":{"b": ["Поход Турахан-бея в Морею и разрушение стены Гексамилион", "c6c2706d"], "d": ["Когда Византия поддержала соперничавшего претендента на престол Мустафу Челеби, Мурад II направил Турахан-бея на Морею. Турахан-бей разрушил стену Гексамилион, наглухо перекрывавшую Коринфский перешеек, вошёл на полуостров и учинил большие разрушения. Мир был достигнут на условиях, что стена больше не будет строиться и будет выплачиваться ежегодный налог; Морейский деспотат, таким образом, был оставлен в военном отношении беззащитным, и почва для окончательного завоевания 1460 года была подготовлена за тридцать семь лет.", "3482eb23"]},
"OLAYLAR_EK5:1424-01-01:0":{"b": ["Афонские монастыри перешли под османское покровительство", "562de5ea"], "d": ["В годы осады Салоник монастырская республика Афон на восточном пальце Халкидики обратилась к Мураду II с просьбой о покровительстве и признала османское владычество. Права монахов на собственность и богослужение были гарантированы; монастыри были оставлены свободными во внутренних делах в обмен на налог. Этот порядок стал самым долговечным примером отношений покровительства, установленных османами с православными институтами, и продлился пять веков.", "6be1a9f2"]},
"OLAYLAR_EK5:1427-01-01:0":{"b": ["Присоединение бейлика Таджеддиногуллары: Niksar", "370ffd47"], "d": ["Под давлением амасийского бейлербея Йоргюч-паши Таджеддиногуллары Хюсамеддин Хасан-бей в 830 (1427) году сдал ключи своей страны с центром в Niksar; ему был дан санджак в Румелии. Так закончился бейлик, основанный во второй половине XIV века, границы которого временами доходили до Kelkit, Амасьи, Самсуна, Орду и Гиресуна. В тот же год земли Hacıemiroğulları также были внесены в кадастр и присоединены к санджаку Джаник; эпоха бейликов Среднего Причерноморья закрылась.", "06fa8222"]},
"OLAYLAR_EK5:1427-01-01:1":{"b": ["Уступка Белграда Венгрии — Татский договор", "62481183"], "d": ["После смерти сербского деспота Стефана Лазаревича по Татскому договору, заключённому между венгерским королём Сигизмундом и наследником Георгием Бранковичем, крепость Белград была передана Венгрии. Крепость, стоящая в месте слияния Дуная и Савы, до тех пор находилась в руках сербского деспотата и для османов была замком ворот, открывающихся в Центральную Европу. Эта передача на сто лет сделала Белград самой жёсткой преградой на пути османского продвижения: осады 1440 и 1456 годов оказались неудачными, крепость пала лишь в 1521 году.", "ee1ad2d8"]},
"OLAYLAR_EK5:1432-01-01:0":{"b": ["Мардин перешёл от гарнизона Кара-Коюнлу к Кара Юлюк Осман-бею из Ак-Коюнлу", "d82bc97f"], "d": ["Мардин, взятый Кара Юсуфом в 1409 году, управлялся наместниками Кара-Коюнлу; оставленный в гарнизоне эмир Насир в 835 (1432) году сдал город Кара Юлюк Осман-бею из Ак-Коюнлу. Управление Ак-Коюнлу продолжалось до начала XVI века.", "407382cb"]},
"OLAYLAR_EK5:1435-01-01:0":{"b": ["Караманиды отняли Кайсери у Dulkadırlı", "2b09e8e8"], "d": ["Одержав победу над Dulkadırlı, караманский бей присоединил к своим владениям Кайсери, Ургюп, Develi Karahisârı и Uçhisar.", "39a543cc"]},
"OLAYLAR_EK5:1446-05-05:0":{"b": ["Buçuktepe Vak'ası — первое янычарское восстание и возвращение Мурада II на престол", "6388dda1"], "d": ["Buçuktepe Vak'ası, первое известное истории янычарское восстание, вспыхнувшее в Эдирне, началось с требования увеличить жалованье на полакче и закончилось низложением юного Мехмеда II. Мурад II 8 сафара 850 года поспешно выехал из Манисы и начал своё второе правление. Это событие стало первым признаком того, что корпус капыкулу превратился в силу, имеющую слово по вопросам престола, и сформировало осторожность Завоевателя по отношению к янычарам на всю жизнь.", "c03ef4f8"]},
"OLAYLAR_EK5:1449-01-01:0":{"b": ["Присоединение побережья Эпира: Арта и Превеза", "796f7ecf"], "d": ["Спустя девятнадцать лет после сдачи Янины в 1430 году Арта и Превеза в прибрежной части Эпирского деспотата также перешли под османское управление. Так был взят под контроль Амбракийский залив, выходящий к Ионическому морю, и морская связь Янины была завершена. Превеза — ключевой пункт залива, который спустя девяносто лет даст имя вошедшей в историю победе Хайреддина Барбароссы.", "b5e95ae5"]},
"OLAYLAR_EK5:1451-02-18:0":{"b": ["Смерть Мурада II и второе воцарение Мехмеда II", "8f8256ad"], "d": ["Заболевший после свадьбы сына Мурад II умер в Эдирне 1 мухаррама 855 года (3 февраля 1451). Девятнадцатилетний Мехмед II 16 мухаррама 855 года (18 февраля 1451) во второй раз взошёл на османский престол — на этот раз навсегда. Возвращение молодого государя, низложенного пять лет назад при Buçuktepe, — начало правления, которое через два года будет увенчано завоеванием Константинополя и превратит Османский бейлик в мировую империю.", "5363b0f7"]},
"OLAYLAR_EK5:1454-07-14:0":{"b": ["Первая османско-крымская совместная осада Кафы", "e346d163"], "d": ["Крымский хан Хаджи Гирей, в июне 1454 года договорившийся с Мехмедом II Завоевателем, осадил Кафу с суши с 7000 всадниками; османский флот из пятидесяти–шестидесяти галер также встал на позиции в открытом море. Генуэзская Кафа добилась снятия осады, заплатив дань, и окончательное завоевание было отложено на двадцать один год, до 1475 года. Эта первая совместная операция была первым примером османско-крымского военного сотрудничества, которое повторится при окончательном завоевании Кафы.", "bf590b3e"]},
"OLAYLAR_EK5:1455-01-01:0":{"b": ["Взятие островов северной части Эгейского моря: Тенедос, Имброс и Тасос", "76575895"], "d": ["Сразу после завоевания Константинополя Мехмед II Завоеватель, чтобы обеспечить морской путь новой столицы, обратился к островам у эгейского устья Дарданелл; Тенедос и Имброс были взяты у Византии, а Тасос — у семьи Гаттилузио генуэзского происхождения. Эти острова, запиравшие обе стороны пролива, стали первым звеном линии снабжения и обороны Стамбула. Вмешательство флотов папства и Венеции заставило власть некоторое время колебаться, и лишь в 1459 году она стала окончательной.", "9a34e8f0"]},
"OLAYLAR_EK5:1455-06-01:0":{"b": ["Завоевание Косова: взятие Приштины и Нови-Пазара", "d7ed2345"], "d": ["Османская армия, двинувшаяся на Сербский деспотат, взяла Приштину на Косовом поле и Нови-Пазар, центр области Рашка; в той же операции было взято и Ново-Брдо, известное серебряными рудниками. Так южная половина Сербии была непосредственно подчинена османскому управлению, и деспотат в Смедерево был отрезан от своих центральных земель. Это завоевание стало решающим шагом на пути к полной аннексии Сербии четыре года спустя.", "b2c7fcce"]},
"OLAYLAR_EK5:1456-01-01:0":{"b": ["Печ перешёл под османское управление — один из центров санджака Дукагин", "19511588"], "d": ["Вскоре после сербского похода Мехмеда II Завоевателя в 1455 году Печ, центр сербского патриархата, перешёл под османское управление; в османских источниках записи об этом переходе нет. Городок со временем превратился в небольшой мусульманский город и стал одной из резиденций санджак-бея в санджаке Дукагин.", "4d7160f6"]},
"OLAYLAR_EK5:1456-01-24:0":{"b": ["Завоевание Эноса и Самотраки — завершение побережья Западной Фракии", "106e723b"], "d": ["Энос в устье реки Марицы был взят у семьи Гаттилузио генуэзского происхождения, державшей его восемьдесят лет; подчинённый ему остров Самотраки также был захвачен в той же операции. С падением Эноса прибрежная полоса Западной Фракии от Салоник до Галлиполи стала непрерывной османской землёй. В руках семьи Гаттилузио остался только Лесбос; и тот будет взят спустя шесть лет.", "327297a0"]},
"OLAYLAR_EK5:1456-07-22:0":{"b": ["Неудача осады Белграда", "3d53a604"], "d": ["Мехмед II Завоеватель после завоевания Константинополя осадил Белград, считавшийся ключом к Центральной Европе; однако подкрепление, приведённое Яношем Хуньяди по Дунаю, и добровольцы, собранные проповедником крестового похода Капистрано, не дали крепости пасть. Падишах, несмотря на проявленный перед осадой личный героизм, был ранен и вынужден отойти. Эта неудача на шестьдесят пять лет закроет венгерскую границу для османского продвижения; Белград удалось взять лишь в 1521 году Сулейману Кануни.", "036836cb"]},
"OLAYLAR_EK5:1458-05-01:0":{"b": ["Завоевание северной Мореи: Патры", "c08a8509"], "d": ["Силы Мехмеда II Завоевателя, обратившиеся к Морейскому деспотату в те же годы, что и присоединение Сербии, взяли Patras (Balyabadra) на северо-западе полуострова. Этот порт, держащий вход в Коринфский залив, — замок сухопутного входа в Морею; его взятие подготовило почву для окончательного завоевания, совершённого двумя годами позже. Город был последней большой пристанью, через которую византийские деспоты поддерживали связь с латинским миром.", "4490cc14"]},
"OLAYLAR_EK5:1459-06-20:0":{"b": ["Взятие побережья западного Причерноморья: Амасра", "f43608fc"], "d": ["Укреплённая колония генуэзцев Амасра на западном Причерноморье сдалась без сопротивления под совместным давлением флота и сухопутных сил Мехмеда II Завоевателя. Этот порт на побережье Бартын — Зонгулдак стоял латинским анклавом между Джандаридами и османскими землями; с его взятием побережье стало единым. Падение Амасры — первый шаг большого причерноморского похода на Синоп и Трабзон два года спустя (1461).", "b8b9f4f0"]},
"OLAYLAR_EK5:1462-09-17:0":{"b": ["Завоевание острова Лесбос", "fe17aeba"], "d": ["Османская армия под командованием Мехмеда II Завоевателя в зу-ль-хиджа 866 года после короткой, но жестокой осады отняла Лесбос у семьи Гаттилузио генуэзского происхождения и присоединила его. Падение крупнейшего острова северной части Эгейского моря ликвидировало и последнюю значительную базу генуэзцев в регионе. Благодаря близости к анатолийскому берегу остров отныне служил передовым постом османского флота и вошёл в историю мореплавания как место, где выросли братья Барбаросса.", "453088e2"]},
"OLAYLAR_EK5:1463-07-28:0":{"b": ["Начало шестнадцатилетней османо-венецианской войны", "563ddb68"], "d": ["Венецианцы, чтобы остановить османское продвижение в Морее и Эгейском море, заключили союз с правителями Карамана и Ак-Коюнлу и в 1463 году начали войну. Эта стратегия окружения — Узун Хасан на востоке, Венеция на западе и Караман между ними — вынудила Завоевателя воевать одновременно на нескольких фронтах. Шестнадцатилетняя борьба охватит все крупные операции эпохи, от Отлукбели до албанских походов, и закончится лишь Константинопольским миром 1479 года.", "e70079e9"]},
"OLAYLAR_EK5:1466-01-01:0":{"b": ["Завоевание большей части Герцеговины: Требинье и Мостар", "f54c0100"], "d": ["Земли Стефана Вукчича Косачи, герцога Герцеговины, создавшего управление отдельно от Боснии, спустя три года после падения Боснийского королевства в значительной степени перешли под османское управление: на юге Требинье в 1466 году было взято «вместе почти со всей областью Герцеговины». Мостар, образовавшийся вокруг двух малых крепостей у моста через Неретву, должен был быть взят незадолго до завоевания Благая, центра Герцеговины, в 1466–1468 годах; в боснийском суммарном кадастре 1468–1469 годов он записан под именем «Köprülü Hisar». Завоевание Герцеговины с остальными крепостями герцогства было завершено в 1483 году.", "a7f22be7"]},
"OLAYLAR_EK5:1466-06-01:0":{"b": ["Второй албанский поход — личное выступление Завоевателя против Скандербега", "9cdd2bfa"], "d": ["Чтобы сломить сопротивление Скандербега, длившееся более четверти века, Мехмед II Завоеватель в 1466–1467 годах организовал большие походы под своим личным командованием. Османская армия осадила Круя и построила крепость Эльбасан, чтобы взять регион под контроль. Поход сломил хребет албанского сопротивления, но не смог добиться падения крепости; полное подчинение региона заняло около десяти лет после смерти Скандербега.", "00e75aca"]},
"OLAYLAR_EK5:1467-10-01:0":{"b": ["Передовые отряды Ак-Коюнлу взяли у Кара-Коюнлу крепость Bingöl", "51b94cbc"], "d": ["В последние недели похода Джахан-шаха против Узун-Хасана передовые отряды Ак-Коюнлу захватили крепость Bingöl; после убийства Джахан-шаха 10 ноября 1467 г. господство Кара-Коюнлу в регионе закончилось.", "c150063d"]},
"OLAYLAR_EK5:1467-11-10:0":{"b": ["Крах государства Кара-Коюнлу: убийство Джахан-шаха", "30bc6358"], "d": ["Правитель Кара-Коюнлу Джахан-шах, подвергшийся нападению при возвращении из похода на Узун Хасана из-за наступления зимы, был убит при бегстве между Бингёлем и Kiğı. После этого удара государство не оправилось; последний правитель Хасан Али в 1469 году был взят в плен и убит Угурлу Мехмедом, сыном Узун Хасана. Господство Кара-Коюнлу, почти век правившее в Восточной Анатолии, Азербайджане и Ираке, таким образом перешло к Ак-Коюнлу.", "5a5288e7"]},
"OLAYLAR_EK5:1468-01-17:0":{"b": ["Смерть Скандербега — угасание албанского сопротивления", "9158c35f"], "d": ["Скандербег, воспитанный при османском дворе, восставший в 1444 году после разгрома при İzlâdi и более четверти века сопротивлявшийся в Албании, умер в Леже, где нашёл убежище. Это сопротивление, неоднократно изматывавшее османские армии при Мураде II и Завоевателе, со смертью вождя лишилось центрального руководства. С крушением албанского фронта, подпитывавшегося папством и Венецией, османы в течение десяти лет взяли Круя и Шкодер и окончательно присоединили регион.", "5c7cffad"]},
"OLAYLAR_EK5:1474-01-01:0":{"b": ["Установлено османское управление в Кайсери: Гедик Ахмед-паша покончил с Караманидами", "33cf35fc"], "d": ["Когда Гедик Ахмед-паша в 1474 году покончил с Караманидами, Кайсери перешёл под османское управление; город на протяжении XV века переходил из рук в руки между Дулкадириды, Рамазаниды и Караманиды. При османском управлении Кайсери стал центром санджака бейлербейлика Караман.", "5d1db169"]},
"OLAYLAR_EK5:1475-01-01:0":{"b": ["Самос оставлен: генуэзское (Маона) владение закончилось", "5bdc380c"], "d": ["По TDV, остров после 1475 года был оставлен; в 1479 году Мехмед Завоеватель завоевал остров и построил крепость.", "4e48c423"]},
"OLAYLAR_EK5:1475-01-10:0":{"b": ["Разгром при Высоком Мосту (Ракова, Васлуй) в Молдавии", "a1a74bf7"], "d": ["Молдавский воевода Стефан Великий заманил османские силы под командованием румелийского бейлербея Хадым Сулейман-паши на болотистую местность и нанёс им тяжёлое поражение. Этот разгром, один из самых тяжёлых сухопутных поражений эпохи Завоевателя, вызвал в Европе большой резонанс и принёс Стефану славу в мире крестоносцев. Падишах на следующий год лично выступил в поход ради возмездия.", "3247c9fe"]},
"OLAYLAR_EK5:1476-07-26:0":{"b": ["Победа при Валя-Албэ (Akdere) — молдавский поход", "45a66791"], "d": ["Мехмед II Завоеватель, лично выступивший в поход, чтобы отомстить за разгром при Ракове годом ранее, нанёс османской армией большое поражение молдавским войскам в местности Akdere и вошёл в Сучаву, центр бейлика. Однако крепости взять не удалось; из-за нехватки провианта, вспыхнувшей среди янычар чумы и венгерских приготовлений армия вынуждена была отступить. Окончательное подчинение Молдавии удалось обеспечить лишь в последующие годы и взятием Килии и Аккермана в 1484 году.", "27b9dd1c"]},
"OLAYLAR_EK5:1478-06-15:0":{"b": ["Завоевание Круя и завершение завоевания Албании", "559a79b4"], "d": ["Через десять лет после смерти Скандербега, в 1478 году, с взятием Круя, Drivasto, Лежи и Jabyak завоевание Албании было в значительной степени завершено. Падение крепости Круя, годами сопротивлявшейся османским армиям и ставшей символом сопротивления Скандербега, означало конец венецианско-албанского союза в регионе. Оставшийся Шкодер должен был быть оставлен османам Константинопольским миром, подписанным на следующий год.", "4f6059e8"]},
"OLAYLAR_EK5:1479-01-01:0":{"b": ["Присоединение Таманского полуострова", "4ef917b8"], "d": ["После взятия Кафы и Керчи в 1475 году флот, отправленный Мехмедом II Завоевателем к кавказскому побережью, вместе с Анапой и Kopa захватил генуэзскую Матрегу (Tamatarhan) на Таманском полуострове. Таким образом обе стороны пролива оказались под контролем, и вход в Азовское море стал полностью управляемым. Тамань как ворота на Северный Кавказ была присоединена к санджаку Кафа.", "74a0de9f"]},
"OLAYLAR_EK5:1479-01-01:1":{"b": ["Переход Самоса под османское управление (Завоеватель)", "c877bc14"], "d": ["Мехмед Завоеватель завоевал Самос, построил крепость и заново организовал перепись; крепость была разрушена Баязидом II в 1483 году по политическим причинам.", "2965b1d9"]},
"OLAYLAR_EK5:1480-07-28:0":{"b": ["Неудача осады Родоса", "35a85c28"], "d": ["По приказу Мехмеда II Завоевателя флот из 160 судов под командованием Месих-паши весной 885 (1480) года осадил Родос, и остров три месяца находился в блокаде. Рыцари-иоанниты во главе с великим магистром Пьером д'Обюссоном, несмотря на тяжёлые потери, отчаянно сопротивлялись; когда последний большой штурм 20 джумада аль-ула 885 года был также отбит, флот 3 августа отошёл. После этой неудачи стены города были полностью обновлены, и он превратился в сильнейшую крепость Европы; остров удалось взять лишь в 1522 году Сулейману Кануни.", "23334bd0"]},
"OLAYLAR_EK5:1481-01-01:0":{"b": ["Икария перешла под управление родосских рыцарей-иоаннитов", "5cbc2669"], "d": ["Икария между Самосом и Хиосом с 1481 по 1521 год находилась под управлением родосских рыцарей-иоаннитов.", "9d387479"]},
"OLAYLAR_EK5:1481-06-22:0":{"b": ["Сражение при Yenişehir — поражение Джем-султана", "c35abee2"], "d": ["Два брата, выступившие за престол после смерти Завоевателя, сошлись на равнине Yenişehir, и Джем-султан потерпел окончательное поражение. Шехзаде, правивший в Бурсе восемнадцать дней и велевший читать хутбу от своего имени, после поражения вынужден был укрыться сначала в Конье, а оттуда — на мамлюкских землях. Yenişehir положил начало самому затяжному династическому кризису османской истории: вопрос Джема на четырнадцать лет парализовал внешнюю политику Османской империи перед лицом Европы.", "9d30204e"]},
"OLAYLAR_EK5:1482-01-01:0":{"b": ["Присоединение Герцеговины", "bf247891"], "d": ["Земли Герцеговинского герцогства, оставшегося после завоевания Боснии в 1463 году, поэтапно перешли под османское управление: Требинье и Мостар были взяты в 1466 году, санджак Герцеговина образован в 1470 году, а последние земли герцогства на адриатическом побережье вместе с Герцег-Нови (Herseknovi) были завоёваны в начале 1482 года и присоединены к санджаку. Так горная область за Адриатикой целиком стала османской, а Босния и Герцеговина превратились в единую административную географическую единицу. Сын последнего герцога, вошедший в османский двор, — Херсекзаде Ахмед-паша, который позднее поднимется до великого визиря.", "0522e47f"]},
"OLAYLAR_EK5:1482-01-01:1":{"b": ["Оставление Закинфа Венеции за ежегодную дань", "268a691a"], "d": ["В конце эпохи Завоевателя Закинф, один из Ионических островов, отнятых у семьи Токко, в поисках спокойствия на Западе новым падишахом, занятым делом султана Джема, был оставлен Венеции. Остров был передан под венецианское управление, признававшее суверенитет османского владыки и платившее ежегодную дань в пятьсот дукатов. Так на Ионическом море прямое османское управление осталось лишь на Айя-Мавре.", "0773761c"]},
"OLAYLAR_EK5:1482-07-29:0":{"b": ["Бегство Джем-султана на Родос", "2228d6da"], "d": ["Джем-султан, потерпевший неудачу и в попытке осадить Конью, бежал из Анатолии с тридцатью людьми и добрался до Родоса, где был торжественно встречен рыцарями-иоаннитами. Однако гостеприимство вскоре превратилось в плен; шехзаде был передан сначала Франции, затем папству и стал козырем в руках европейской политики. Баязид II вынужден был ежегодно платить за удержание брата, а военные шаги османов против Запада были приостановлены до смерти Джема.", "05ca0dd6"]},
"OLAYLAR_EK5:1485-01-01:0":{"b": ["Начало османо-мамлюкской войны (фронт Чукурова)", "3fe3f0c7"], "d": ["Борьба за влияние над Дулкадириды и вражда, оставленная бегством Джем-султана на мамлюкские земли, в 1485 году начали между двумя суннитскими великими державами войну, которая продлится шесть лет. В боях, происходивших в Чукурове вокруг Аданы и Тарса, стороны не смогли добиться превосходства друг над другом; османские армии получили несколько тяжёлых ударов. Эта война — первая фаза разрыва османо-мамлюкских отношений и начало процесса, который через тридцать лет завершится походами Явуза на Мардж-Дабик и Ридания.", "08141630"]},
"OLAYLAR_EK5:1491-05-01:0":{"b": ["Османо-мамлюкский мир — посредничество Туниса", "60dd6719"], "d": ["В османо-мамлюкской войне, начавшейся в 1485 году, стороны не добились решающей победы; при посредничестве правителя Туниса Османа Хафсида в 1491 году было достигнуто соглашение. Договор в значительной степени вернул границы к довоенным и отсрочил сведение счётов между двумя исламскими государствами на целое поколение. Шестилетняя изнурительная борьба — одна из главных причин осторожной внешней политики Баязида II и его упора на внутренние устройства вместо обращения на восток.", "406d3b78"]},
"OLAYLAR_EK5:1492-08-01:0":{"b": ["Принятие Османской империей сефардских евреев, изгнанных из Испании", "5c2b5c24"], "d": ["После падения Гранады часть евреев, бежавших в Испании от гнёта инквизиции, нашла убежище на османских землях и была расселена по разным городам. Под османским управлением эти сефардские общины получили невиданную до того свободу: селиться где пожелают, исповедовать свою веру, открывать учебные заведения и строить новые синагоги. Эта миграция, преобразившая экономическую жизнь Салоник и Стамбула благодаря привезённым с собой знаниям в книгопечатании, медицине и финансах, стала самым обсуждаемым в Европе примером османского порядка терпимости.", "b5b4a53b"]},
"OLAYLAR_EK5:1495-02-25:0":{"b": ["Смерть Джем-султана — конец четырнадцатилетнего заложничества", "f6588b70"], "d": ["Джем-султан, переданный папством французскому королю Карлу VIII, умер в местности, называемой Castel Capuana, после того как 27 января 1495 года выехал из Рима; источники отмечают, что он мог быть отравлен в папских кругах. Смерть шехзаде, четырнадцать лет находившегося в руках европейских государств как карта угрозы против османов, наконец развязала руки Баязиду II. Действительно, после этого падишах объявит войну Венеции и приведёт свой флот к первой большой победе.", "8f2579d5"]},
"OLAYLAR_EK5:1499-08-28:0":{"b": ["Морская победа при Сапиенце (Зонкьо) — первый большой успех флота в Средиземном море", "9754aaef"], "d": ["Баязид II, получивший свободу действий с окончанием вопроса Джема, в 1499 году объявил войну Венеции; османский флот разбил венецианский флот у Сапиенцы (Зонкьо) и одержал первую большую морскую победу в Средиземном море. Этой победой флот заявил, что теперь способен противостоять Венеции на море.", "5fa6989c"]},
"OLAYLAR_EK5:1500-12-24:0":{"b": ["Потеря Кефалинии и Итаки", "60f0f687"], "d": ["Венеция, потрясённая взятием Модона и Корона, объединилась с Испанией, перешла в контрнаступление и осадила Кефалинию, находившуюся в османских руках с 1479 года. После сорокасемидневного сопротивления крепость пала, остров вместе с Итакой перешёл к Венеции и в течение трёхсот лет не возвращался под османское управление. Эта потеря создала равновесие, при котором выигранное в Морее было отдано на Ионическом море.", "a61731e0"]},
"OLAYLAR_EK5:1502-03-01:0":{"b": ["Падение Золотой Орды и возвышение Крыма", "0d1dc515"], "d": ["Последний правитель Шейх-Ахмед-хан (1481–1502) не смог вывести свою страну из кризиса, и Золотая Орда в 1502 году исчезла с исторической сцены в результате удара крымского хана Менгли Гирея. В результате борьбы за престол и раздробления на землях бывшей Золотой Орды возникли Крымское, Казанское, Ногайское, Астраханское и Сибирское ханства. Эта победа Крыма, находившегося под османским покровительством, сделала османское влияние к северу от Чёрного моря бесспорным, а образовавшуюся в регионе пустоту в последующем столетии заполнит Москва.", "9314f239"]},
"OLAYLAR_EK5:1502-12-14:0":{"b": ["Окончание османо-венецианской войны и мир", "125b1526"], "d": ["Война, начавшаяся в 1499 году и потрясшая Венецию потерей Сапиенцы, Лепанто, Модона и Корона, в 1502 году закончилась миром. Венеция, потеряв важнейшие базы в Морее, вынуждена была признать османское превосходство в обмен на сохранение торговых привилегий в Восточном Средиземноморье. Правление Баязида II, считающееся осторожным, этой войной впервые подняло османов до положения серьёзной морской державы в Средиземноморье.", "3d102f53"]},
"OLAYLAR_EK5:1511-07-02:0":{"b": ["Восстание Шахкулу — кызылбашское восстание от области Теке до Сиваса", "3beadca7"], "d": ["Шахкулу Баба Текели, открыто поднявший восстание в 1510 году под воздействием сефевидской пропаганды в Анатолии, в марте 1511 года разгромил рынок Анталии, в апреле разбил османские силы в Кютахье и её окрестностях. В последнем сражении с великим визирем Хадым Али-пашой близ Сиваса обе стороны понесли тяжёлые потери; погибли и великий визирь, и предводитель восстания. Это восстание, потрясшее власть государства в Анатолии, обнажило вакуум власти последних лет Баязида II и стало сильнейшим доводом в пользу восшествия на престол шехзаде Селима.", "846180f5"]},
"OLAYLAR_EK5:1512-04-24:0":{"b": ["Отречение Баязида II и воцарение Селима Явуза", "c4cfab69"], "d": ["Под давлением шехзаде Селима, опиравшегося в борьбе с братьями за престол на поддержку янычар, Баязид II 24 апреля 1512 года отрёк от престола, и Селим I в тот же день взошёл на трон девятым османским правителем. Престарелый падишах умер по пути в родную Димотику, в деревне Abalar близ Чорлу, 25 раби аль-авваль 918 года (10 июня 1512). Тридцатиоднолетнее осторожное и замкнутое правление сменила эпоха Явуза, которая за восемь лет вдвое расширит границы империи.", "7194b8c2"]},
"OLAYLAR_EK5:1513-01-01:0":{"b": ["Завоевание крепости Синь", "83271ea5"], "d": ["Османские акынджи на боснийской границе взяли у Венгерского королевства крепость Синь, выдвинутую вглубь Далмации. Это было ранним звеном далматинской пограничной линии, которая будет расширена через девять лет завоеванием Гази Хусрев-беем Книна и окрестностей; крепость будет потеряна в пользу Венеции в 1686 году.", "28c20426"]},
"OLAYLAR_EK5:1513-04-01:0":{"b": ["Сражение при Yenişehir и устранение шехзаде Ахмеда", "e2ed15dd"], "d": ["Селим Явуз разбил на равнине Yenişehir близ Бурсы своего старшего брата шехзаде Ахмеда, сильнейшего соперника в борьбе за престол, и, взяв в плен, устранил его. Так братская распря, длившаяся с 1511 года, закончилась, и внутренний раскол в Анатолии прекратился. Селим, обезопасив тыл, получил свободу обратиться к сефевидскому вопросу.", "ed5f5ec0"]},
"OLAYLAR_EK5:1514-09-06:0":{"b": ["Вступление Селима Явуза в Тебриз", "dad2e227"], "d": ["После Чалдыранской победы османская армия вошла в сефевидскую столицу Тебриз, и в городе хутба была прочитана от имени падишаха. Селим пробыл здесь неделю и велел перевезти часть тебризских мастеров и улемов в Стамбул; этот перевоз глубоко повлияет на османское дворцовое искусство. Хотя город был оставлен из-за приближения зимы и недовольства янычар, сефевидское превосходство на Востоке было сломлено. Места, перешедшие к османам в этот день на карте, не соприкасаются друг с другом, и это верно: Тебриз — девятидневная оккупация армией; равнина Эрзинджана сдалась в походе без боя, а крепость Kemah посреди неё держалась у сефевидов до 19 мая 1515 года; Сиирт взял обратно у сефевидов хасанкейфский мелик Халил-бей, подчинившийся османам, будучи освобождённым в Тебризе из заключения Шаха Исмаила — окружающий его Диярбакыр оставался сефевидским до 1515 года, Хасанкейф — до 1517 года.", "3f65211e"]},
"OLAYLAR_EK5:1515-02-25:0":{"b": ["Муш и Бингёль (Çapakçur) перешли от Сефевидов к османскому управлению", "b0a53b5a"], "d": ["После Чалдырана с взятием Восточной Анатолии у Сефевидов Муш в 921/1515 году вошёл под османское управление; соседний Çapakçur (Бингёль) в том же процессе был присоединён к Османам.", "9c979b3f"]},
"OLAYLAR_EK5:1515-05-19:0":{"b": ["Завоевание крепости Kemah у Сефевидов", "73fd8671"], "d": ["Селим Явуз, зимовавший в Амасье после возвращения из Чалдыранского похода, поручил Бийикли Мехмед-паше завоевание укреплённой крепости Kemah, державшей переправу через Евфрат. В конце осады, в которой лично участвовал падишах, крепость была отнята у сефевидов, и ворота Восточной Анатолии открылись. Это завоевание — первый конкретный шаг, превративший Чалдыранскую победу в постоянное территориальное приобретение.", "9e896ebe"]},
"OLAYLAR_EK5:1515-06-13:0":{"b": ["Победа при Turnadağ — бейлик Дулкадириды стал подвластным османам", "fd879145"], "d": ["Османские силы разбили Дулкадирского бея Алаэддевле Бозкурта, занимавшего двойственную позицию во время Чалдыранского похода, в местности Ördekli между Göksun и Andırın; Алаэддевле в этом сражении был убит. Бейлик в эту дату не был присоединён: после Алаэддевле во главе бейлика Дулкадириды Селимом Явузом был поставлен Али-бей Шехсуваролу, и страна с центром в Мараше — Эльбистане продолжала существовать как подвластный османам бейлик. Так буфер на мамлюкской границе перешёл под османский контроль, и путь для египетского похода, состоявшегося два года спустя, был открыт; присоединение же произойдёт после убийства Али-бея.", "cf9c7460"]},
"OLAYLAR_EK5:1515-09-19:0":{"b": ["Завоевание Амида (Диярбакыр) и учреждение бейлербейства Диярбакыр", "a6867d5b"], "d": ["После того как Идрис Битлиси привлёк на сторону османов суннитских курдских беев региона, сефевидские силы не выдержали долгой осады, и ключи Амида были переданы Бийикли Мехмед-паше. Город стал центром вновь созданного бейлербейства Диярбакыр. Так административное ядро Верхней Месопотамии оказалось в османских руках.", "70169bcc"]},
"OLAYLAR_EK5:1516-03-26:0":{"b": ["Завоевание Харпута — открытие дороги на Диярбакыр", "564eb269"], "d": ["Караманский бейлербей Хусрев-паша, выступивший, чтобы спасти от сефевидской осады взятый после Чалдырана Диярбакыр, после трёхдневной осады взял крепость Харпут, окрестности которой ранее занял Черкес Хусейн-бей. Дорога к востоку от Евфрата, ведущая к Диярбакыру, таким образом была обеспечена.", "eb738178"]},
"OLAYLAR_EK5:1516-05-01:0":{"b": ["Сражение при Koçhisar (Kızıltepe) — поражение Кара-хана", "9ea9e843"], "d": ["Османская армия под командованием Бийикли Мехмед-паши разбила сефевидского наместника Кара-хана в целодневном полевом сражении в местности Koruk степи Dede Garkın близ Koçhisar; отрубленная голова Кара-хана была отправлена в лагерь падишаха. После этого османские силы вошли в город Мардин, но, пробыв несколько дней, ушли; крепость Мардина, удерживавшаяся сефевидскими гарнизонами, была принята лишь год спустя. Эта победа, обеспечив южную границу Явуза, позволила ему обратиться к походу на Египет. В тот же день присоединено также: Palu, Çemişgezek, Siverek.", "6bc19ce1"]},
"OLAYLAR_EK5:1516-06-05:0":{"b": ["Выступление Селима Явуза из Стамбула в Египетский поход", "ac258b4b"], "d": ["Селим Явуз, внешне готовясь к новому восточному походу против сефевидов, выступил из Стамбула и направился на юг через Акшехир. Установление мамлюкским султаном Кансухом аль-Гаври контактов с шахом Исмаилом и угроза восточному флангу османов должны были вскоре привести к смене цели. Поход продлится два года; это начало большой кампании, которая превратит Османскую империю в ближневосточную.", "6b27f782"]},
"OLAYLAR_EK5:1516-06-20:0":{"b": ["Взятие Забида: первый выход османских мореходов в Красное море", "38740e0c"], "d": ["Мореходы османского происхождения Хусейн-бей и Салман-реис, посланные в Красное море по просьбе мамлюкского султана Кансуха аль-Гаври из-за давления Португалии в Индийском океане, взяли Забид своими флотами. Эта операция, ещё проводившаяся на мамлюкской службе, — первое фактическое присутствие османского флота на линии Красное море — Индия. Через год, когда Египет перейдёт к османам, тот же флот будет напрямую подчинён Стамбулу.", "f715b0aa"]},
"OLAYLAR_EK5:1516-07-30:0":{"b": ["Официальное объявление целью похода мамлюков и Алеппо", "689e310d"], "d": ["Селим Явуз, когда Кансух аль-Гаври, договорившись с сефевидами, двинул армию на Алеппо, открыто объявил целью похода мамлюкского султана и Алеппо. Так многолетнее скрытое соперничество двух суннитских государств превратилось в открытую войну. Это объявление запустило четырёхнедельный обратный отсчёт до Мардж-Дабика.", "f2a137f3"]},
"OLAYLAR_EK5:1516-08-02:0":{"b": ["Неудача осады Адена: первая попытка в Красном море против Португалии", "8ffd46f2"], "d": ["Салман-реис и Хусейн-бей вели восьмидневную осаду Адена, ворот Красного моря в Индийский океан, чтобы взять его, но перед мощными укреплениями города вынуждены были отойти. Невзятие Адена на долгие годы нарушит южную стратегию против Португалии. Эта попытка — первое испытание османской океанской политики.", "8b584b76"]},
"OLAYLAR_EK5:1516-08-24:0":{"b": ["Присоединение бейлика Рамазаниды к Османской империи", "cfaa3754"], "d": ["Во время пожалований после победы при Мардж-Дабике бейлик Рамазаниды с центром в Адане был передан Махмуд-бею и взят под османское владычество. Бейлик, вышедший из подчинения мамлюкам, был не упразднён, а оставлен семье со статусом «оджаклык»; Рамазаниды продолжали управлять Чукуровой в качестве османских санджак-беев. Этот привилегированный порядок продолжался до 1608 года, когда Пир Мансур оставил бейлик. В тот же день присоединено также: Малатья, Тарс, Мосул, Антеп.", "af7c4758"]},
"OLAYLAR_EK5:1516-08-28:0":{"b": ["Переход Алеппо, Ракки и Дейр-эз-Зора под османскую власть", "2088eb6a"], "d": ["Через четыре дня после Мардж-Дабика Селим Явуз без сопротивления вошёл в Алеппо, и в мечетях города хутба была прочитана от его имени. Столь быстрое падение Алеппо, считавшегося торговой и административной столицей Сирии, показывает, что мамлюкская власть в регионе рухнула. Взятие города разом открыло дорогу на Дамаск, а оттуда — в Египет. В тот же день присоединено также: Антакья, Ракка, Дейр-эз-Зор.", "6055ffc7"]},
"OLAYLAR_EK5:1516-08-29:0":{"b": ["Встреча с аббасидским халифом аль-Мутаваккилем III в Gökmeydan в Алеппо", "22979f42"], "d": ["Каирский аббасидский халиф аль-Мутаваккиль III, попавший в плен вместе с мамлюкской армией при Мардж-Дабике, был представлен в Алеппо в Gökmeydan перед падишахом, и Селим Явуз оказал ему большое уважение. Каирский халифат, с 1261 года являвшийся символической должностью в тени мамлюкских султанов, этой встречей фактически перешёл под османское покровительство. Халиф позднее будет увезён вместе с падишахом в Стамбул.", "b1490892"]},
"OLAYLAR_EK5:1516-09-26:0":{"b": ["Переход Триполи и Хамы под османское управление", "a1e19a79"], "d": ["После Алеппо и Хамы без сопротивления перешёл под османское управление и сирийский Триполи. Город, один из самых оживлённых портов Восточного Средиземноморья, был морскими воротами Дамаска и центром торговли шёлком и сахаром. С его взятием прибрежная полоса Билад аш-Шама целиком сменила владельца.", "57168655"]},
"OLAYLAR_EK5:1516-09-27:0":{"b": ["Переход Дамаска под османскую власть", "2b844d91"], "d": ["Селим Явуз, перед которым после Алеппо открылся путь сдачей Хамы и Хомса, 27 сентября подошёл к Дамаску; не войдя сразу в город, он разбил шатёр снаружи в местности Mastaba и на двенадцатый день после прибытия торжественно вступил внутрь. Пробыв в Дамаске долго, он устроил административное управление Сирией и велел построить гробницу Мухйиддина Ибн Араби. Так весь Билад аш-Шам вышел из-под мамлюкского управления. В тот же день присоединено также: Бейрут.", "7cd1cd2b"]},
"OLAYLAR_EK5:1516-10-10:0":{"b": ["Провозглашение Туманбая мамлюкским султаном в Каире", "6020d90d"], "d": ["После смерти при Мардж-Дабике Кансуха аль-Гаври мамлюкские эмиры возвели на престол Туманбая, которому предстояло стать последним султаном государства. Новый султан, черкесского происхождения, принял государство, потерявшее Сирию, с истощённой казной и без огнестрельного оружия. Тем не менее он построит линию обороны перед Каиром и организует последнее сопротивление османскому продвижению.", "c55b45e9"]},
"OLAYLAR_EK5:1516-12-21:0":{"b": ["Сражение при Газе (Хан-Юнус): поражение Джанбирди аль-Газали", "9f1eb8cb"], "d": ["Селим Явуз отправил великого визиря Хадым Синан-пашу с авангардом в четыре тысячи человек к Газе. Джанбирди аль-Газали, назначенный Туманбаем наибом Дамаска, пытался остановить османский авангард на линии Газа — Хан-Юнус, но потерпел тяжёлое поражение и бежал в Египет. С рассеянием последней мамлюкской буферной силы в Палестине дорога к пустыне Синай была полностью открыта.", "042a934e"]},
"OLAYLAR_EK5:1516-12-28:0":{"b": ["К востоку от Иордана: переход Аммана под османское управление", "9db62667"], "d": ["После сражения за Газу османские силы, готовившиеся к египетскому походу, двигаясь на юг, вошли в Амман к востоку от Иордана. Прибрежные и внутренние города Палестины (Яффа, Наблус, Сайда, Акка, Иерусалим) уже сменили владельца осенью 1516 года, после Мардж-Дабика. Эти города на четыре века стали управляться как санджаки эялета Дамаск.", "fac75355"]},
"OLAYLAR_EK5:1516-12-29:0":{"b": ["Прибытие Селима Явуза в Иерусалим", "66d7bfad"], "d": ["В Иерусалим, без сопротивления перешедший под османское управление после Мардж-Дабика, после сражения при Газе прибыл Селим Явуз с сановниками государства и войском. Падишах посетил Купол Скалы и мечеть Аль-Акса, подтвердив священный статус города. Иерусалим с этой даты до декабря 1917 года, целых четыре века, останется под османским управлением.", "42cf2ec1"]},
"OLAYLAR_EK5:1517-01-02:0":{"b": ["Вступление Селима Явуза в Газу и движение к пустыне Синай", "2106bfc7"], "d": ["После поражения Джанбирди аль-Газали при Хан-Юнусе (21 декабря 1516) Газа находилась в руках авангарда. Падишах 2 января 1517 года вступил в Газу, встретившись здесь с Синан-пашой, стоявшим во главе авангарда, и армия сделала последние приготовления к переходу в Египет. По безводной пустыне Катья (Синай), тянущейся от Газы до Салихии, предстояло идти восемь переходов, перевозя воду на верблюдах. Этот переход — самая рискованная и самая сложная в логистическом отношении фаза похода.", "5c3d7bc1"]},
"OLAYLAR_EK5:1517-01-24:0":{"b": ["Взятие Суэца — ворота в Красное море", "05f3324e"], "d": ["После победы при Ридании, с вступлением османских войск в Каир, Суэц на северной оконечности Красного моря перешёл под османское управление. Этот порт-верфь, откуда мамлюки отправляли флот в Индийский океан, стал базой южной политики против Португалии. Суэц — северное устье линии, по которой три века спустя будет открыт канал.", "501facb1"]},
"OLAYLAR_EK5:1517-01-24:1":{"b": ["Первое вступление османских частей в Каир", "0a3f4f4d"], "d": ["На следующий день после победы при Ридании османским армиям было разрешено войти в Каир, и 24 января части расположились в городе. Однако это вступление не означало полного контроля над городом; Туманбай отошёл в Верхний Египет, мамлюкское сопротивление ещё не было сломлено. Завоевание Каира завершится не за один день, а в кровавом процессе, растянувшемся на недели.", "32d9401c"]},
"OLAYLAR_EK5:1517-01-27:0":{"b": ["Набег Туманбая на Каир и трёхдневные уличные бои", "b83b6ce6"], "d": ["Туманбай, отошедший в Верхний Египет, в ночь с 27 на 28 января с примерно семью тысячами человек внезапно вошёл в Каир, начал сопротивление в городе и поставил османские части в крайне трудное положение. В трёхдневных ожесточённых уличных боях мамлюки временно удерживали большую часть города. Сопротивление удалось сломить лишь с вводом османской артиллерии и подкреплений.", "98838d21"]},
"OLAYLAR_EK5:1517-02-08:0":{"b": ["Переход Джанбирди аль-Газали на османскую службу", "a94ea459"], "d": ["Бывший мамлюкский эмир Джанбирди аль-Газали, отошедший в Салихию после Ридании, обратился к падишаху и попросил пощады. Селим Явуз принял его на службу, рассудив, что он будет полезен в установлении порядка в Египте и Сирии. Этот выбор — первый крупный пример османской политики включения мамлюкских кадров в систему вместо их ликвидации.", "847c1e81"]},
"OLAYLAR_EK5:1517-02-15:0":{"b": ["Торжественное вступление Селима Явуза в Каир и чтение хутбы", "6d98080c"], "d": ["После подавления уличных боёв падишах 15 февраля 1517 года с очень пышной церемонией вступил в Каир, и в мечетях хутба была прочитана от его имени. Чтение хутбы в Каире от имени османского султана — объявление о юридическом конце мамлюкского владычества, длившегося с 1250 года. Эта дата считается символическим моментом завершения фактического завоевания Египта.", "3f8589a3"]},
"OLAYLAR_EK5:1517-03-30:0":{"b": ["Пленение последнего мамлюкского султана Туманбая в Terrûce", "7058e6ad"], "d": ["Туманбай, скрывавшийся в дельте Нила после ухода из Каира, был выдан бедуинами, давшими ему приют, и взят в области Terrûce. Его пленение уничтожило организованный центр мамлюкского сопротивления. Последний султан после этого четырнадцать дней будет находиться в османских руках.", "5fc98f13"]},
"OLAYLAR_EK5:1517-04-13:0":{"b": ["Казнь Туманбая у Баб Зувейла и конец Мамлюкского государства", "ad9820be"], "d": ["Через четырнадцать дней после пленения Туманбай был повешен у Баб Зувейла, знаменитых ворот Каира; позднее его тело было погребено в медресе, построенном его дядей. Так Мамлюкское государство, с 1250 года правившее Египтом и Сирией, официально исчезло из истории. Со сломом сопротивления под османское управление перешли и города Верхнего Египта (Саид), такие как Асьют и Асуан.", "96555946"]},
"OLAYLAR_EK5:1517-04-18:0":{"b": ["Нападение португальского флота на Джидду и оборона Салман-реиса", "52322cf5"], "d": ["Португальский флот из примерно тридцати галер и галеонов напал на Джидду; Салман-реис, руководя обороной города, не дал врагу высадиться и потопил несколько португальских кораблей. Эта оборона предотвратила переход порта Мекки, а значит и паломнического пути, в руки христианского государства. Джидда через несколько месяцев официально будет включена в османское управление присягой Хиджаза.", "a480f1f5"]},
"OLAYLAR_EK5:1517-05-19:0":{"b": ["Принятие Александрии с флотом — завершение завоевания Египта", "386878fe"], "d": ["Ровно через четыре месяца после Ридании и через тридцать шесть дней после казни Туманбая Александрия перешла под османское управление с приходом в порт османского флота под командованием Джафер-бея; дельтовые порты вроде Рашида и Дамьетты были присоединены в тот же процесс. То, что этот большой порт Египта на Средиземном море был принят спустя месяцы после падения Каира и не с суши, а с моря, ясно показывает, что завоевание было завершено не одним сражением, а область за областью. Александрия отныне станет жизненно важным портом, связывающим Стамбул с Каиром. В тот же день присоединено также: Рашид (Розетта).", "52187c14"]},
"OLAYLAR_EK5:1517-07-06:0":{"b": ["Бескровное присоединение Хиджаза: присяга Абу Нумайи, сына шерифа Мекки", "c13b98c7"], "d": ["Явуз Султан Селим сначала думал направить войска для взятия Мекки и её окрестностей, но отказался от этого, когда мекканский эмир шериф Баракат заявил о своём повиновении. Двенадцатилетний сын Бараката Абу Нумайй прибыл в Каир с дарами отца и ключами от Мекки и был принят падишахом. Таким образом, Хиджаз присоединился к Османам не как автоматическое следствие Ридании, а через пять с половиной месяцев и без единого выстрела — мирным путём, через присягу. Другие населённые пункты, присоединённые в ту же дату: Таиф. Другие населённые пункты, утраченные в ту же дату: Хурма (к востоку от Таифа), Рабиг, Бадр.", "74c58fb7"]},
"OLAYLAR_EK5:1517-07-12:0":{"b": ["Принятие титула Хадим аль-Харамейн и хутба в Медине", "63b32b59"], "d": ["После второго приёма мекканской делегации Селим Явуз официально принял покровительство над Харамейном и стал использовать титул «Хадим аль-Харамейн аш-Шарифейн». Шериф Баракат, надев присланную ему почётную одежду, велел читать хутбу от имени падишаха; когда и мединская делегация отправилась в Стамбул, эмирство Бараката было подтверждено берате. Падишах отправил жителям Харамейна двести тысяч золотых и множество провианта, положив начало традиции сурре, повторявшейся каждый год. В тот же день присоединено также: Янбу, Табук.", "3b3bfd8f"]},
"OLAYLAR_EK5:1517-08-28:0":{"b": ["Переход Салман-реиса на османскую службу и передача политики в Красном море", "771da99a"], "d": ["Салман-реис, защищавший Джидду от португальцев, прибыл в Каир и предстал перед Селимом Явузом; хотя некоторое время он удерживался, в 1519 году он был вызван в Стамбул и обязался подготовить тридцать галер и несколько галеонов против португальской угрозы. Эта встреча — начало перехода политики в Красном море и Индийском океане от мамлюкского наследия под прямое подчинение Стамбулу. Османская империя теперь была не только средиземноморским государством, но и силой, ведущей океанскую политику.", "c87580bd"]},
"OLAYLAR_EK5:1517-09-10:0":{"b": ["Отъезд Селима Явуза из Каира и бейлербейство Хайр-бея", "8cd4fb23"], "d": ["Селим Явуз, пробыв в Египте около восьми месяцев и устроив административный, финансовый и военный порядок, покинул Каир; бывший алеппский наиб Хайр-бей, оттянувший левый фланг при Мардж-Дабике и ускоривший разгром мамлюков, как первый османский бейлербей Египта начал управление из Цитадели. Избрание правителя из мамлюков было сознательной политикой перехода, не позволявшей новому управлению казаться чужим местному населению. На обратном пути падишах увёз в Стамбул вместе с собой последнего аббасидского халифа аль-Мутаваккиля III и выдающихся мастеров и учёных Египта.", "c2b3bc7e"]},
"OLAYLAR_EK5:1517-09-11:0":{"b": ["Конец каирского Аббасидского халифата — предание о «церемонии передачи»", "1d357640"], "d": ["Селим Явуз, захватив Египет, привёз с собой в Стамбул попавшего в плен при Мардж-Дабике последнего халифа аль-Мутаваккиля III Алаллаха; Каирский Аббасидский халифат, с 1261 года бесправно существовавший в тени мамлюкских султанов, таким образом закончился. Знаменитое же предание о том, что халифат был передан Явузу на официальной церемонии в Айя-Софии, впервые встречается в конце XVIII века в труде д'Оссона и отсутствует во всех источниках эпохи Явуза. TDV İslâm Ansiklopedisi считает предание вымыслом, так как нет первоисточника, документирующего церемонию; однако отмечает и то, что для перехода халифата по шариату такой церемонии передачи не требовалось.", "86efdf28"]},
"OLAYLAR_EK5:1518-01-01:0":{"b": ["Эрзурум присоединён к османскому управлению — сефевидское влияние в Восточной Анатолии сломлено", "78d1be02"], "d": ["Хотя после победы при Чалдыране (1514) османское влияние в регионе возросло, полное взятие Эрзурума откладывалось до тех пор, пока не было сломлено иранское влияние; город перешёл под османское управление лишь в 1518-19 гг., после египетского похода. Эрзурум оказался под властью Сефевидов в 1502 г., когда шах Исмаил положил конец государству Ак-Коюнлу; так закончился этот шестнадцатилетний период. В 1534 г., во время похода на два Ирака (Ирокейн), будет учреждён бейлербейлик Эрзурум. В 1518-1519 гг. Ашкале вместе с областью Эрзурума перешёл под османское управление (день не подтверждён).", "41e2822f"]},
"OLAYLAR_EK5:1519-03-01:0":{"b": ["Начало джелалийских восстаний: восстание шейха Джелала Бозоклу", "99bd8a99"], "d": ["В области Бозок человек по имени шейх Джелал объявил себя махди и поднял восстание в окрестностях Токата; хотя восстание было подавлено, его имя на целый век стало названием всех разбойничьих и мятежных движений в Анатолии. Джелализм, соединившись в конце XVI века с распадом тимарной системы и демографическим давлением, превратился в самую затяжную проблему внутренней безопасности империи. Восстания привели в Анатолии к массовым переселениям, называемым «великим бегством».", "ec33f73b"]},
"OLAYLAR_EK5:1519-09-01:0":{"b": ["Присоединение Алжира к Османскому государству", "b8eba4c1"], "d": ["Хайреддин-реис, сопротивлявшийся испанскому давлению в Северной Африке, чтобы удержаться, обратился к Стамбулу и подарил Алжир падишаху, а хутба была прочитана от имени Селима Явуза. Так Алжир был официально присоединён к османским землям, а Хайреддину с титулом бейлербея были направлены войска и пушки. Это присоединение заложило основу многовекового османского морского господства в Западном Средиземноморье. В тот же день присоединено также: Константина, Шершель, Медеа (Titteri), Сетиф.", "42dac5d2"]},
"OLAYLAR_EK5:1520-09-21:0":{"b": ["Смерть Селима Явуза в Чорлу", "9fe83744"], "d": ["Селим I, более чем вдвое увеличивший за восемь лет территорию государства, 18 июля 1520 года выехал из Стамбула в новый поход; из-за большой опухоли на спине он не смог продвинуться дальше Чорлу. Несмотря на вмешательство лекарей, болезнь усилилась, и после двух месяцев безнадёжного лечения он умер здесь 8–9 шавваля 926 года (21–22 сентября 1520). Чалдыраном, Мардж-Дабиком и Риданией он остановил Иран и устранил Мамлюкское государство, принёс османам халифат и покровительство над Харамейном. Он оставил единственного сына — Сулеймана.", "39cccc63"]},
"OLAYLAR_EK5:1521-01-01:0":{"b": ["Переход острова Икария к османскому управлению", "6afa972b"], "d": ["Икария между Самосом и Хиосом с 1481 по 1521 год находилась под управлением родосских рыцарей-иоаннитов; первый османский период на острове начался в 1522 году и продолжался до 1822 года. В этот период за сбор и уплату налогов отвечал каймакам; как и на других островах Эгейского моря, сохранялся и местный совет старейшин (демогеронтия), временами вступавший в столкновение с османским управлением.", "7c6cc486"]},
"OLAYLAR_EK5:1522-01-01:0":{"b": ["Присоединение страны Дулкадир — эялет Дулкадир с центром в Мараше", "595c3c30"], "d": ["Страна Дулкадир, существовавшая после поражения при Turnadağ в 1515 году как зависимое от Османов бейлик, после убийства Şehsuvaroğlu Али-бея вместе с детьми в Artukova была непосредственно присоединена к османским землям и превращена в эялет с центром в Мараше. Область Bozok этого бейлика была подчинена османскому управлению как отдельный санджак. Так закончился почти двухвековой дулкадирский период Мараша, Elbistan, Göksun, Gürün, Zamantı и Darende; буферное бейлик на мамлюкской границе полностью исчезло.", "9b819db9"]},
"OLAYLAR_EK5:1522-05-29:0":{"b": ["Завоевание Книна", "a46d3117"], "d": ["В результате набегов боснийского санджак-бея Гази Хусрев-бея в 927–928 (1521–1522) годах к османскому управлению перешли ряд венецианских крепостей, прежде всего Книн, Скрадин и Островица; граница была отодвинута за вторую горную гряду. Эта цепь завоеваний заложила основу далматинского санджака, который будет завершён через пятнадцать лет взятием Клиса.", "21f9fbd5"]},
"OLAYLAR_EK5:1523-01-05:0":{"b": ["Уход рыцарей: передача Бодрума, Коса и Додеканеса", "ea01666e"], "d": ["По условиям сдачи Родоса рыцари-иоанниты оставили не только центр острова, но и все позиции, которые они удерживали двести лет. Крепость Бодрум (Сен-Пьер) на анатолийском берегу и острова Кос, Калимнос и Лерос таким образом без боя перешли под османское управление. С этой передачей, завершённой через две недели после падения Родоса, латинское присутствие в юго-восточном углу Эгейского моря полностью закончилось.", "bcbe8fa8"]},
"OLAYLAR_EK5:1524-01-01:0":{"b": ["Восстание Хаина Ахмед-паши в Египте", "b18bb805"], "d": ["Ахмед-паша, ожидавший великого визирата, но отправленный правителем в Египет, объявил в Каире о своей независимости, провозгласив себя «аль-Малик аль-Мансур султан Ахмед». Восстание было быстро подавлено, паша убит, но событие показало хрупкость центрального контроля в богатейшей провинции империи. После этого Ибрагим-паша отправился в Египет и подготовил знаменитый Египетский канун-наме, заново упорядочивший управление эялетом.", "35eb542c"]},
"OLAYLAR_EK5:1528-01-01:0":{"b": ["Присоединение Северной Боснии: Яйце и Баня-Лука", "8ec86cfa"], "d": ["Когда после Мохача рухнула венгерская оборонительная линия, боснийский санджак-бей Гази Хусрев-бей двинулся в долину Врбаса и взял последние боснийские крепости, остававшиеся в руках венгерского королевства. С падением Яйце и Баня-Луки эялет Босния на севере вышел к реке Сава, и возник хорватский фронт. Баня-Лука вскоре стала вторым центром эялета.", "1f634005"]},
"OLAYLAR_EK5:1529-09-08:0":{"b": ["Взятие Буды и передача её Запольяи", "fba4f89b"], "d": ["На пути к Венскому походу османская армия осадила и отвоевала Буду, перешедшую в руки Фердинанда, и сдала город находившемуся под османским покровительством венгерскому королю Яношу Запольяи. Так над Венгрией была создана модель буферного вассального королевства в габсбургско-османском соперничестве. Этот порядок продлится до 1541 года; после смерти Запольяи Буда будет превращена в непосредственный османский эялет.", "6777eb1d"]},
"OLAYLAR_EK5:1532-04-25:0":{"b": ["Кануни выступил в Германский поход — вызов Карлу V", "7c3d7055"], "d": ["После безрезультатной осады Вены и повторной осады Буды Фердинандом падишах выехал из Стамбула, чтобы на этот раз вызвать на полевое сражение непосредственно императора Карла V. В августе армия задержится из-за сопротивления малой крепости Кёсег, и поскольку император не вышел на бой, поход ограничится набегами. Этот поход подготовил почву для первого мира с Габсбургами, заключённого на следующий год.", "c3e6e378"]},
"OLAYLAR_EK5:1532-08-05:0":{"b": ["Германский поход и осада Кёсега", "8aec937a"], "d": ["Кануни выступил с армией на Австрию, чтобы вынудить Карла V к полевому сражению; малая крепость Кёсег, сопротивлявшаяся двадцать пять дней, задержала продвижение армии. Поскольку император не вышел на бой, акынджи ударили по окрестностям Вены, и в связи с приближением зимы армия вернулась. Поход не принёс территориальных приобретений, но посадил Габсбургов за стол переговоров и подготовил почву для мира следующего года.", "792fc40e"]},
"OLAYLAR_EK5:1533-01-01:0":{"b": ["Константинопольский договор — первый мир с Габсбургами", "b085767a"], "d": ["Падишах принял посла Фердинанда Корнелиуса и согласился на перемирие, и появился первый официальный мирный текст между Османской империей и Австрией. По договору Фердинанд согласился выплачивать ежегодную дань за удерживаемые им венгерские земли, австрийский эрцгерцог в протоколе был приравнен к великому визирю. Этот неравный статус был открытым выражением претензии османской дипломатии XVI века на превосходство.", "e51c434d"]},
"OLAYLAR_EK5:1534-06-01:0":{"b": ["Взятие Карса и открытие северо-восточной границы", "742e3101"], "d": ["Когда передовая колонна похода Irakeyn двигалась из Эрзурума на восток, крепость Карс, находившаяся в руках грузинского атабегства и лежавшая в развалинах со времён Тимура, была принята без сопротивления. Город, удерживая проход между дугой Аракса и Çıldır, считался ключом к северным воротам, открывающимся в Иран. Это приобретение стало первым звеном бейлербейлика Карс, который будет создан тридцать лет спустя, и Кавказской линии.", "b3a27cc8"]},
"OLAYLAR_EK5:1534-07-13:0":{"b": ["Первый вход в Тебриз — начало похода Irakeyn", "cf7ed4e3"], "d": ["Ибрахим-паша, шедший впереди в звании сердар-экрема, когда шах Тахмасп уклонился от полевого сражения и отошёл вглубь страны, вошёл в Тебриз, столицу Сефевидов, без сопротивления. Кануни также достиг города в сентябре; однако из-за наступившей зимы и слишком растянутой линии снабжения армия повернула в направлении Багдада, и Тебриз долго не удавалось удержать. Город, взятый вторично после Чалдыранской битвы, стал местом, где османы узнали, что на востоке завоевать легко, а удержать трудно.", "a303a9e4"]},
"OLAYLAR_EK5:1534-09-22:0":{"b": ["Завоевание Туниса Барбароссой", "d8754216"], "d": ["Капудан-паша Хайреддин Барбаросса, ударив флотом по берегам Италии, направился к Тунису, обратил в бегство хафсидского правителя Мулая Хасана и вошёл в город. Взятие Туниса благодаря его положению, контролирующему Сицилийский пролив, разом склонило баланс сил в Западном Средиземноморье в пользу османов. Однако это господство не продлится долго: Карл V на следующий год ответит большим флотом.", "b0aeb30e"]},
"OLAYLAR_EK5:1535-07-21:0":{"b": ["Потеря Туниса в пользу Карла V", "a691f0f8"], "d": ["Карл V большим походом при поддержке генуэзского и папского флотов взял Гулетту, затем захватил Тунис и вернул Мулая Хасана на престол под испанским покровительством. В город был поставлен испанский гарнизон, и продвижение османов в Центральном Средиземноморье было временно остановлено. Окончательное завоевание Туниса станет возможным лишь сорок лет спустя, в 1574 году.", "cbb995cd"]},
"OLAYLAR_EK5:1536-01-01:0":{"b": ["Поход Гази Хусрев-бея вдоль Савы: Босански-Брод и Ясеновац", "3740ec83"], "d": ["После взятия Яйце и Баня-Луки в 1528 году крепости по берегам Савы ещё некоторое время оставались на хорватско-славонской границе, подчинённой габсбургской короне. Гази Хусрев-бей, ставший в 1536 году в третий раз боснийским санджак-беем, в том же году, взяв Пожегу и окрестности, присоединил к османскому управлению и крепости Брод и Ясеновац на берегу Савы. Так северная граница Боснии вышла к Саве; область была завершена через два года взятием Дубицы.", "415f0592"]},
"OLAYLAR_EK5:1536-03-15:0":{"b": ["Казнь Макбула Ибрагим-паши", "348aa7b8"], "d": ["Ибрагим-паша, тринадцать лет бывший великим визирем, ближайшим другом Кануни и фактически вторым человеком государства, был казнён задушением во дворце, куда его пригласили на ифтар, без какого-либо объяснения причин. Позиция, занятая им в Ирақском походе, использование им титула «сераскер султан» и дворцовые расклады считаются повлиявшими на его смерть. Казнь — поворотный пункт, показывающий, что в османском центральном управлении у великих визирей не было абсолютной безопасности.", "a780f3de"]},
"OLAYLAR_EK5:1537-03-12:0":{"b": ["Завоевание крепости Клис и учреждение санджака Далмация", "6ffd4ebf"], "d": ["Кетхюда Гази Хусрев-бея, хорватского происхождения новообращённый Мурад-бей отнял у Венеции стратегическую крепость Клис, расположенную прямо к северу от Сплита. Сразу после завоевания Клис был сделан центром нового санджака и каза, охватывавших его окрестности; границы этого санджака в значительной степени очертили рамки османской Хорватии. Это завоевание, последовавшее через пятнадцать лет после Книна, завершило административный остов внутренней Далмации.", "8338f8aa"]},
"OLAYLAR_EK5:1537-08-25:0":{"b": ["Осада Корфу и война с Венецией", "11af95bd"], "d": ["После Апулийского похода османская армия высадила войска на Корфу и осадила сильную венецианскую крепость острова. Из-за неприступности крепости, тяжёлых потерь и погодных условий 6 сентября блокада была снята, и армия отошла. Хотя осада оказалась безрезультатной, война, начатая с Венецией, закончилась присоединением к османам множества островов в Эгейском и Адриатическом морях и победой при Превезе на следующий год.", "f023c2b9"]},
"OLAYLAR_EK5:1537-10-01:0":{"b": ["Поход Барбароссы в Эгейское море: взятие островов, непосредственно управлявшихся Венецией", "1b32ed96"], "d": ["Флот, вернувшийся от осады Корфу, воспользовавшись объявлением войны Венеции, один за другим принял в Эгейском море острова, подчинённые не герцогству, а непосредственно Венеции. Эгина была взята после яростного сопротивления, Астипалея, находившаяся в руках семьи Кверини, а также Карпатос и Кассос сдались, а Патмос, находившийся под управлением монастыря, также принял османское покровительство. Наксосское герцогство было обложено данью и оставлено на месте; его присоединение должно было ждать 1566 года.", "632f4747"]},
"OLAYLAR_EK5:1538-08-01:0":{"b": ["Поход Барбароссы на север Эгейского моря: взятие Скироса и Северных Спорад", "20ab688e"], "d": ["На пути к Превезе флот один за другим принял острова северной части Эгейского моря, которые после завоевания Стамбула укрылись под Венецией. Скирос к северу от Негропонта и Скиатос, Скопелос и Алонисос, держащие вход в Салоникский залив, таким образом перешли под османское управление. Эти острова закрыли последний северо-эгейский пробел, остававшийся у Венеции ещё шестьдесят восемь лет после того, как Негропонт был взят в 1470 году.", "2a9ea08f"]},
"OLAYLAR_EK5:1538-08-03:0":{"b": ["Взятие Адена и присоединение побережья Йемена", "e7d46d8f"], "d": ["Флот, вышедший из Суэца в Индийский поход, сначала направился к берегу Йемена, поскольку нельзя было выйти в океан, не обезопасив Красное море. Хадым Сулейман-паша 3 августа 1538 года вошёл в порт Аден; правитель Тахиридов Амир ибн Дауд, склонявшийся к португальцам, был приведён к капитанскому порогу и казнён, а в городе оставлен гарнизон в 500 человек. Во время того же похода были приняты Моха и острова Камаран и Фарасан, господствующие над проливом, и заложена основа бейлербейлика Йемен. Так Османское государство впервые овладело всем северным берегом Баб-эль-Мандеба; Сана и внутренние области должны были ждать ещё девять лет.", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["Молдавский поход и присоединение области Буджак (Бендеры)", "90a88a56"], "d": ["В походе против молдавского воеводы Петру Рареша, не выполнявшего османские обязательства, была взята Сучава, город Яссы был разграблен крымским ханом Сахиб Гиреем. Падишах поставил воеводой Стефана Çekirge и присоединил к непосредственным османским землям Бендеры вместе с областью Буджак (Южная Бессарабия). Это присоединение стало одним из звеньев, превративших северо-западное побережье Чёрного моря во внутреннее море османов. Молдавия уже была подвластным османам воеводством; этот поход не отнял землю у иностранного государства, а лишь изъял внутреннее управление Бендер и Буджака у воеводы и подчинил непосредственно падишаху; остальная часть воеводства сохранила подвластный статус. Та же структура повторится в 1484 году в Килии и Аккермане и в 1713 году в Хотине: пограничные крепости — непосредственно, внутренние земли — подвластные.", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["Переход Нафплиона (Anabolu) по договору", "104d0937"], "d": ["Трёхлетняя война с Венецией после Превезы закончилась тем, что республика согласилась оставить последние две крепости в Морее. Анаболу, не взятый осадой, и Монемвасия были переданы Османам за столом переговоров, помимо военной контрибуции в триста тысяч дукатов. Так полуостров Морея стал цельным, так что не осталось ни одного венецианского следа.", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["Переход Сегеда под османское управление и создание ливы Сегед", "019aa000"], "d": ["После полного установления османского управления в Буде в 1541 году знатные люди Сегеда приняли власть Фердинанда I и приготовились к вооружённой обороне. Будинский бейлербей Кючюк Бали-паша в начале 1543 года вызвал к себе правителей города и казнил их по обвинению в измене, затем послал отряд занять город. В это время была создана лива Сегед, и первым санджак-беем был назначен сын Бали-паши Дервиш-бей; сначала лива простиралась между Дунаем и Тисой.", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["Завоевание Валпо, Шиклоша и Печа", "2ca030a3"], "d": ["Первой целью венгерского похода, предпринятого через два года после присоединения Буды, было обезопасить южный фланг нового эялета между Дравой и Дунаем. После взятия крепостей Valpo и Шиклош сдался центр Бараньи — Печ. Город станет самым многолюдным и наиболее благоустроенным центром османской Венгрии; от него получил своё прозвище историк Ибрахим Peçuylu.", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["Завоевание Эстергома и Секешфехервара", "efca9e05"], "d": ["В венгерском походе, в который Кануни выступил лично, после осады продолжительностью две с половиной недели под османское управление перешёл Эстергом, религиозный центр Венгерского королевства и город архиепископства. Затем был взят и Секешфехервар, город коронации венгерских королей, и оборонительный пояс эялета Буда был завершён. Эстергом до 1595 года оставался в османских руках как ключевая крепость дунайской линии.", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["Северный и западный оборонительный пояс Буды: Вац, Хатван и Шиманторня", "733ee5ce"], "d": ["После взятия Эстергома и Секешфехервара бейлербей Буды без падишахского похода двинулся, чтобы завершить кольцо крепостей вокруг столицы. Вац на излучине Дуная, Хатван — ворота Альфёльда, и Шиманторня на линии Шио были приняты одна за другой. Приобретения этого тихого года превратили Буду из пограничного города в центр эялета, которому предстояло продержаться сто сорок лет.", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["Присоединение Басры и выход к Персидскому заливу", "02f87c11"], "d": ["Во время завоевания Багдада (1534) правитель Басры Рашид ибн Мугамис заявил о подчинении Кануни, а в 1538 году прислал ключи от города. Сменивший его шейх Яхья выступил против османов, и багдадский бейлербей Аяс-паша двинулся по суше, а санджак-бей Мосула — с 120 судами по Евфрату; Аяс-паша вошёл в Басру 26 декабря 1545 года, и город стал центром бейлербейлика. Этот порт в устье Шатт-эль-Араба стал дверью, через которую османы вышли в залив, контролировавшийся Португалией из Ормуза; Амасийским договором 1555 года Иран также признал это положение.", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["Завоевание Саны и внутренних областей Йемена", "d31ded85"], "d": ["После Таиза была взята и Сана, и вся страна была подчинена бейлербейлику. Однако из-за крутой географии и различия мазхабов это господство никогда не было спокойным; Йемен превратился для Османов в фронт, постоянно поглощавший солдат.", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["Завоевание Таиза", "d4509df9"], "d": ["В Йемене, где девять лет назад довольствовались прибрежной полосой, в связи с постепенным усилением зейдитских имамов в горной внутренней области силы Оздемир-паши поднялись на нагорье и взяли Таиз.", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["Константинопольский договор — пятилетний мир с Габсбургами", "41f81773"], "d": ["Между Османской империей и Габсбургами был подписан мир сроком на пять лет; Фердинанд согласился выплачивать ежегодно 30 000 дукатов за удерживаемые им венгерские земли. Договор юридически закрепил фактическое разделение Венгрии на три части. Обеспечение таким образом безопасности западного фронта дало Кануни возможность организовать новые походы на Иран.", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["Второй иранский поход и повторное взятие Тебриза", "e82365df"], "d": ["В походе, предпринятом по побуждению Алкас-мирзы, брата шаха Тахмаспа, восставшего против него и укрывшегося в Стамбуле, армия вторично вошла в Тебриз. Поскольку Сефевиды вновь не вступили в полевое сражение и отошли, выжигая землю, в городе удалось остаться лишь несколько недель. Поход окончательно показал, что Тебриз невозможно удержать, и обратил османскую стратегию к созданию постоянной пограничной линии, то есть к укреплению Вана.", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["Завоевание Вана и закрепление восточной границы", "fc8f930b"], "d": ["Крепость Ван, осаждённая на обратном пути из Тебриза, благодаря своему положению на скале у восточного берега озера была бесспорным ключом области и после короткой осады сдалась. Город сразу сделали центром бейлербейлика; к нему были присоединены санджаки Erciş, Adilcevaz и Hakkâri. В отличие от Тебриза, Ван удержали, и на протяжении четырёхсот лет он оставался самой дальней постоянной позицией османов на востоке.", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["Присоединение Эль-Хасы и Катифа — аравийский берег Залива", "f6701e60"], "d": ["После взятия Басры был занят Катиф, ставший передовым постом Португалии на западном берегу залива, и вместе с оазисами Эль-Хасы во внутренней части был создан новый бейлербейлик. Отсюда начинались походы на Бахрейн и Ормуз. Так Османское государство получило право голоса на побережье Аравийского полуострова одновременно и на Красном море, и на Персидском заливе.", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["Утрата Шахризора — бей Ардалана Сухраб склонился к Сефевидам", "5600efc9"], "d": ["Область Шахризор, признавшая османское управление во время похода Irakeyn (1535), находилась под управлением ардаланского эмира Bige Bey, сидевшего в крепости Zalm. После смерти Bige Bey в 1550 году его брат Sührâb, захвативший крепость Zalm и овладевший беялыком, обратился к Сефевидам и отделился от повиновения османам; так область Шахризор вышла из-под османского влияния. Область была возвращена лишь во время Нахичеванского похода, в 1554 году, осадой и взятием крепости Zalm.", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["Взятие Ардагана и бассейна Çıldır", "14c9eb76"], "d": ["Эрзурумский бейлербей во время продолжавшейся войны с Сефевидами направился на земли грузинских атабегов по излучине Куры и подчинил османскому управлению Ардаган и окрестности Çıldır. Линия Карс–Ардаган таким образом была завершена, и нагорья, открывающиеся на северо-востоке к Грузии, были взяты под контроль. Окончательное административное устройство области будет завершено эялетом Çıldır, который будет создан через двадцать семь лет.", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["Соколлу Мехмед-паша перешёл Дунай — начало войны в Трансильвании", "38fde931"], "d": ["Из-за смут, вызванных монахом Мартинуцци, опекуном трансильванского короля Яноша Сигизмунда-младшего, и передачи Трансильванией банатских крепостей Фердинанду, был признан необходимым новый поход; командование было поручено румелийскому бейлербею Соколлу Мехмед-паше. Армия, несмотря на попытки Мартинуцци тянуть время, перешла Дунай и взяла Beçe, Beçkerek, Çanad и Липову; однако осада Тимишоары была снята 16 ноября из-за холодов. Так в Венгрии была открыта новая османско-габсбургская война.", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["Город Липова (Lippa) перешёл в руки австрийской армии Кастальдо — крепость сдалась 5 декабря", "a0e1ff0d"], "d": ["Липову, взятую Соколлу Мехмед-пашой в октябре 1551 года, армия генерала Кастальдо осадила 4 ноября; через два дня город перешёл в руки австрийцев. Улама-паша ещё девять дней оборонял крепость с гарнизоном в 5000 человек и 5 декабря 1551 года вышел по соглашению. До падения Тимишоары в 1552 году Липова оставалась в габсбургских руках.", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["Удержание отрядами, посланными из Темешвара, палланок Южного Баната — Вршац, Harám, Keve", "edca0921"], "d": ["После сдачи Темешвара османской армии части, отделившиеся от осадной армии, направились к малым палланкам Баната; по рассказу Банлаки, этими силами были заняты палланки Versec, Facset, Mehádia, Csákóvár, Haramvár и Keve. Так Харам на берегу Дуная также перешёл в османские руки.", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["Завоевание Сольнока и неудача осады Эгера", "a7156e8f"], "d": ["После взятия Тимишоары две соединившиеся османские армии почти без боя овладели Сольноком на Тисе, когда наёмные стражи оставили крепость. Затем осаждённая крепость Эгер не была взята из-за тридцативосьмидневного сопротивления двухтысячного гарнизона под командованием Иштвана Добо, и армия с наступлением зимы отошла. То, что в одном походе одна крепость легко пала, а другая устояла, было первым ясным признаком того, что граница в Венгрии более не продвигается сама собой в пользу османов.", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["Османо-французский союз — французский флот перешёл под османское командование", "a8e01b22"], "d": ["По договору от 1 февраля 1553 года французский флот был передан под команду османского флота; предусматривались совместные действия против Испании в Западном Средиземноморье. После договора Тургут-реис 15 июня 1553 года выступил в поход с сорока пятью галерами для поддержки Франции. Это был первый официальный союзный договор, перенёсший торговую основу капитуляций 1536 года в военное сотрудничество.", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["Казнь шехзаде Мустафы в Konya Ereğlisi", "dec36858"], "d": ["Шехзаде Мустафа, вошедший в шатёр отца, чтобы присоединиться к армии, собранной для Нахичеванского похода, при входе на аудиенцию столкнулся с палачами и был убит удушением. Убийство кандидата в наследники, пользовавшегося большой любовью в армии, вызвало глубокий гнев среди янычар, Рустем-паша был снят с поста великого визиря. Событие вошло в литературу и народную память как один из самых спорных переломов османской политики в отношении шехзаде.", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["Перенос границы Ибрим–Нубия к югу", "c57d5d77"], "d": ["Южная граница бейлербейлика Египет была перенесена за второй порог после того, как крепость Ибрим, поднимающаяся на скалистом мысу на Ниле, была укреплена руками Оздемир-бея и Нижняя Нубия полностью присоединена к османскому Египту. (В Ибриме османская административная организация была создана после завоевания Египта; на карте Ибрим показывается османским с 1517 года. Этот год приблизителен, источник года не даёт.) Крепость была и преградой против набегов из Нубии, и контрольным пунктом пути золота и рабов к Сеннару. Боснийский гарнизон, поселённый здесь, оказался настолько долговечным, что потомки его всё ещё находились в крепости три века спустя. Источники дают два разных рассказа о времени перехода Ибрима под османское управление: статья TDV о Судане связывает присоединение Нижней Нубии к османскому Египту с операцией Оздемир-паши в середине XVI века, а статья о Нубии пишет, что область до долины Вади-Хальфа и административная организация в Ибриме были созданы сразу после завоевания 1517 года. Санджак Ибрим 26 июля 1573 года был присоединён к эялету Хабеш.", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["Взятие Беджаии (Bougie) у испанцев", "49691cda"], "d": ["Беджаия, сорок три года находившаяся в руках Испании и разрезавшая побережье между Алжиром и Константиной надвое, сдалась после осады с суши и с моря. С падением крепости побережье алжирского оджака стало непрерывным до самого Орана. Эта потеря вызвала в Испании такое негодование, что командир Алонсо де Пералта, сдавший крепость, был казнён на родине.", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["Присоединение Зейлы к эялету Хабеш", "7bbf369a"], "d": ["На южной оконечности эялета Хабеш порт Зейла на африканском берегу Аденского залива был подчинён османскому управлению. Этот город, бывший морскими воротами Адальского султаната, был последним пунктом снабжения для судов, выходящих за пределы Баб-эль-Мандеба. С присоединением Зейлы граница Османского государства в Африке достигла самой южной точки.", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["Сражение шехзаде в Конье", "1c8de387"], "d": ["Шехзаде Баязид, вступивший в борьбу за престол, подошёл к Конье с примерно 30 000 войска и в двухдневных боях потерпел поражение от брата шехзаде Селима. Разбитый Баязид через Амасью бежал в Иран, к шаху Тахмаспу. Сражение превратило кризис престолонаследия в последние годы Кануни во вопрос внешней политики.", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["Морская победа при Джербе", "c7b905c1"], "d": ["Османский флот под командованием Пияле-паши рассеял у Джербы союзный испано-генуэзско-мальтийский флот, собранный для возвращения Триполи, манёвром разделения надвое. Союзники потеряли большую часть флотов, и крепость на острове вскоре пала. Джерба считается второй после Превезы большой морской победой, закрепившей османское превосходство в Средиземном море.", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["Казнь шехзаде Баязида в Казвине", "a759de14"], "d": ["Шехзаде Баязид, укрывшийся в Иране, после долгих торгов был передан шахом Тахмаспом османской делегации и убит удушением вместе с четырьмя сыновьями. В обмен на выдачу сефевиды получили важные материальные уступки и гарантии границы. Этой казнью было устранено последнее препятствие на пути Селима II к престолу, и мирный порядок Амасийского мира был сохранён.", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["Взятие Хиоса у генуэзцев", "a4559b96"], "d": ["Хиос, двести лет управлявшийся как торговая колония генуэзской семьи Джустиниани и платившая дань Османам, был принят Пияле-пашой без единого выстрела под предлогом задержки дани и предоставления гавани вражеским кораблям. Вместе с Хиосом и Псарой было ликвидировано последнее генуэзское присутствие на восточном берегу Эгейского моря. Производство мастики хиосцами и их привилегии были сохранены, а остров подчинён эялету Cezâyir-i Bahr-i Sefîd.", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["Присоединение Наксосского герцогства — все Киклады", "68f0ec0b"], "d": ["Латинское Наксосское герцогство, существовавшее с 1207 года и платившее дань Османам с 1537 года, было упразднено под предлогом поступавших жалоб на последнего герцога Джакомо Криспо, притеснявшего своих подданных. Наксос, Парос, Değirmenlik, Андрос, Сирос, Миконос, Иос, Yamurgi и все Киклады вокруг них были одним решением взяты под непосредственное османское управление. Кануни некоторое время передал управление островами Иосифу Наси; так в центре Эгейского моря закончилось латинское господство, продолжавшееся три с половиной века.", "d4d7a143"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["Восстание в Йемене и йеменский поход Коджи Синан-паши", "c8218d8e"], "d": ["Зейдитский имам Мутаххар, восставший под предлогом принудительного сбора налогов, вырвал османское управление из большей части Йемена. Коджа Синан-паша, посланный из Стамбула, в ходе операции 1568–1570 годов после долгой осады взял Кавкабан и вновь установил османское господство в регионе. Поход имел жизненно важное значение для сохранения контроля над южными воротами Красного моря и торговым путём Индийского океана.", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["Оборонительный союз с Султанатом Ачех и помощь в Индийском океане", "8e835f24"], "d": ["Послы Ачеха, просившие помощи у Кануни против португальских нападений, после смерти падишаха под Сигетваром представили свою верность Селиму II, и с ним был подписан оборонительный договор. Падишах приказал отправить из Александрии пушки, ружья, боеприпасы и мастеров; для отправки в индийские воды были подготовлены семнадцать военных кораблей. Разрастание йеменского восстания помешало флоту выйти в путь, но османские артиллеристы и мастера, добравшиеся до Ачеха, оставили в регионе прочный след.", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["Высадка на Кипре: взятие Лимасола", "9074ccc9"], "d": ["Османская армия, высадившаяся на острове, без большого сопротивления овладела Лимасолом и на следующий день направилась к Ларнаке. Благодаря недовольству местного населения венецианским управлением и помощи османским силам и в Ларнаке не встретили серьёзного сопротивления; пристань Tuzla была сделана базой высадки войск и снаряжения. Венеция сосредоточила оборону в Никосии и Фамагусте; правитель Пафоса объявил о повиновении сердару лишь после падения Никосии.", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["Завоевание Никосии", "413d866b"], "d": ["После осады, начавшейся 25 июля 1570 года и длившейся сорок пять дней, Никосия, находившаяся под венецианским управлением столица Кипра, сдалась османской армии. Падение центра острова прижало венецианское сопротивление к крепости Фамагуста. Завоевание вызвало большой резонанс на Западе и ускорило процесс, ведущий к созданию флота Священной лиги под руководством папы.", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["Сдача Кирении — северный берег Кипра", "39fdeea5"], "d": ["Падение Никосии 9 сентября с истреблением жителей сломило сопротивление на севере Кипра. Крепость Кирения за горами Пентадактилос, узнав о судьбе столицы, через восемь дней сдалась на условиях, и гарнизону было разрешено покинуть остров. Венецианский флаг остался на острове лишь в Фамагусте; она продержится ещё одиннадцать месяцев.", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["Восстановление флота после Лепанто", "db51fe44"], "d": ["Первой задачей Кылыч Али-паши, назначенного капудан-пашой после разгрома при Лепанто, было воссоздание флота, понёсшего тяжёлые потери; верфи работали без перерыва всю зиму 1571–1572 годов. В июне 1572 года в Средиземное море вышел новый флот примерно из 250 галер и 300 добровольческих галер реисов. Это быстрое восстановление показало, что Лепанто не смогло окончательно сломить османскую морскую мощь.", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["Константинопольский договор с Венецией — признание Кипра", "4d08ef50"], "d": ["Венеция, оставшаяся одна после распада Священной лиги, заключила с османами отдельный мир, официально признав принадлежность Кипра Османской империи и согласившись выплатить военную контрибуцию. Договор ясно показал, что победа при Лепанто не принесла христианскому миру политических выгод. После этого Венеция семьдесят лет избегала прямой войны с османами.", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["Смерть Селима II", "c289f5ee"], "d": ["Селим II после падения около двух месяцев не мог выходить в диван и умер. Его смерть двенадцать дней хранилась в тайне во дворце, пока в Стамбул не прибыл старший сын Мурад из Манисы. В вопросе дня смерти источники расходятся: Селяники называет 15 декабря; Герлах, Мехмед б. Мехмед и Дженаби — 13 декабря.", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["Объявление о смерти Селима II и воцарение Мурада III", "84334d70"], "d": ["Смерть Селима II и воцарение Мурада III, привезённого из Манисы, были официально объявлены 22 декабря 1574 года. Новый падишах пробудет на престоле двадцать один год; его правление запомнится длинными иранскими войнами на Востоке, канунтом Долгой войны на Западе и порчей акче внутри страны. До смерти Соколлу Мехмед-паши в 1579 году в управлении государством сохранялся прежний порядок.", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["Битва при Эль-Ксар-эль-Кебире (Вади-эс-Сейль) — Абд аль-Малик, поддержанный османами, уничтожил португальскую армию", "21280dac"], "d": ["Абд аль-Малик, сев на престол Марокко при поддержке османов, уничтожил при Вади-эс-Сейле большую армию португальского короля Себастьяна; поскольку в сражении погибли сразу три государя, в западных источниках оно называется «битвой трёх королей». Военная мощь Португалии рухнула, и страна вскоре перешла в руки Испании. Абд аль-Малик также погиб в сражении; сменивший его брат Ахмад аль-Мансур сообщил о победе в Стамбул через делегацию. Отношения между двумя государствами остались на уровне обмена послами и дарами, а не дани или подчинения, и вскоре обострились из-за вопроса о дарах.", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["Изъявление Дербентом верности Лала Мустафа-паше — Дербент (Demirkapı) под османским управлением", "9c55aeff"], "d": ["Во время ширванского похода делегация из семи человек от жителей Дербента отправилась к сердару Лала Мустафа-паше, находившемуся в Ereş, и изъявила верность. Дербент (Demirkapı), закрывающий узкий проход между Кавказским хребтом и Каспийским морем и являющийся обязательным проходом для сухопутных дорог с севера, играл ключевую роль в удержании Ширвана. Османское господство здесь продолжалось до 1607 года.", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["Завоевание Ширвана: взятие Шемахи", "9afae4c1"], "d": ["Армия, открывшаяся на Кавказе после победы при Çıldır, вошла в Ширван, самую богатую провинцию Сефевидов на каспийском берегу, и взяла центральный город Шемаху. Осман-паша Оздемироглу был назначен сюда бейлербеем, и северная ветвь Шёлкового пути оказалась под османским контролем. Ширван станет самым переходящим из рук в руки и самым дорогим фронтом двенадцатилетней восточной войны.", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["Взятие Баку — выход к берегу Каспия", "eb5adab8"], "d": ["Последним звеном ширванской операции был взят порт Баку на западном берегу Каспийского моря. Нефтяные колодцы вокруг города уже в ту эпоху были известным источником дохода, а порт служил пунктом вывоза иранского шёлка, шедшего через Каспий. Так Османское государство впервые и единственный раз в своей истории получило берег Каспийского моря.", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["Завоевание Эривани (Revan) и строительство крепости", "7f623b7b"], "d": ["Фархад-паша, получивший в Карсе приказ идти на Эривань и построить там крепость, двинулся на Эривань, и город в начале рамадана 991 года (середина сентября 1583 года) был взят под османский контроль. В Эривани, держащей северные ворота долины Аракса, была построена новая большая крепость; город был сделан центром бейлербейлика. Эривань, стоявшая посреди армейской дороги между Карсом и Тебризом, была логистическим хребтом восточного фронта. Крепость была построена настолько прочной, что в течение следующих двухсот лет она была неизменной целью османо-иранских войн.", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["Присоединение Карабаха и Гянджи", "29abaead"], "d": ["Как последнее приобретение десятилетней восточной войны Фархад-паша в 1588 году двинулся на Гянджу и 1 сентября вошёл в город; область Карабах между Курой и Араксом и её центр Гянджа были взяты под османское управление. Так Ширван, Эривань и Карабах соединились, и на Кавказе образовалась непрерывная османская линия. Договор Фархад-паши, подписанный в 1590 году, закрепит эту границу, но приобретение удастся удерживать лишь двадцать лет.", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["Завоевание Бихача", "651a7275"], "d": ["Боснийский бейлербей Телли Хасан-паша, взяв в ноябре 1591 года Рипач, передовую крепость Бихача, в 1592 году овладел и самим городом и крепостью; после десятидневной осады комендант Ламберг сдался. Это завоевание продвинуло боснийскую границу вдоль реки Уны и стало последним крупным османским приобретением накануне Долгой войны, которая вспыхнет через год с гибелью Телли Хасан-паши под Купой.", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["Начало османо-австрийской «Долгой войны»", "bd22c392"], "d": ["После того как боснийский бейлербей Телли Хасан-паша потерпел поражение и погиб как шахид под Купой (Сисак), Османское государство объявило войну Австрии, и началась Долгая война, которая продлится тринадцать лет. Эта война, в которой решающей была пехота с огнестрельным оружием, ускорила привлечение к службе секбанов и стрелков в османской армии и углубила упадок тимарной сипахийской конницы. Война закончится в 1606 году Житваторокским миром.", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["Коджа Синан-паша выступил в австрийский поход — первый поход Долгой войны", "d4a2f46d"], "d": ["После того как боснийский бейлербей Хасан-паша потерпел поражение и погиб как шахид под Сиской (Сисак), великий визирь Коджа Синан-паша блестящими речами и обещаниями убедил падишаха пойти на войну и выступил с 12 000 янычар и другими частями. Так открылся первый поход османо-австрийской войны, которая продлится тринадцать лет.", "0f217276"]}
});
